INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (378, 2310, 'B', 'HOLY WEEK', 'Wednesday in Holy Week', 'Scarlet or Violet', NULL, 'Is. 62:11-63:7', 'Psalm 70', 'Rom. 5:6-11', 'Luke 22:1-23:56 or John 13:38', NULL, NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (379, 2320, 'B', 'HOLY WEEK', 'Holy (Maundy) Thursday', 'scarlet or Violet', '<div><strong>Let Us Love One Another, as Christ Has Loved Us and Loves Us to the End</strong></div>\r\n\r\n<div>&quot;The Lord\'s Passover&quot; (Ex. 12:11) and &quot;the blood of the covenant&quot; at Mount Sinai (Ex. 24:8) are preeminent types of the Lord\'s Supper. The blood of Christ, the Lamb of God, now covers us, and we keep His Supper &quot;as a feast to the Lord&quot; (Ex. 12:13_14). In Him, we see &quot;the God of Israel&quot; (Ex. 24:10), and yet He does not lay His hand on us to punish us. As disciples of Jesus, we recline at the table with Him to eat and drink in peace (Mark 14:18). The apostles, who received the New Testament in His blood &quot;on the night when he was betrayed,&quot; delivered the same to His Church, which we also now receive in remembrance of Him (1 Cor. 11:23_26; Mark 14:22_25). So He has &quot;loved his own who were in the world,&quot; and He loves us &quot;to the end&quot; (John 13:1). As He thus feeds us in love, let us love one another, just as He has loved us (John 13:34). For &quot;we who are many are one body&quot; because &quot;we all partake of the one bread,&quot; which is the body of Christ (1 Cor. 10:17).</div>', 'Ex. 24:3–11', 'Psalm 116:12–19', '1 Cor. 10:16–17', 'Mark 14:12–26', '<div>Gracious is the LORD, and | righteous; *</div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;our God is | merciful.</strong></div>\r\n\r\n<div>I love the LORD, because | he has heard*</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>my voice and my pleas for | mercy.</strong></div>\r\n\r\n<div>Because he inclined his | ear to me, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>therefore I will call on him as long | as I live.</strong></div>\r\n\r\n<div>The snares of death encompassed me; the pangs of Sheol laid | hold on me; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>I suffered distress and | anguish.</strong></div>\r\n\r\n<div>Then I called on the name of the LORD: *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>&quot;O LORD, I pray, deliv- | er my soul!&quot;</strong></div>\r\n\r\n<div>Gracious is the LORD, and | righteous; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>our God is | merciful.</strong></div>', '<div>Entrance: 617 O Lord, We Praise Thee </div>\r\n\r\n<div>Of the Day: 445 When You Woke That Thursday Morning </div>\r\n\r\n<div>Offertory: 574 Before the Throne of God Above Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;622 Lord, Jesus Christ, You Have Prepared </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;641 You Satisfy the Hungry Heart </div>\r\n\r\n<div>Closing: None </div>', '<div>Stripping of the Altar while reading Ps. 22</div>');
