INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (383, 2360, 'B', 'EASTER', 'The Resurrection of Our Lord (Easter Sunrise)', 'White or Gold', NULL, 'Ex. 15:1–11', 'Psalm 118:15-29', '1 Cor. 5:6b–8', 'John 20:1–18', NULL, NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (384, 2370, 'B', 'EASTER', 'The Resurrection of Our Lord (Easter Day)', 'White or Gold', '<div><strong>The Risen Christ Has Swallowed Up Death Forever!</strong></div>\r\n\r\n<div>The entire fallen world is veiled in a funeral shroud &quot;that is spread over all nations&quot; and &quot;cast over all peoples&quot; (Is. 25:7). But the Lord of hosts, in the Person of the incarnate Son, Jesus Christ, has removed that terrible pall and swallowed up death forever. By submitting Himself to death, He burst it apart from the inside out. Now He wipes away all tears from our faces, and He invites us to &quot;be glad and rejoice in his salvation&quot; (Is. 25:9). His body and His blood, crucified and risen, are given and poured out for us as a feast &quot;of rich food full of marrow, of aged wine well refined&quot; (Is. 25:6). We enter that feast through Holy Baptism, whereby our old man is buried with Jesus Christ, and we are raised up in Him, &quot;dressed in a white robe&quot; of His perfect righteousness (Mark 16:5). What St. Paul and the other apostles received &quot;by the grace of God&quot; is also &quot;delivered to you&quot; by the preaching of Christ, &quot;in which you stand, and by which you are being saved&quot; (1 Cor. 15:1_11).</div>', 'Is. 25:6–9', 'Psalm 16', '1 Cor. 15:1–11', 'Mark 16:1–8', '<div>INTROIT Ex:15 2a,6,13,17-18, antiphon: Ex:15:1b</div>\r\n\r\n<div>I will sing to the LORD, for he has triumphed | gloriously; *</div>\r\n\r\n<div><strong>the horse and his rider he has thrown in- | to the sea.</strong></div>\r\n\r\n<div>The LORD is my strenght | and my song, *</div>\r\n\r\n<div><strong>and he as become my sal- | vation.</strong></div>\r\n\r\n<div>Your right hand O LORD, glorious | in power; * <strong>your right hand, O LORD, shatters the | enemy.</strong></div>\r\n\r\n<div>You have led you steadfast love the people whom you | have redeemed; *</div>\r\n\r\n<div><strong>you have guided them by your strenght to your ho- | ly abode.</strong></div>\r\n\r\n<div>You will bring them in and plat the on you own | mountain, *</div>\r\n\r\n<div><strong>the place, O LORD, which you have made for | your abode,</strong></div>\r\n\r\n<div>The sancuary, O LORD, which your hands have es- | tablished. *</div>\r\n\r\n<div>The LORD will reigh forever and | ever.</div>\r\n\r\n<div><strong>Glory be to the Father…</strong></div>\r\n\r\n<div>I will sing to the LORD, for he has triumphed | gloriously; *</div>\r\n\r\n<div><strong>the horse and his rider he has thrown in- | to the sea.</strong></div>', '<div>Entrance: 457 Jesus Christ Is Risen Today </div>\r\n\r\n<div>Of the Day: 467 Awake, My Heart, with Gladness </div>\r\n\r\n<div>Offertory: 463 Christ the Lord Is Risen Today; Alleluia </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;633 At the Lambâ€™s High Feast We Sing </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;474 Alleluia! Jesus Is Risen 466 Christ Has Arisen, Alleluia </div>\r\n\r\n<div>Closing: 478 The Day of Resurrection</div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (385, 2380, 'B', 'EASTER', 'The Resurrecition of Our Lord (Easter Monday)', 'White or Gold', NULL, 'Ex. 15:1-18 or Dan. 12:1c-3', 'Psalm 100', 'Acts 10:34-43 or 1 Cor. 5:6b-8', 'Luke 24:13–35(36-49)', NULL, NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (386, 2390, 'B', 'EASTER', 'The Resurrection of Our Lord (Easter Tusday)', 'White or Gold', NULL, 'Dan. 3:8-28', 'Psalm 2', 'Acts 13:26-33', 'Luke 24:36–49', NULL, NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (387, 2400, 'B', 'EASTER', 'The Resurrection of Our Lord (Easter Wednesday)', 'White or Gold', NULL, 'Acts 3:13-15, 17-19', 'Psalm 61', 'Col. 3:1-7 or 1 Cor. 11:23-26', 'John 21:1–14', NULL, NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (388, 2410, 'B', 'EASTER', 'Second S. of Easter', 'White', '<div>The Risen Christ Breathes His Peace in the Holy Absolution</div>\r\n\r\n<div>The crucified and risen Lord Jesus appeared to His apostles on the first Easter Sunday. He &quot;came and stood among them,&quot; and with His Word and the wounds in &quot;his hands and his side,&quot; He granted them His peace (John 20:19_20). He sent them as ministers of the Gospel in His name to bestow the life-giving Holy Spirit for us and for His whole Church through the forgiveness of sins (John 20:21_23). Through this apostolic ministry, He calls us to believe that He &quot;is the Christ, the Son of God,&quot; so that by such faith we &quot;may have life in his name&quot; (John 20:31). The apostles &quot;have seen and heard&quot; this divine life manifested in the flesh of Christ, and those who succeed them in this apostolic ministry now proclaim that same Absolution to us, so that we &quot;too may have fellowship&quot; with the risen Christ, with the apostles and &quot;with one another&quot; (1 John 1:1_7). The one, holy, catholic and apostolic Church lives by &quot;their testimony to the resurrection of the Lord Jesus,&quot; and all who believe this Word are &quot;of one heart and soul,&quot; because in Him they truly have &quot;everything in common&quot; (Acts 4:32_33).</div>', 'Acts 4:32–35', 'Psalm 148', '1 John 1:1—2:2', 'John 20:19–31', '<div>INTROIT &nbsp;&nbsp;&nbsp;&nbsp;ps. 105:1-5, 8; Anitphon 1 Pe 2:2-3</div>\r\n\r\n<div>Like newborn infants, long for the pure spiritual milk, that by it you may grow up to sal- | vation-- *</div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;if indeed you have tasted that the | Lord is good.</strong></div>\r\n\r\n<div>Oh give thanks to the LORD; call up- | on his name; *</div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;make known his deeds among the | peoples</strong></div>\r\n\r\n<div>Sing to him, sing prais- | es to him; *</div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;tell of all his | wondrous works!</strong></div>\r\n\r\n<div>Glory in his | holy name; *</div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;let the hearts of those who seek the | LORD rejoice!</strong></div>\r\n\r\n<div>Seek the LORD | and his strength; *</div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;seek his presence con- | tinually!</strong></div>\r\n\r\n<div>Remember the wondrous works that | he has done; *</div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;his miracles, and the judgements he | uttered.</strong></div>\r\n\r\n<div>He remembers his covenant for- | ever, *</div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;the word that he commanded, for a thousand gener- | ations.</strong></div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div><strong>Glory be to the Father…</strong></div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div>Like newborn infants, long for the pure spiritual milk, that by it you may grow up to sal- | vation-- *</div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;if indeed you have tasted that the | Lord is good.</strong></div>\r\n\r\n<div>&nbsp;</div>', '<div>Entrance: 487 Come, You Faithful, Raise the Strain </div>\r\n\r\n<div>Of the Day: 472 These Things Did Thomas Count as Real </div>\r\n\r\n<div>Offertory: 720 We Walk by Faith and Not by Sight </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;461 I Know That My Redeemer Lives </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;411 I Want to Walk as a Child of the Light </div>\r\n\r\n<div>Closing: 603 We Know That Christ Is Raised </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (389, 2420, 'B', 'EASTER', 'Third S. of Easter', 'White', '<div><strong>The Preaching of Repentance and Forgiveness of Sins Makes Us Pure</strong></div>\r\n\r\n<div>The risen Lord Jesus taught His disciples &quot;that the Christ should suffer and on the third day rise from the dead&quot; and &quot;that repentance and forgiveness of sins should be proclaimed in his name to all nations&quot; (Luke 24:46_47). Therefore, St. Peter preaches repentance and forgiveness to the people of Jerusalem. As he proclaims that Jesus fulfilled all that &quot;God foretold by the mouth of all the prophets&quot; (Acts 3:18), he also convicts the people of their sin, because they &quot;delivered over and denied&quot; this Lord Jesus and &quot;killed the Author of life.&quot; Yet God &quot;glorified his servant Jesus&quot; and raised Him from the dead (Acts 3:13_15). St. Peter calls the people to repent, so that their &quot;sins may be blotted out, that times of refreshing may come from the presence of the Lord&quot; (Acts 3:19_20). Through this forgiveness of sins and by faith in this forgiveness, the Father shows His love for us in order that &quot;we should be called children of God; and so we are&quot; (1 John 3:1). Thus, we hope in Him and are made pure even &quot;as he is pure,&quot; because &quot;he appeared in order to take away sins, and in him there is no sin&quot; (1 John 3:3, 5).</div>', 'Acts 3:11–21', 'Psalm 4', '1 John 3:1–7', 'Luke 24:36–49', '<div>INTROIT &nbsp;&nbsp;&nbsp;Ps 30:1-5; antiphon: Ps 16:11b</div>\r\n\r\n<div>In your presence there is full- | ness of joy; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>at your right hand are pleasures for- | evermore.</strong></div>\r\n\r\n<div>I will extol you, O LORD, for you have | drawn me up *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and have not let my foes rejoice | over me.</strong></div>\r\n\r\n<div>O LORD my God, I cried to | you for help *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and you have | healed me.</strong></div>\r\n\r\n<div>O LORD, you have brought up my soul | from Sheol; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>you restored me to life from among those who go down | to the pit.</strong></div>\r\n\r\n<div>Sing praises to the LORD, O | you his saints, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and give thanks to his | holy name.</strong></div>\r\n\r\n<div>For his anger is but for a moment, and his favor is for a | lifetime.*</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>Weeping may tarry for the night, but joy comes with the | morning.</strong></div>\r\n\r\n<div><strong>Glory be to the Father…</strong></div>\r\n\r\n<div>In your presence there is full- | ness of joy; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>at your right hand are pleasures for- | evermore.</strong></div>\r\n\r\n<div>&nbsp;</div>', '<div>Entrance: 483 With High Delight Let Us Unite </div>\r\n\r\n<div>Of the Day: 466 Christ Has Arisen, Alleluia </div>\r\n\r\n<div>Offertory: 949 Heavenly Hosts In Ceaseless Worship </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;464 The Strife Is O’er, the Battle Done </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;479 Christ Is Risen, Christ Is Living </div>\r\n\r\n<div>Closing: 490 Jesus Lives! The Victory’s Won </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (390, 2430, 'B', 'EASTER', 'Fourth S. of Easter', 'White', '<div><strong>Jesus, the Good Shepherd, Lays Down His Life for the Sheep</strong></div>\r\n\r\n<div>The Lord Jesus is &quot;the good shepherd&quot; who &quot;lays down his life for the sheep&quot; (John 10:11). His life is not taken from Him, but He lays it down willingly, of His own accord, because He knows and loves the sheep. As the One sent by the Father, He has the &quot;authority to lay it down&quot; and the &quot;authority to take it up again&quot; (John 10:18). So has He done, and now He continues to love and serve as the Good Shepherd of the sheep by the voice of His Gospel. He thus calls all people into the fold of His Church, so that there may be &quot;one flock, one shepherd&quot; (John 10:16). That is why the apostles &quot;were teaching the people and proclaiming in Jesus the resurrection from the dead&quot; (Acts 4:2). Since &quot;there is salvation in no one else,&quot; His voice rings out to this day through the preaching of His name, &quot;for there is no other name under heaven given among men by which we must be saved&quot; (Acts 4:12). His voice comforts our hearts against all condemnation and gives us courage to &quot;love one another&quot; and &quot;to lay down our lives for the brothers,&quot; as He laid down His life for us (1 John 3:16, 23).</div>', 'Acts 4:1–12', 'Psalm 23', '1 John 3:16–24', 'John 10:11–18', '<div>INTROIT &nbsp;Ps. 23; Antiphon John 10:14, 15b</div>\r\n\r\n<div><font size=3 color=black>I am the good | shepherd. *</font></div>\r\n\r\n<div><font size=3 color=black>&nbsp;&nbsp;&nbsp;&nbsp;<strong>I know my own and my own know me, and I lay down my life | for the sheep.</strong></font></div>\r\n\r\n<div><font size=3 color=black>The Lord is my | shepherd; *</font></div>\r\n\r\n<div><font size=3 color=black><strong>&nbsp;&nbsp;&nbsp;&nbsp;I | shall not want. </strong></font></div>\r\n\r\n<div><font size=3 color=black>He makes me lie down in green | pastures. *</font></div>\r\n\r\n<div><font size=3 color=black><strong>&nbsp;&nbsp;&nbsp;&nbsp;He leads me beside still | waters. </strong></font></div>\r\n\r\n<div><font size=3 color=black>He re- | stores my soul. </font></div>\r\n\r\n<div><font size=3 color=black><strong>&nbsp;&nbsp;&nbsp;&nbsp;He leads me in paths of righteousness for his | name’s sake. </strong></font></div>\r\n\r\n<div><font size=3 color=black>Even though I walk through the valley of the shadow of death, I will fear no evil, for you are | with me; * </font></div>\r\n\r\n<div><font size=3 color=black><strong>&nbsp;&nbsp;&nbsp;&nbsp;your rod and your staff, they | comfort me. </strong></font></div>\r\n\r\n<div><font size=3 color=black>You prepare a table before me in the presence of my | enemies; *</font></div>\r\n\r\n<div><font size=3 color=black>&nbsp;&nbsp;<strong>&nbsp;&nbsp;you anoint my head with oil; my cup &nbsp;|overflows.</strong> </font></div>\r\n\r\n<div><font size=3 color=black>Surely goodness and mercy shall follow me all the days | of my life, *</font></div>\r\n\r\n<div><font size=3 color=black><strong>&nbsp;&nbsp;&nbsp;&nbsp;and I shall dwell in the house of the Lord fo- | rever.</strong></font></div>\r\n\r\n<div><strong>Glory be to the Father…</strong></div>\r\n\r\n<div><font size=3 color=black>I am the good | shepherd. *</font></div>\r\n\r\n<div><font size=3 color=black>&nbsp;&nbsp;&nbsp;&nbsp;<strong>I know my own and my own know me, and I </strong></font></div>', '<div>Entrance: 710 The Lord’s My Shepherd, I’ll Not Want </div>\r\n\r\n<div>Of the Day: 709 The King of Love My Shepherd Is </div>\r\n\r\n<div>Offertory: 740 I Am Jesus’ Little Lamb </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;711 Savior, like a Shepherd Lead Us </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;641 You Satisfy the Hungry Heart </div>\r\n\r\n<div>Closing: 473 Our Paschal Lamb, That Sets Us Free </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (391, 2440, 'B', 'EASTER', 'Fifth S. of Easter', 'White', '<div>Jesus Christ Is the True Vine Who Bears Much Fruit in Us</div>\r\n\r\n<div>&quot;God is love,&quot; and He has manifested Himself to us by sending &quot;his only Son into the world, so that we might live through him&quot; (1 John 4:9, 16). By the ministry of the Gospel, &quot;he has given us of his Spirit,&quot; so that we also believe and confess &quot;that Jesus Christ has come in the flesh.&quot; In this way, we &quot;abide in him and he in us,&quot; and we &quot;love one another&quot; (1 John 4:2, 7, 13). Such divine love is exemplified in Philip\'s preaching of &quot;the good news about Jesus&quot; to the Ethiopian eunuch. And when &quot;they came to some water,&quot; the eunuch was baptized into the very Gospel that Philip had preached (Acts 8:35_38). That Ethiopian was thereby grafted into &quot;the true vine,&quot; Jesus Christ (John 15:1), just as we are. Already we are clean because of the Word that Christ has spoken to us and by the washing of water with His Word. We now abide in Him by faith in His forgiveness. As He abides in us, both body and soul, with His own body and His blood, He &quot;bears much fruit&quot; in us (John 15:3_5).</div>', 'Acts 6:1-9; 7:2a', 'Psalm 146', '1 Peter 2:2-10', 'John 14:1-14', '<div>INTROIT &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Ps. 145:1-2,8,10,21; antiphon: John 16:16</div>\r\n\r\n<div>A little while, and you will se me no | longer; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and again a little while, and you will | see me.</strong></div>\r\n\r\n<div>I will extol you, my | God and King, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and bless your name forever and |ever.</strong></div>\r\n\r\n<div>Every day I will | bless you*</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and praise your name forever and | ever.</strong></div>\r\n\r\n<div>The LORD is gracious and | merciful, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>slow to anger and abounding in | steadfast love.</strong></div>\r\n\r\n<div>All you works shall give than to you, | O LORD, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and all your saints shall | bless you!</strong></div>\r\n\r\n<div>My mouth will speak the praise | of the LORD, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and let all flesh bless his holy name forever and | ever.</strong></div>\r\n\r\n<div><strong>Glory be to the Father…</strong></div>\r\n\r\n<div>A little while, and you will se me no | longer; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and again a little while, and you will | see me.</strong></div>', '<div>Entrance: 474 Alleluia! Jesus Is Risen </div>\r\n\r\n<div>Of the Day: 595 O Blessed Spring </div>\r\n\r\n<div>Offertory: 768 To God the Holy Spirit Let Us Pray </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;633 At the Lamb’s High Feast We Sing; </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;540 Christ, the Word of God Incarnate </div>\r\n\r\n<div>Closing: 479 Christ Is Risen, Christ Is Living </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (392, NULL, 'B', 'EASTER', 'Sixth S. of Easter', 'White', '<div><strong>The Lord Jesus Is with His Church in the Apostolic Ministry of the Gospel</strong></div>\r\n\r\n<div>The crucified and risen Lord Jesus is with His Church through the word of His apostles, who &quot;are witnesses of all that he did.&quot; He was anointed by God &quot;with the Holy Spirit and with power,&quot; and &quot;he went about doing good and healing all who were oppressed by the devil,&quot; and so He was with those whom He sent &quot;to preach to the people&quot; (Acts 10:38_42). The Holy Spirit is bestowed on those who hear that apostolic preaching, who are &quot;baptized in the name of Jesus Christ,&quot; so that &quot;everyone who believes in him receives forgiveness of sins through his name&quot; (Acts 10:43_44, 48). For as He came by the water of His Baptism, even to the blood of His Passion, so the Spirit testifies to the truth with &quot;the water and the blood&quot; in the apostolic ministry of the Gospel (1 John 5:6_7). By these means, Christ Jesus speaks to us, that His joy may be in us and that our &quot;joy may be full.&quot; For this purpose, He appointed the apostles to &quot;go and bear fruit&quot; in order to make known His divine friendship to us (John 15:11, 15_16).</div>', 'Acts 10:34–48', 'Psalm 98', '1 John 5:1–8', 'John 15:9–17', '<div>INTROIT &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Ps.66:1-2,8-9,20; antiphon Ps. 66:16</div>\r\n\r\n<div>Come and hear, all you who | fear God *</div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;and I will tell what he has done | for my soul.</strong></div>\r\n\r\n<div>Shout for joy to God, | all the earth; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>sing the glory of his name; give to him | glorious praise!</strong></div>\r\n\r\n<div>Bless our God, O | peoples; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>let the soud of his | praise be heard,</strong></div>\r\n\r\n<div>who has kept our soul among the | living *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and has not let our | feet slip.</strong></div>\r\n\r\n<div>Blessed | be God, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>because he has not rejected my prayer or removed his steadfast | love from me!</strong></div>\r\n\r\n<div><strong>Glory be to the Father…</strong></div>\r\n\r\n<div>Come and hear, all you who | fear God *</div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;and I will tell what he has done | for my soul.</strong></div>', '<div>Entrance: 700 Love Divine, All Loves Excelling </div>\r\n\r\n<div>Of the Day: 556 Dear Christians, One and All, Rejoice </div>\r\n\r\n<div>Offertory: 671 Sing with All the Saints in Glory </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;845 Where Charity and Love Prevail </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;683 Jesus, Thy Boundless Love to Me </div>\r\n\r\n<div>Closing: 829 Christ the Eternal Lord </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (393, 2460, 'B', 'ASCENSION', 'The Ascension of Our Lord', 'White', NULL, 'Acts 1:1–11', 'Psalm 47', 'Eph. 1:15–23', 'Luke 24:44–53', NULL, NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (394, 2470, 'B', 'EASTER', 'Seventh S. of Easter', 'White', '<div><strong>Our Great High Priest Preserves Us in the Name of His Father</strong></div>\r\n\r\n<div>On the eve of His Passion, Christ Jesus intercedes for the disciples as their merciful and great High Priest. He prays that His Father would protect them &quot;from the evil one&quot; and preserve them in His name (John 17:11_12, 15). Along with His prayer, Christ Himself comes to the Father by His self-sacrifice upon the cross, thereby consecrating Himself for the sake of His disciples, &quot;that they also may be sanctified in truth&quot; (John 17:19). To that same end, He speaks to them in the world and gives them His Father\'s Word, that is, Himself. His apostles, in turn, have written these things &quot;to you who believe in the name of the Son of God that you may know that you have eternal life&quot; (1 John 5:13). For &quot;this life is in his Son,&quot; whom He has given by His Word, and &quot;whoever has the Son has life&quot; (1 John 5:11_12). By this apostolic testimony, disciples are gathered together &quot;with one accord,&quot; as one Body in Christ, &quot;devoting themselves to prayer&quot; and waiting upon the Lord in &quot;the upper room&quot; of His Church on earth (Acts 1:13_14).</div>', 'Acts 1:12–26', 'Psalm 1', '1 John 5:9–15', 'John 17:11b–19', '<div><strong>INTROIT &nbsp;&nbsp;Ps.27:1a,4-5,10,14; antiphon Ps.27:7</strong></div>\r\n\r\n<div>Hear, O LORD, when I | cry aloud; *</div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;be gracious to me and | answer me!</strong></div>\r\n\r\n<div>The LORD is my light and my sal- | vation; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;<strong>whom | shall I fear?</strong></div>\r\n\r\n<div>One thing have I asked of the LORD, that will I seek | after; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>that I may dwell in the house of the LORD all the days of my life, to gaze upon the beauty of the LORD and to inquire in his | temple.</strong></div>\r\n\r\n<div>For he will hide me in his shelter in the day of | trouble; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>he will conceal me under the cover of his tent; he will lift me high up- | on a rock.</strong></div>\r\n\r\n<div>For my father and my mother have for- | saken me, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>but the LORD will | take me in.</strong></div>\r\n\r\n<div>Wait | for the LORD; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>be strong, and let your heart take courage; wait | for the LORD!</strong></div>\r\n\r\n<div><strong>Glory be to the Father…</strong></div>\r\n\r\n<div>Hear, O LORD, when I | cry aloud; *</div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;be gracious to me and | answer me!</strong> </div>', '<div>Entrance: 909 Christ Is Made the Sure Foundation </div>\r\n\r\n<div>Of the Day: 539 Christ Is the World’s Redeemer </div>\r\n\r\n<div>Offertory: 651 I Love Your Kingdom, Lord </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;644 The Church’s One Foundation </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;856 O Christ, Who Called the Twelve </div>\r\n\r\n<div>Closing: 643 Send Forth by God’s Blessing </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (395, 2480, 'B', 'PENTECOST', 'Pentecost Eve', 'Red', NULL, 'Ex. 19:1-9', 'Psalm 113', 'Rom. 8:12-17(22-27)', 'John 14:8-21', NULL, NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (396, 2490, 'B', 'PENTECOST', 'The Day of Pentecost', 'Red', '<div><strong>The Holy Spirit Brings the Dead to Life by the Righteousness of Christ</strong></div>\r\n\r\n<div>In returning to His Father by way of the cross and resurrection, Christ Jesus sends &quot;the Helper&quot; to His Church, that is, &quot;the Spirit of truth, who proceeds from the Father.&quot; The Spirit testifies of Christ and glorifies Him, by taking what is His and declaring it to the world in the preaching of repentance for the forgiveness of sins (John 15:26; 16:7, 14). He convicts the world of sin by the word of the Law, He forgives sins and justifies sinners by the Word of the Gospel, and He bestows the faith that says &quot;Amen&quot; to this righteousness of God (John 16:8_11). Therefore, the Lord pours out His Spirit on the apostles, that by their preaching, the Spirit should be given to His entire Church. As the multitudes are gathered from all the nations by &quot;this sound,&quot; that is, by the preaching of &quot;the mighty works of God&quot; in Christ Jesus, so does God the Father pour out the Spirit of His Son &quot;on all flesh&quot; (Acts 2:6, 11, 17). The Lord God breathes upon the slain, and so shall they live; for so the Lord has spoken, and He shall do it (Ezek. 37:5_14).</div>', 'Ezek. 37:1–14', 'Psalm 139:1–12 (13–16)', 'Acts 2:1–21', 'John 15:26–27; 16:4b–15', '<div><strong>INTROIT &nbsp;&nbsp;ps.104:24,27,28,30 antiphon: Liturgical Text</strong></div>\r\n\r\n<div>Come, Holy Spirit, fill the hearts of the | faithful, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and kindle in them the fire of your love. Alle- | luia.</strong></div>\r\n\r\n<div>O LORD, how manifold are your works! In wisdom have you | made them all; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>the earth is full of your | creatures. </strong></div>\r\n\r\n<div>These all | look to you, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>to give them their food in due | season.</strong></div>\r\n\r\n<div>When you give it to them, they gath- | er it up; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>when you open your hand, they are filled with | good things.</strong></div>\r\n\r\n<div>When you send forth your Spirit, they are cre- | ated, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;<strong>and you renew the face | of the ground.</strong></div>\r\n\r\n<div><strong>Glory be to the Father…</strong></div>\r\n\r\n<div>Come, Holy Spirit, fill the hearts of the | faithful, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and kindle in them the fire of your love. Alle- | luia.</strong></div>', '<div>Entrance: 497 Come, Holy Ghost, God and Lord </div>\r\n\r\n<div>Of the Day: 502 Holy Spirit, the Dove Sent from Heaven </div>\r\n\r\n<div>Offertory: 768 To God the Holy Spirit Let Us Pray </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;496 Holy Spirit, Light Divine </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;650 Holy Spirit, Ever Dwelling </div>\r\n\r\n<div>Closing: 503 O Day Full of Grace </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (397, 2500, 'B', 'PENTECOST', 'Pentecost Evening / Monday', 'Red', NULL, 'Is. 57:15-21', 'Psalm 43', 'Acts 10:34a, 42-48', 'John 3:16-21', NULL, NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (398, 2510, 'B', 'PENTECOST', 'Pentecost Tuesday', 'Red', NULL, 'Is. 32:14-20', 'Psalm 27', 'Acts 8:14-17', 'John 10:1-10', NULL, NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (399, 2520, 'B', 'HOLY TRINITY', 'The Holy Trinity', 'White', '<div><strong>The Glory of the Lord of Hosts Shines in Mercy, Forgiveness and Salvation</strong></div>\r\n\r\n<div>When Isaiah &quot;saw the Lord sitting upon a throne, high and lifted up,&quot; he cried out and confessed that he was &quot;a man of unclean lips.&quot; If even the holy angels cover their faces in the presence of &quot;the King, the Lord of hosts,&quot; how can sinful humans stand before Him (Is. 6:1_5)? Yet, the glory of the Lord is saving grace, and with &quot;a burning coal&quot; from the altar the angel touched Isaiah\'s lips, removing his guilt (Is. 6:6_7). Likewise, from the altar of Christ\'s cross, by the ministry of the Gospel, &quot;the whole earth is full of his glory&quot; (Is. 6:3). For He was crucified, died and was buried, &quot;according to the definite plan and foreknowledge of God,&quot; and God &quot;raised him up, loosing the pangs of death&quot; (Acts 2:23_24). He &quot;received from the Father the promise of the Holy Spirit&quot; (Acts 2:33), and He raises up the fallen world by pouring out His life-giving Spirit upon sinners through His earthly Means of Grace. To give this saving gift, God sent His Son into the world, &quot;that whoever believes in him should not perish but have eternal life&quot; (John 3:16_17).When Isaiah &quot;saw the Lord sitting upon a throne, high and lifted up,&quot; he cried out and confessed that he was &quot;a man of unclean lips.&quot; If even the holy angels cover their faces in the presence of &quot;the King, the Lord of hosts,&quot; how can sinful humans stand before Him (Is. 6:1_5)? Yet, the glory of the Lord is saving grace, and with &quot;a burning coal&quot; from the altar the angel touched Isaiah\'s lips, removing his guilt (Is. 6:6_7). Likewise, from the altar of Christ\'s cross, by the ministry of the Gospel, &quot;the whole earth is full of his glory&quot; (Is. 6:3). For He was crucified, died and was buried, &quot;according to the definite plan and foreknowledge of God,&quot; and God &quot;raised him up, loosing the pangs of death&quot; (Acts 2:23_24). He &quot;received from the Father the promise of the Holy Spirit&quot; (Acts 2:33), and He raises up the fallen world by pouring out His life-giving Spirit upon sinners through His earthly Means of Grace. To give this saving gift, God sent His Son into the world, &quot;that whoever believes in him should not perish but have eternal life&quot; (John 3:16_17).</div>', 'Is. 6:1–8', 'Psalm 29', 'Acts 2:14a, 22-36', 'John 3:1–17', '<div>Blessed be the Holy Trinity and the undivided | Unity. *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>Let us give glordy to him because he has shown his mer- | cy to us.</strong></div>\r\n\r\n<div>I have set the Lord always be- | fore me; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>because he is at my right hand, I shall not be | shaken.</strong></div>\r\n\r\n<div>Therefore my heart is glad, and my whole being re- | joices; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>my flesh also | dwells secure.</strong></div>\r\n\r\n<div>For you will not abandon my soul | to Sheol, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>or let your holy one see cor- | ruption.</strong></div>\r\n\r\n<div>You make known to me the | path of life; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>in your presence there is fullness of joy; at your right hand are pleasures for- | evermore.</strong></div>\r\n\r\n<div><strong>Glory be to the Father…</strong></div>\r\n\r\n<div>Blessed be the Holy Trinity and the undivided | Unity. *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>Let us give glordy to him because he has shown his mer- | cy to us.</strong></div>', '<div>Entrance: 507 Holy, Holy, Holy </div>\r\n\r\n<div>Of the Day: 940 Holy God, We Praise Thy Name </div>\r\n\r\n<div>Offertory: 795 Voice Raised to You We Offer </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;960 Isaiah, Mighty Seer in Days of Old </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;907 God Himself Is Present </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;971 There Is a Redeemer (Lutheran Service Builder) </div>\r\n\r\n<div>Closing: 822 Alleluia! Let Praises Ring </div>', '<div>Athanasian Creed is usuall confessed on this Sunday.</div>');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (400, 2530, 'B', 'PENTECOST', 'Sunday on May 24-28 (Proper 3)', 'Green', NULL, 'Hos. 2:14-20', 'Psalm 103:1-13', 'Acts:2:14a,36-47', 'Mark 2(13-17)18-22', NULL, NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (401, 2540, 'B', 'PENTECOST', 'Sunday on May 29-June 4 (Proper 4)', 'Green', NULL, 'Deut. 5:12-15', 'Psalm 81:1-10', '2 Cor 4:5-12', 'Mark 2:23-28(3:1-6)', NULL, NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (402, 2550, 'B', 'PENTECOST', 'Sunday on June 5-11 (Proper 5)', 'Green', '<div><strong>Jesus Has Defeated the Devil and Released Us from the Bondage of Sin and Death</strong></div>\r\n\r\n<div>The devil deceived us, enticing us to disregard and disobey the Word of God and driving us to hide &quot;from the presence of the Lord God.&quot; But the Lord, in His mercy, promised a Savior, who would set Himself against the devil on our behalf (Gen. 3:8_15). The Son of Man came, the incarnate Son of God, conceived and born of the woman. He &quot;first binds the strong man,&quot; Satan, by atoning for the sins of the world, thereby removing the condemnation of the Law and the fear of death (Mark 3:27). Now He plunders the devil\'s house by calling all men to repent. Though He appears to be &quot;out of his mind&quot; (Mark 3:21), He fulfills the will of God and makes of us His own brothers and sisters. Therefore, &quot;we do not lose heart,&quot; despite the suffering, sin and death that we experience in this fallen world. &quot;He who raised the Lord Jesus will raise us also with Jesus.&quot; By His grace, we are &quot;being renewed day by day.&quot; For the Gospel is daily bringing us into His presence, not for punishment, but for &quot;an eternal weight of glory&quot; (2 Cor. 4:14_17).</div>', 'Gen. 3:8–15', 'Ps. 130', '2 Cor. 4:13—5:1', 'Mark 3:20–35', '<div>INTROIT &nbsp;&nbsp;&nbsp;Ps.28:7-9; antiphone ps.28:6</div>\r\n\r\n<div>Blessed | be the LORD! *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>For he has heard the voice of my pleas for | mercy.</strong></div>\r\n\r\n<div>The LORD is my stringth and my shield; in him my heart trusts, and | I am helped; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>my heart exults, and with my song I give | thanks to him.</strong></div>\r\n\r\n<div>The LORD is the strength of his | people; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>he is the saving refuge of his a- | nointed.</strong></div>\r\n\r\n<div>Oh, save your people and bless your | heritage! *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>Be their shepherd and carry them for- | ever.</strong></div>\r\n\r\n<div><strong>Glory be to the Father…</strong></div>\r\n\r\n<div>Blessed | be the LORD! *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>For he has heard the voice of my pleas for | </strong></div>', '<div>Entrance: 645 Built on the Rock </div>\r\n\r\n<div>Of the Day: 668 Rise! To Arms! With Prayer Employ You </div>\r\n\r\n<div>Offertory: 735 Have No Fear, Little Flock </div>\r\n\r\n<div>Distribution: 561 The Tree of Life </div>\r\n\r\n<div>716 I Walk in Danger All the Way </div>\r\n\r\n<div>Closing: 656 A Mighty Fortress Is Our God </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (403, 2560, 'B', 'PENTECOST', 'Sunday on June 12-18 (Proper 6)', 'Green', '<div><strong>The Cross of Christ Is the Tree of Life, Which Bears Abundant Fruit after Its Own Kind</strong></div>\r\n\r\n<div>The parables of our Lord convey the mysteries of the kingdom of God to those who are &quot;able to hear it,&quot; that is, &quot;to his own disciples,&quot; who are catechized to fear, love and trust in Him by faith (Mark 4:33_34). He scatters &quot;seed on the ground,&quot; which &quot;sprouts and grows&quot; unto life, even as &quot;he sleeps and rises&quot; (Mark 4:26_27). &quot;On the mountain height of Israel,&quot; He plants a young and tender twig, and it becomes &quot;a noble cedar.&quot; Indeed, His own cross becomes the Tree of Life, under which &quot;every kind of bird&quot; will dwell, and in which &quot;birds of every sort will nest&quot; (Ezek. 17:22_25). His cross is our resting place, even while now in mortal bodies, we &quot;groan, being burdened&quot; (2 Cor. 5:1_4). Yet in faith, we live for God in Christ, who for our sake &quot;died and was raised&quot; (2 Cor. 5:15). We know that, in His resurrected body, &quot;we have a building from God, a house not made with hands, eternal in the heavens&quot; (2 Cor. 5:1).</div>', 'Ezek. 17:22–24', 'Psalm 1', '2 Cor. 5:1–10 (11–17)', 'Mark 4:26–34', '<div>INTROIT &nbsp;&nbsp;&nbsp;Ps. 92:12-15; antiphon: Ps. 29:1</div>\r\n\r\n<div>It is good to give thanks | to the LORD, *</div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;to sing praises to your name, | O Most High.</strong></div>\r\n\r\n<div>The righteous flourish like the | palm tree*</div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;and grow like a cedar in | Lebanon.</strong></div>\r\n\r\n<div>&nbsp;The are planted in the house | of the LORD; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>they flourish in the courts | of our God.</strong></div>\r\n\r\n<div>They still bear fruit in | old age; *</div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;they are ever full of | sap and green,</strong></div>\r\n\r\n<div>to declare that the LORD is | upright; *</div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;his is my rock, and there is no unrighteousness | in him.</strong></div>\r\n\r\n<div><strong>Glory be to the Father…</strong></div>\r\n\r\n<div>It is good to give thanks | to the LORD, *</div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;to sing praises to your name, | O Most High.</strong></div>', '<div>Entrance: 705 The Man Is Ever Blessed </div>\r\n\r\n<div>Of the Day: 834 O God, O Lord of Heaven and Earth </div>\r\n\r\n<div>Offertory: 577 Almighty God, Your Word Is Cast </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;654 Your Kingdom, O God, Is My Glorious Treasure </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;894 For the Fruits of His Creation </div>\r\n\r\n<div>Closing: 652 Father, We Thank Thee </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (404, 2570, 'B', 'PENTECOST', 'Sunday on June 19-25 (Proper 7)', 'Green', '<div><strong>The Word of Christ Bestows Peace on His Creation through His Forgiveness of Sins</strong></div>\r\n\r\n<div>In his anguish and affliction, Job must be reminded that, as a finite creature, he is in no position to question the Maker of the heavens and the earth. Job\'s &quot;words without knowledge&quot; are unable to penetrate the wisdom of the Lord (Job 38:1_2). For the Lord has &quot;prescribed limits&quot; and &quot;set bars and doors,&quot; so that &quot;here shall your proud waves be stayed&quot; (Job 38:9_11). That\'s how He humbles us unto repentance. But also by His powerful Word, He calms the &quot;great windstorm&quot; and the waves &quot;breaking into the boat.&quot; He does not permit the chaos of this fallen world to overwhelm us or bring us to despair. By the Word of His Gospel, He speaks &quot;Peace!&quot; to us, which bestows the &quot;great calm&quot; of His new creation (Mark 4:37_39). Therefore, do not be afraid, and do not receive this grace of God in vain. &quot;Now is the favorable time,&quot; and &quot;now is the day of salvation&quot; (2 Cor. 6:1_2).</div>', 'Job 38:1–11', 'Psalm 124', '2 Cor. 6:1–13', 'Mark 4:35–41', '<div><strong>INTROIT &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Ps.107:29-32; antiphon: Ps.107:28</strong></div>\r\n\r\n<div>Then they cried to the LORD in their | trouble, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and he delivered them from | their distress.</strong></div>\r\n\r\n<div>He made the | storm be still, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and the waves of the | sea were hushed.</strong></div>\r\n\r\n<div>Then they were glad that the waters were | quiet, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and he brought them to their desired | haven.</strong></div>\r\n\r\n<div>Let them thank the LORD for his | steadfast love, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>for his wondrous works to the chil- | dren of men!</strong></div>\r\n\r\n<div>Let them extol him in the congregation of the | people, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and praise him in the assembly of the | elders.</strong></div>\r\n\r\n<div><strong>Glory be to the Father…</strong></div>\r\n\r\n<div>Then they cried to the LORD in their | trouble, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and he delivered them from | their distress.</strong></div>', '<div>Entrance: 790 Praise to the Lord, the Almighty </div>\r\n\r\n<div>Of the Day: 726 Evening and Morning </div>\r\n\r\n<div>Offertory: 722 Lord, Take My Hand and Lead Me </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;717 Eternal Father, Strong to Save </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;752 Be Still, My Soul </div>\r\n\r\n<div>Closing: 728 How Firm a Foundation </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (405, 2580, 'B', 'PENTECOST', 'Sunday on June 26-July 2 (Proper 8)', 'Green', '<div><strong>The Lord Jesus Is Faithful, and in Mercy He Raises You Up from Death to Life</strong></div>\r\n\r\n<div>The Lord is faithful. His steadfast love never ceases, and &quot;his mercies never come to an end&quot; (Lam. 3:22_23). To keep us in repentance and to make our faith grow, He causes grief for a while, but He does not cast off forever; in due time, &quot;he will have compassion&quot; (Lam. 3:31_33). Therefore, &quot;hope in him,&quot; and &quot;wait quietly for the salvation of the Lord,&quot; for &quot;the Lord is good to those who wait for him&quot; (Lam. 3:24_26). That is what the woman did who had &quot;a discharge of blood,&quot; and also the ruler whose daughter &quot;was at the point of death.&quot; Each waited on the mercy of the Lord Jesus, and each received His saving help (Mark 5:21_28). The woman had suffered much for 12 years, and the ruler\'s daughter had already died before Jesus arrived. Yet at the right time, the woman was immediately &quot;healed of her disease,&quot; and the little girl &quot;got up and began walking&quot; (Mark 5:29, 42). Such is &quot;the grace of our Lord Jesus Christ,&quot; who humbled Himself unto the extreme poverty of death &quot;so that you by his poverty might become rich,&quot; even unto life everlasting (2 Cor. 8:9).</div>', 'Lam. 3:22–33', 'Psalm 30', '2 Cor. 8:1–9, 13–15', 'Mark 5:21–43', '<div><strong>INTROIT &nbsp;Ps.121:5-8; antiphon Ps.121:1-2</strong></div>\r\n\r\n<div>I lift up my eyes to the hills. *</div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;From where does my | help come?</strong></div>\r\n\r\n<div>My help comes | from the LORD, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>who made | heaven and earth.</strong></div>\r\n\r\n<div>The LORD is your | keeper *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>The LORD is your shade at your | right hand.</strong></div>\r\n\r\n<div>The sun shall not strike | you by day *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>nor the | moon by night.</strong></div>\r\n\r\n<div>The LORD will keep your going out and your | coming in *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>from this time forth and for- | evermore.</strong></div>\r\n\r\n<div><strong>Glory be to the Father…</strong></div>\r\n\r\n<div>I lift up my eyes to the hills. *</div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;From where does my | help come?</strong></div>', '<div>Entrance: 820 My Soul, Now Praise Your Maker </div>\r\n\r\n<div>Of the Day: 846 Your Hand, O Lord, in Days of Old </div>\r\n\r\n<div>Offertory: 683 Jesus, Thy Boundless Love to Me </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;559 Oh, How Great Is Your Compassion </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;782 Gracious God, You Send Great Blessings </div>\r\n\r\n<div>Closing: 548 Thanks to Thee, O Christ, Victorious </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (406, 2590, 'B', 'PENTECOST', 'Sunday on July 3-9 (Proper 9)', 'Green', '<div><strong>The Ministers of Christ Are Sent with His Authority to Forgive Sins and Give Life</strong></div>\r\n\r\n<div>The prophet Ezekiel was raised up by the Spirit of the Lord and sent to speak an unpopular Word to the rebellious house of Israel. As a prophet, he was not to speak his own word, but to preach the Law and the Gospel: &quot;Thus says the Lord God,&quot; whether the people &quot;hear or refuse to hear&quot; (Ezek. 2:4_5). So, too, in the footsteps of the prophets before Him, the Lord Jesus &quot;went about among the villages teaching&quot; (Mark 6:6). In His hometown, as elsewhere, &quot;many who heard him were astonished,&quot; marveling at His wisdom and at the &quot;mighty works done by his hands,&quot; and yet, &quot;they took offense at him&quot; (Mark 6:2_3). The offense culminates in His cross, which is, ironically, the heart and center of His &quot;authority over the unclean spirits&quot; (Mark 6:7). It is by that authority of His cross that those He sends preach repentance, &quot;cast out many demons&quot; and heal the sick (Mark 6:12_13). Thus, the apostle Paul boasts in the cross of Christ and in his own weaknesses, knowing that God\'s grace is sufficient and that the power of Christ &quot;is made perfect in weakness&quot; (2 Cor. 12:8_9).</div>', 'Ezek. 2:1–5', 'Psalm 123', '2 Cor. 12:1–10', 'Mark 6:1–13', '<div>INTROIT &nbsp;Ps.132:13-16; antophon: ps.34:8</div>\r\n\r\n<div>Oh, taste and see that the | LORD is good! *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>Blessed is the man who takes ref- | uge in him!</strong></div>\r\n\r\n<div>For the LORD has chosen | Zion; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>he has desired it for his | dwelling place:</strong></div>\r\n\r\n<div>&quot;This is my resting place for- | ever; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>here I will dwell, for I have de- | sired it.</strong></div>\r\n\r\n<div>I will abundantly bless her pro- | visions; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>I will satisfy her | poor with bread.</strong></div>\r\n\r\n<div>Her priests I will clothe with sal- | vation, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and her saints will | shout for joy.</strong></div>\r\n\r\n<div><strong>Glory be to the Father…</strong></div>\r\n\r\n<div>Oh, taste and see that the | LORD is good! *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>Blessed is the man who takes ref- | uge in him!</strong></div>', '<div>Entrance: 966 Before You, Lord We Bow </div>\r\n\r\n<div>Of the Day: 839 O Christ, Our True and Only Light </div>\r\n\r\n<div>Offertory: &nbsp;&nbsp;&nbsp;&nbsp;717 Eternal Father, Strong to Save* (using alt sts. *2, *3) </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;642 O Living Bread from Heaven </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;578 Thy Strong Word Closing: </div>\r\n\r\n<div>965 God Bless Our Native Land (or My Country ‘Tis of Thee) </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (407, 2600, 'B', 'PENTECOST', 'Sunday on July 10-16 (Proper 10)', 'Green', '<div><strong>The Lord Jesus Brings His People through Death into Life by the Preaching of Repentance</strong></div>\r\n\r\n<div>Amos did not choose to be a prophet, but the Lord took him &quot;from following the flock&quot; and said to him, &quot;Go, prophesy to my people Israel&quot; (Amos 7:15). It was a hard word given him to preach: King Jeroboam would &quot;die by the sword,&quot; and Israel would &quot;go into exile away from his land&quot; (Amos 7:10_11). For this word, Amos was hated and threatened. St. John the Baptist also suffered for his faithful preaching of repentance. King Herod &quot;sent and seized John and bound him in prison,&quot; even though he knew that John &quot;was a righteous and holy man&quot; (Mark 6:17, 20). Out of pride and fear, Herod &quot;sent an executioner with orders to bring John\'s head&quot; (Mark 6:27). Yet in Christ, St. John the Baptist &quot;has been raised from the dead&quot; (Mark 6:14, 16). For Christ is the destruction of death itself &quot;before the foundation of the world,&quot; and even now by faith, &quot;the God and Father of our Lord Jesus Christ&quot; has blessed us in Christ &quot;with every spiritual blessing in the heavenly places&quot; (Eph. 1:3_4). Through Baptism into Christ, you also &quot;were sealed with the promised Holy Spirit&quot; for life and salvation (Eph. 1:13).</div>', 'Amos 7:7–15', 'Psalm 85:(1-7)8-13', 'Eph. 1:3–14', 'Mark 6:14–29', '<div><strong>INTROIT &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Ps. 143:1-2,8a; antiphon: ps. 143:11</strong></div>\r\n\r\n<div>For your name\'s sake, O LORD, pre- | serve my life! *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>in your righteousness bring my soul out of | trouble!</strong></div>\r\n\r\n<div>Hear my prayer, O LORD; give ear to my pleas for | mercy! *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>In your faithfulness answer me, in your | righteousness!</strong></div>\r\n\r\n<div>Enter not into judgement with your | servant, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>for no one living is righteous be- | fore you.</strong></div>\r\n\r\n<div>Let me hear in the morning of your | steadfast love, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>for in | you I trust.</strong></div>\r\n\r\n<div><strong>Glory be to the Father…</strong></div>\r\n\r\n<div>For your name\'s sake, O LORD, pre- | serve my life! *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>in your righteousness bring my soul out of | trouble!</strong></div>', '<div>Entrance: 713 From God Can Nothing Move Me </div>\r\n\r\n<div>Of the Day: 743 Jesus, Priceless Treasure </div>\r\n\r\n<div>Offertory: 777 Grant Peace, We Pray, in Mercy, Lord </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;619 Thy Body, Given for Me, O Savior </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;716 I Walk in Danger All the Way </div>\r\n\r\n<div>Closing: 917 Savior, Again to Thy Dear Name We Raise </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (408, 2610, 'B', 'PENTECOST', 'Sunday on July 17-23 (Proper 11)', 'Green', '<div>The Lord Jesus Shepherds His Church on Earth by the Ministry of the Gospel\\rThe Lord rebukes and removes &quot;the shepherds who destroy and scatter the sheep&quot; (Jer. 23:1). He gathers the flock, brings them back to the fold and sets &quot;shepherds over them who will care for them&quot; (Jer. 23:3_4). He raises up the Son of David, the great Good Shepherd, to &quot;reign as king and deal wisely&quot; (Jer. 23:5). He is &quot;our righteousness,&quot; in whom we &quot;dwell securely&quot; (Jer. 23:6). He has compassion on all of us, who were &quot;like sheep without a shepherd&quot; (Mark 6:34). Not only does He teach us many things, but taking the bread, He blesses and breaks and gives it to the disciples &quot;to set before the people&quot; (Mark 6:41). He abundantly provides for His Church on earth, so that everyone is fed and fully satisfied in body and soul. He preaches peace &quot;to you who were far off,&quot; and &quot;by the blood of Christ,&quot; He brings you near (Eph. 2:13, 17). Though you were &quot;separated from Christ&quot; by your sin, &quot;having no hope and without God in the world&quot; (Eph. 2:12), now &quot;you are fellow citizens with the saints and members of the household of God&quot; (Eph. 2:19).</div>', 'Jer. 23:1–6', 'Psalm 23', 'Eph. 2:11–22', 'Mark 6:30–44', '<div><strong>INTROIT ps.147:7; antiphon 145:16</strong></div>\r\n\r\n<div>You open | your hand *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>you satisfy the desire of every | living thing.</strong></div>\r\n\r\n<div>Sing to the LORD with thanks - | giving; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>make melody to our God | on the lyre!</strong></div>\r\n\r\n<div>He covers the heavens with clouds; he prepares rain | for the earth; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>he makes grass grow | on the hills.</strong></div>\r\n\r\n<div>He gives to the | beast their food, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and to the youn ravens | that cry.</strong></div>\r\n\r\n<div>His delight is not in the strength | of the horse, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>nor his pleasure in the legs | of a man,</strong></div>\r\n\r\n<div>but the LORD takes pleasure in those who | fear him, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>in those who hope in his | steadfast love.</strong></div>\r\n\r\n<div><strong>Glory be to the Father…</strong></div>\r\n\r\n<div>You open | your hand *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>you satisfy the desire of every | living thing.</strong></div>', '<div>Entrance: 709 The King of Love My Shepherd Is </div>\r\n\r\n<div>Of the Day: 644 The Church’s One Foundation </div>\r\n\r\n<div>Offertory: 711 Savior, like a Shepherd Lead Us </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;642 O Living Bread from Heaven </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;641 You Satisfy the Hungry Heart </div>\r\n\r\n<div>Closing: 861 Christ Be My Leader </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (409, 2620, 'B', 'PENTECOST', 'Sunday on July 24-30 (Proper 12)', 'Green', '<div><strong>Creation Is Redeemed and Sanctified by the Word of Christ Jesus</strong></div>\r\n\r\n<div>Having spared faithful Noah and his family from the flood, the Lord established His covenant with them, &quot;and with every living creature,&quot; that never again would there be &quot;a flood to destroy the earth&quot; (Gen. 9:9_11). He signed and sealed this everlasting covenant with His rainbow in the clouds, by which He sees and remembers His promise that &quot;the waters shall never again become a flood to destroy all flesh&quot; (Gen. 9:13_16). Although creation suffers under the curse of sin, the Lord preserves and orders creation for the benefit of His Church. In particular, all of creation is redeemed and sanctified by the incarnate Son of God. &quot;Take heart,&quot; and &quot;do not be afraid,&quot; for He is with you on the sea. He is not a ghost, but He has come in the flesh to save you. He has gotten &quot;into the boat&quot; with you, and the wind that was against you has ceased (Mark 6:45_51). For He is the Word and promise of the Father, and His own flesh and blood are the covenant by which you are &quot;strengthened with power through his Spirit in your inner being&quot; (Eph. 3:16_17).</div>', 'Gen. 9:8–17', 'Psalm 136:1-9', 'Eph. 3:14–21', 'Mark 6:45–56', '<div><strong>INTROIT &nbsp;Ps.145:1-3,6-7; antophon Ps.145:5</strong></div>\r\n\r\n<div>On the glorious splendor of your | majesty, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and on your wonderous works, I will | meditate.</strong></div>\r\n\r\n<div>I will extol you, my | God and King, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and bless your name forever and | ever.</strong></div>\r\n\r\n<div>Every day I will | bless you *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and praise your name forever and | ever.</strong></div>\r\n\r\n<div>Great is the LORD, and greatly | to be praised, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and his greatness is un- | searchable.</strong></div>\r\n\r\n<div>The shall speak of the might of your | awesome deads, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and I will declare you | greatness.</strong></div>\r\n\r\n<div>They shall pour forth the flame of your abundant | goodness *</div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;and shall sing alooud of your | rightesousness.</strong></div>\r\n\r\n<div><strong>Glory be to the Father…</strong></div>\r\n\r\n<div>On the glorious splendor of your | majesty, *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and on your wonderous works, I will | meditate.</strong></div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (410, 2630, 'B', 'PENTECOST', 'Sunday on July 31-August 6 (Proper 13)', 'Green', '<div><strong>Jesus Is the True and Living Bread from Heaven</strong></div>\r\n\r\n<div>Having rescued Israel &quot;out of the land of Egypt&quot; (Ex. 16:6), the Lord manifested His glory and made Himself known to His people. He fed them with &quot;meat to eat&quot; in the evening and with &quot;bread from heaven&quot; in the morning (Ex. 16:4, 8, 12). But now, the &quot;true bread from heaven,&quot; which the Father gives to you, is the Son, &quot;who comes down from heaven and gives life to the world&quot; (John 6:32_33). Whoever comes to Him &quot;shall not hunger,&quot; and whoever believes in Him &quot;shall never thirst.&quot; He is &quot;the bread of life,&quot; who gives Himself to you as &quot;the food that endures to eternal life&quot; (John 6:27, 35). By the gracious working of God, you believe in Him by the calling of one Spirit through the Gospel, so that you also have &quot;one Lord, one faith, one baptism, one God and Father of all&quot; (Eph. 4:4_6). As you eat His one body in the Holy Supper, so you belong to the one body of His Church, in which you &quot;are to grow up in every way into him who is the head&quot; (Eph. 4:15).</div>', 'Ex. 16:2–15', 'Psalm 145:10-21', 'Eph. 4:1–16', 'John 6:22–35', '<div>INTROIT &nbsp;PS.78:23-25; antiphon: Ps.78:72</div>\r\n\r\n<div>With upright heart he shep- | herded them *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and guided them with his | skillful hand.</strong></div>\r\n\r\n<div>He commanded the | skies above *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and opened the doors fo | heaven,</strong></div>\r\n\r\n<div>and he rained down on them man- | na to eat*</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and gave them grain of | heaven.</strong></div>\r\n\r\n<div>Man ate the bread of the | angels; *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>he sent them food in a- | bundance.</strong></div>\r\n\r\n<div><strong>Glory be to the Father…</strong></div>\r\n\r\n<div>With upright heart he shep- | herded them *</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and guided them with his | skillful hand.</strong></div>', '<div><font face=\"Goudy Old Style\" size=2 color=black>Entrance: 697 Awake, O Sleeper, Rise from Death </font></div>\r\n\r\n<div><font face=\"Goudy Old Style\" size=2 color=black>Of the Day: 918 Guide Me, O Thou Great Redeemer </font></div>\r\n\r\n<div><font face=\"Goudy Old Style\" size=2 color=black>Offertory: 789 Praise and Thanksgiving </font></div>\r\n\r\n<div><font face=\"Goudy Old Style\" size=2 color=black>Distribution: </font></div>\r\n\r\n<div><font face=\"Goudy Old Style\" size=2 color=black>&nbsp;&nbsp;&nbsp;&nbsp;625 Lord Jesus Christ, Life-Giving Bread </font></div>\r\n\r\n<div><font face=\"Goudy Old Style\" size=2 color=black>&nbsp;&nbsp;&nbsp;&nbsp;624 The Infant Priest Was Holy Born </font></div>\r\n\r\n<div><font face=\"Goudy Old Style\" size=2 color=black>Closing: 652 Father, We Thank Thee </font></div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (411, 2640, 'B', 'PENTECOST', 'Sunday on August 7-13 (Proper 14)', 'Green', '<div><strong>The Lord Jesus Feeds Us with His Flesh, in Order to Strengthen Us with His Own Life</strong></div>\r\n\r\n<div>God the Father sent His Son into the world, so that the world might have life in Him. Now He &quot;draws&quot; you to His Son, Christ Jesus, by the preaching of His Gospel. &quot;Everyone who has heard and learned from the Father&quot; comes to Jesus, who will never cast him out but &quot;will raise him up on the last day&quot; (John 6:44_45). He is &quot;the bread of life,&quot; who &quot;comes down from heaven&quot; in the flesh, that you may eat of Him and &quot;live forever&quot; (John 6:48_51). Although &quot;the journey is too great for you,&quot; in the strength of this food you shall come to &quot;the mount of God.&quot; Do not be afraid, and do not despair, but &quot;arise and eat&quot; (1 Kings 19:5_8). And &quot;no longer walk as the Gentiles do, in the futility of their minds&quot; (Eph. 4:17), but &quot;walk in love, as Christ loved us and gave himself up for us&quot; (Eph. 5:2). In Him, you have been &quot;created after the likeness of God in true righteousness and holiness&quot; (Eph. 4:24). Therefore, &quot;be imitators of God, as beloved children&quot; (Eph. 5:1), by &quot;forgiving one another, as God in Christ forgave you&quot; (Eph. 4:32).</div>', '1 Kings 19:1–8', 'Psalm 34:1-8', 'Eph. 4:17—5:2', 'John 6:35–51', '<div>You open | your hand; * </div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;you satisfy the desire of every | living thing.</strong></div>\r\n\r\n<div>Oh, taste and see that the | LORD is good! *</div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;Blessed is the man who takes ref- | uge in him!</strong></div>\r\n\r\n<div>Oh, fear the LORD, | you his saints, *</div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;for those who fear him | have no lack!</strong></div>\r\n\r\n<div>The young lions suffer want and | hunger; *</div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;but those who seek the LORD lack | no good thing.</strong></div>\r\n\r\n<div><strong>Glory be to the Father…</strong></div>\r\n\r\n<div>You open | your hand; * </div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;you satisfy the desire of every | living thing.</strong></div>', '<div><font face=\"Goudy Old Style\" size=2 color=black>Entrance: 793 Praise, My Soul, the King of Heaven </font></div>\r\n\r\n<div><font face=\"Goudy Old Style\" size=2 color=black>Of the Day: 534 Lord, Enthroned in Heavenly Splendor </font></div>\r\n\r\n<div><font face=\"Goudy Old Style\" size=2 color=black>Offertory: 774 Feed Thy Children, God Most Holy </font></div>\r\n\r\n<div><font face=\"Goudy Old Style\" size=2 color=black>Distribution: </font></div>\r\n\r\n<div><font face=\"Goudy Old Style\" size=2 color=black>&nbsp;&nbsp;&nbsp;&nbsp;865 Lord, Help Us Ever to Retain </font></div>\r\n\r\n<div><font face=\"Goudy Old Style\" size=2 color=black>&nbsp;&nbsp;&nbsp;&nbsp;724 If God Himself Be for Me </font></div>\r\n\r\n<div><font face=\"Goudy Old Style\" size=2 color=black>Closing: 576 My Hope Is Built on Nothing Less </font></div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (412, 2650, 'B', 'PENTECOST', 'Sunday on August 14-20 (Proper 15)', 'Green', '<div><strong>Jesus Is the Word and Wisdom of God, Who Gives You Life and Light in His Flesh</strong></div>\r\n\r\n<div>Jesus is the divine Word by whom all things were made, who has become flesh and dwells among us. He gives His flesh &quot;for the life of the world,&quot; not only as a sacrifice for sin but as &quot;the living bread&quot; from heaven (John 6:51). Eat His flesh and drink His blood (John 6:54_57), and no longer walk in the darkness of sin, but walk in His light. &quot;Arise from the dead&quot; and live in Him, because you are &quot;light in the Lord&quot; (Eph. 5:8, 14). Being filled with His Spirit, confess Him to &quot;one another in psalms and hymns and spiritual songs, singing and making melody to the Lord with all your heart&quot; (Eph. 5:18_19). Fear, love and trust in Him, &quot;and serve him in sincerity and faithfulness&quot; (Josh. 24:14). For He has brought you &quot;out of the house of slavery&quot; by His cross and resurrection, and now He does &quot;great signs&quot; in your sight (Josh. 24:17). Indeed, He is the divine wisdom, who has built His house, prepared His feast and set His table; He bids you to recline and eat of His bread and drink of the wine He has mixed (Prov. 9:1_5).</div>', 'Prov. 9:1–10 or Josh. 24:1–2a, 14–18', 'Psalm 34:12–22', 'Eph. 5:6–21', 'John 6:51–69', '<div>Introit Psalm 111:1–5, 9; antiphon: v. 10</div>\r\n\r\n<div>The fear of the Lord is the beginning of wisdom; all those who practice it have a good understanding.</div>\r\n\r\n<div>\tHis praise endures forever!</div>\r\n\r\n<div>Praise the Lord! I will give thanks to the Lord with my whole heart,</div>\r\n\r\n<div>\tin the company of the upright, in the congregation.</div>\r\n\r\n<div>Great are the works of the Lord,</div>\r\n\r\n<div>\tstudied by all who delight in them.</div>\r\n\r\n<div>Full of splendor and majesty is his work,</div>\r\n\r\n<div>\tand his righteousness endures forever.</div>\r\n\r\n<div>He has caused his wondrous works to be remembered;</div>\r\n\r\n<div>\tthe Lord is gracious and merciful.</div>\r\n\r\n<div>He provides food for those who fear him;</div>\r\n\r\n<div>\the remembers his covenant forever.</div>\r\n\r\n<div>He sent redemption to his people; he has commanded his covenant forever.</div>\r\n\r\n<div>\tHoly and awesome is his name!</div>\r\n\r\n<div>Glory be to the Father and to the Son</div>\r\n\r\n<div>\tand to the Holy Spirit;</div>\r\n\r\n<div>as it was in the beginning,</div>\r\n\r\n<div>\tis now, and will be forever. Amen.</div>\r\n\r\n<div>The fear of the Lord is the beginning of wisdom; all those who practice it have a good understanding.</div>\r\n\r\n<div>\tHis praise endures forever!</div>', '<div><font face=\"Times New Roman\" size=2 color=black>Entrance: &nbsp;905 Come, Thou Almighty King</font></div>\r\n\r\n<div><font face=\"Times New Roman\" size=2 color=black>Of the Day: &nbsp;566 By Grace I’m Saved</font></div>\r\n\r\n<div><font face=\"Times New Roman\" size=2 color=black>Offertory: 665 Be Strong in the Lord</font></div>\r\n\r\n<div><font face=\"Times New Roman\" size=2 color=black>Distribution:</font></div>\r\n\r\n<div><font face=\"Times New Roman\" size=2 color=black>&nbsp;&nbsp;&nbsp;&nbsp;565 Thy Works, Not Mine, O Christ</font></div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<font face=\"Times New Roman\" size=2 color=black>559 Oh, How Great Is Your Compassion </font></div>\r\n\r\n<div><font face=\"Times New Roman\" size=2 color=black>Closing: &nbsp;664 Fight the Good Fight &nbsp;</font></div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (413, 2660, 'B', 'PENTECOST', 'Sunday on August 21-27 (Proper 16)', 'Green', '<div><strong>The True Tradition of the Church Is the Ministry of the Gospel of Christ Jesus, Her Savior</strong></div>\r\n\r\n<div>The true tradition of the Church is the Gospel, which is the preaching and administration of Christ Jesus. Other traditions, although not commanded by God, may serve and support that sacred tradition of the Gospel. But the Church dare not &quot;[reject] the commandment of God&quot; in order to establish or hold to &quot;the tradition of men&quot; (Mark 7:8_9). Sinful people attempt to draw near to the Lord &quot;with their mouth&quot; and to honor Him &quot;with their lips,&quot; while their hearts are far removed from Him (Is. 29:13). Yet, He is &quot;the Holy One of Israel,&quot; who brings about salvation by His cross. Therefore, &quot;the wisdom of their wise men shall perish,&quot; but &quot;the deaf shall hear&quot; and &quot;the eyes of the blind shall see&quot; (Is. 29:14_19). This mystery of Christ is profound, for He is the Husband of the Church, and He is her Savior. Not because of any works that she has done, but solely for the sake of His great love, He &quot;gave himself up for her, that he might sanctify her, having cleansed her by the washing of water with the word&quot; (Eph. 5:25_26).</div>', 'Is. 29:11–19', 'Psalm 14', 'Eph. 5:22–33', 'Mark 7:1–13', '<div><strong>INTROIT Psalm 26:1–2, 6–7; antiphon: v. 8</strong></div>\r\n\r\n<div>O Lord, I love the habitation | of your house *</div>\r\n\r\n<div><strong>&nbsp;and the place where your | glory dwells.</strong></div>\r\n\r\n<div>Vindicate me, O Lord, for I have walked in my in - tegrity, *</div>\r\n\r\n<div><strong>&nbsp;and I have trusted in the Lord | without wavering.</strong></div>\r\n\r\n<div>Prove me, O Lord, and | try me; *</div>\r\n\r\n<div><strong>&nbsp;test my heart | and my mind.</strong></div>\r\n\r\n<div>I wash my hands in innocence and go around your altar, | O Lord, *</div>\r\n\r\n<div><strong>&nbsp;proclaiming thanksgiving aloud, and telling all your | wondrous deeds.</strong></div>\r\n\r\n<div><strong>Glory be to the Father …</strong></div>\r\n\r\n<div>O Lord, I love the habitation | of your house *</div>\r\n\r\n<div><strong>&nbsp;and the place where your | glory dwells.</strong></div>', '<div>Entrance: 822 Alleluia! Let Praises Ring </div>\r\n\r\n<div>Of the Day: 589 Speak, O Lord, Your Servant Listens </div>\r\n\r\n<div>Offertory: 865 Lord, Help Us Ever to Retain </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;713 From God Can Nothing Move Me </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;644 The Church’s One Foundation </div>\r\n\r\n<div>Closing: 862 Oh, Blest the House </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (414, 2670, 'B', 'PENTECOST', 'Sunday on August 28-September 3 (Proper 17)', 'Green', '<div><strong>We Are Cleansed and Sustained by the Word of God</strong></div>\r\n\r\n<div>Wickedness and evil come &quot;from within, out of the heart,&quot; and that is what defiles a person (Mark 7:21_23). Hence, we cannot save ourselves, because we are sinful and unclean from the inside out. But as the Lord Jesus &quot;declared all foods clean&quot; (Mark 7:19), so He cleanses us by His Word, by the preaching of repentance and the forgiveness of sins. Therefore, &quot;listen to the statutes and the rules&quot; of the Lord, &quot;and do them, that you may live&quot; (Deut. 4:1). For His Word is righteous, and to live according to it is &quot;your wisdom and your understanding in the sight of the peoples&quot; (Deut. 4:6). Cling to His Word, and also teach it &quot;to your children and your children\'s children&quot; (Deut. 4:9). Put on this &quot;armor of God&quot; by hearing and heeding what He speaks to you, that you may &quot;stand firm&quot; in the evil day (Eph. 6:11_13). Gird yourself with the righteousness of Christ, by faith in the &quot;gospel of peace,&quot; and take up &quot;the sword of the Spirit, which is the word of God,&quot; by confessing Christ Jesus and &quot;praying at all times in the Spirit&quot; (Eph. 6:14_18).</div>', 'Deut. 4:1–2, 6–9', 'Psalm 119:129-136', 'Eph. 6:10–20', 'Mark 7:14–23', '<div>Introit\tPsalm 51:7, 10–12; antiphon: v. 2</div>\r\n\r\n<div>Wash me thoroughly from my in- | iquity, *</div>\r\n\r\n<div><strong>\tand cleanse me | from my sin!</strong></div>\r\n\r\n<div>Purge me with hyssop, and | I shall be clean; *</div>\r\n\r\n<div><strong>\twash me, and I shall be whit- | er than snow.</strong></div>\r\n\r\n<div>Create in me a clean heart, | O God, *</div>\r\n\r\n<div><strong>\tand renew a right spirit with- | in me.</strong></div>\r\n\r\n<div>Cast me not away from your | presence, *</div>\r\n\r\n<div><strong>\tand take not your Holy Spirit | from me.</strong></div>\r\n\r\n<div>Restore to me the joy of your sal- | vation, *</div>\r\n\r\n<div><strong>\tand uphold me with a willing | spirit.</strong></div>\r\n\r\n<div><strong>Glory be to the Father and | to the Son *</strong></div>\r\n\r\n<div><strong>\tand to the Holy | Spirit;</strong></div>\r\n\r\n<div><strong>as it was in the be- | ginning, *</strong></div>\r\n\r\n<div><strong>\tis now, and will be forever. | Amen.</strong></div>\r\n\r\n<div>Wash me thoroughly from my in- | iquity, *</div>\r\n\r\n<div><strong>\tand cleanse me | from my sin!</strong></div>', '<div>Entrance: 867 Let Children Hear the Mighty Deeds </div>\r\n\r\n<div>Of the Day: 566 By Grace I’m Saved </div>\r\n\r\n<div>Offertory: 777 Grant Peace, We Pray, in Mercy, Lord </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;559 Oh, How Great Is Your Compassion </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;696 O God, My Faithful God </div>\r\n\r\n<div>Closing: 662 Onward, Christian Soldier </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (415, 2680, 'B', 'PENTECOST', 'Sunday on September 4-10 (Proper 18)', 'Green', '<div><strong>Our Merciful Lord and Savior, Jesus Christ, Does All Things Well</strong></div>\r\n\r\n<div>The Lord proclaims the Gospel &quot;to those who have an anxious heart&quot; to comfort and encourage them with His presence. He comes not only with threats of &quot;vengeance&quot; and &quot;recompense,&quot; but with His gracious salvation (Is. 35:4). He opens &quot;the eyes of the blind&quot; and &quot;the ears of the deaf,&quot; and He loosens &quot;the tongue of the mute&quot; to &quot;sing for joy&quot; (Is. 35:5_6). Like water on thirsty ground, He speaks His life-giving Word to people of all nations. With His Word and the touch of His hand, He does &quot;all things well,&quot; so that you may now speak &quot;plainly&quot; (Mark 7:31_37). You confess the truth of God in Christ to the glory of His holy name, and you call upon His name in every trouble, confident that He will hear and answer. As you pray and confess with your tongue, so also &quot;love your neighbor as yourself&quot; (James 2:8). Show your faith &quot;in our Lord Jesus Christ, the Lord of glory,&quot; by loving without partiality. For God has &quot;chosen those who are poor in the world to be rich in faith and heirs of the kingdom&quot; (James 2:1_5).</div>', 'Is. 35:4–7a', 'Psalm 146', 'James 2:1–10, 14–18', 'Mark 7:(24–30) 31–37', '<div><font color=black><strong>Introit Psalm 28:1–2, 6–7; antiphon: v. 8</strong></font></div>\r\n\r\n<div><font color=black>The Lord is the strength of his | people; *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;he is the saving refuge of his an- | ointed.</strong></font></div>\r\n\r\n<div><font color=black>To you, O Lord, I call; my rock, be not | deaf to me, *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;lest, if you be silent to me, I become like those who go down | to the pit.</strong></font></div>\r\n\r\n<div><font color=black>Hear the voice of my pleas for mercy, when I cry to | you for help, *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;when I lift up my hands toward your most holy san- | ctuary.</strong></font></div>\r\n\r\n<div><font color=black>Blessèd | be the Lord! *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;For he has heard the voice of my pleas for | mercy.</strong></font></div>\r\n\r\n<div><font color=black>The Lord is my strength and my shield; in him my heart trusts, and | I am helped; *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;my heart exults, and with my song I give | thanks to him.</strong></font></div>\r\n\r\n<div><font color=black><strong>Glory be to the Father and | to the Son *</strong></font></div>\r\n\r\n<div><font color=black><strong>&nbsp;and to the Holy | Spirit;</strong></font></div>\r\n\r\n<div><font color=black><strong>as it was in the be- | ginning, *</strong></font></div>\r\n\r\n<div><font color=black><strong>&nbsp;is now, and will be forever. | Amen.</strong></font></div>\r\n\r\n<div><font color=black>The Lord is the strength of his | people; *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;he is the saving refuge of his an- | ointed.</strong></font></div>', '<div>Entrance: 545 Word of God, Come Down on Earth </div>\r\n\r\n<div>Of the Day: 797 Praise the Almighty </div>\r\n\r\n<div>Offertory: 841 O Son of God, in Galilee </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;637 Draw Near and Take the Body of the Lord </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;846 Your Hand, O Lord, in Days of Old </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;749 There Is a Balm in Gilead </div>\r\n\r\n<div>Closing: 643 Sent Forth by God’s Blessing </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (416, 2690, 'B', 'PENTECOST', 'Sunday on September 11-17 (Proper 19)', 'Green', '<div><strong>Christ Jesus Delivers Us from Sin, Death and the Devil</strong></div>\r\n\r\n<div>Those who teach the Word of God &quot;will be judged with greater strictness&quot; (James 3:1) because it is by the Word that saving faith is obtained, whereas false doctrine always threatens to destroy Christian faith and life. The tongue &quot;boasts of great things,&quot; whether for good or evil (James 3:5). In fallen man, &quot;it is a restless evil, full of deadly poison&quot; (James 3:8). But anyone who bridles his tongue with the Word of God, who &quot;does not stumble in what he says, he is a perfect man&quot; (James 3:2). It is Christ who opens His ear to the voice of His Father, so that, with &quot;the tongue of those who are taught,&quot; He is able to sustain the weary &quot;with a word&quot; (Is. 50:4_5). Entrusting Himself to His Father, even to death, He is not put to shame but is vindicated in His resurrection (Is. 50:6_9). By His faith and faithfulness, He casts out the &quot;mute and deaf spirit&quot; from us (Mark 9:25). He has compassion on us and helps us, so that we are not destroyed but cleansed from every evil and raised up from death to life (Mark 9:22_27).</div>', 'Is. 50:4–10', 'Psalm 116:1-9', 'James 3:1–12', 'Mark 9:14–29', '<div><font color=black><strong>Introit Psalm 31:14–16; antiphon: v. 24</strong></font></div>\r\n\r\n<div><font color=black>Be strong, and let your heart take | courage, *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;all you who wait | for the Lord!</strong></font></div>\r\n\r\n<div><font color=black>But I trust in you, | O Lord; *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;I say, “You | are my God.”</strong></font></div>\r\n\r\n<div><font color=black>My times are | in your hand; *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;rescue me from the hand of my enemies and from my perse- | cutors!</strong></font></div>\r\n\r\n<div><font color=black>Make your face shine on your | servant; *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;save me in your | steadfast love!</strong></font></div>\r\n\r\n<div><font color=black><strong>Glory be to the Father and | to the Son *</strong></font></div>\r\n\r\n<div><font color=black><strong>and to the Holy | Spirit;</strong></font></div>\r\n\r\n<div><font color=black><strong>as it was in the be- | ginning, *</strong></font></div>\r\n\r\n<div><font color=black><strong>is now, and will be forever. | Amen.</strong></font></div>\r\n\r\n<div><font color=black>Be strong, and let your heart take | courage, *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;all you who wait | for the Lord!</strong></font></div>\r\n\r\n<div>&nbsp;</div>', '<div>Entrance: 528 Oh, for a Thousand Tongues to Sing</div>\r\n\r\n<div>Of the Day: 849 Praise the One Who Breaks the Darkness </div>\r\n\r\n<div>Offertory: 846 Your Hand, O Lord, in Days of Old </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;620 Jesus Comes Today with Healing </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;770 What a Friend We Have in Jesus </div>\r\n\r\n<div>Closing: 533 Jesus Has Come and Brings Pleasure </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (417, 2700, 'B', 'PENTECOST', 'Sunday on September 18-24 (Proper 20)', 'Green', '<div><strong>Our Father Cares for His Children with the Gospel of His Son</strong></div>\r\n\r\n<div>The sinful heart is filled with &quot;bitter jealousy and selfish ambition&quot; (James 3:14), which causes hostility, quarrels and conflicts, even among those who are fellow members of the body of Christ. This should not be so! Rather, God &quot;opposes the proud&quot; with His Law, in order to humble them unto repentance; He &quot;gives grace to the humble,&quot; in order to exalt them by His Gospel of forgiveness (James 4:6_10). This true &quot;wisdom from above&quot; is found in the gentleness, mercy and peace of our Lord, Jesus Christ, who humbled Himself and sacrificed Himself for the salvation of sinners (James 3:17). He was &quot;like a gentle lamb led to the slaughter,&quot; committing Himself to God, His Father, &quot;who judges righteously, who tests the heart and the mind&quot; (Jer. 11:19_20). Therefore, &quot;after three days,&quot; His Father exalted Him by raising Him from the dead (Mark 9:31). In Holy Baptism, He takes disciples of all ages into His arms like little children. In receiving Him through repentance and faith in His forgiveness of sins, they receive from His Father a share in the glory of His cross and resurrection (Mark 9:36_37).</div>', 'Jer. 11:18–20', 'Psalm 54', 'James 3:13—4:10', 'Mark 9:30–37', '<div>INTROIT\tPsalm 37:5–7; antiphon: v. 4</div>\r\n\r\n<div>Delight yourself | in the Lord, *</div>\r\n\r\n<div><strong>\tand he will give you the desires | of your heart.</strong></div>\r\n\r\n<div>Commit your way | to the Lord; *</div>\r\n\r\n<div><strong>\ttrust in him, and | he will act.</strong></div>\r\n\r\n<div>He will bring forth your righteousness | as the light, *</div>\r\n\r\n<div><strong>\tand your justice as the | noonday.</strong></div>\r\n\r\n<div>Be still before the Lord and wait patiently | for him; *</div>\r\n\r\n<div>\tfret not yourself over the one who prospers <strong>in his way, over the man who carries out evil dev- | ices!</strong></div>\r\n\r\n<div><strong>Glory be to the Father and | to the Son</strong></div>\r\n\r\n<div><strong>and to the Holy | Spirit;</strong></div>\r\n\r\n<div><strong>as it was in the be - | ginning,</strong></div>\r\n\r\n<div><strong>is now, and will be forever. | Amen.</strong></div>\r\n\r\n<div>Delight yourself | in the Lord, *</div>\r\n\r\n<div><strong>\tand he will give you the desires | of your heart.</strong></div>', '<div>Entrance: 725 Children of the Heavenly Father </div>\r\n\r\n<div>Of the Day: 851 Lord of Glory, You Have Bought Us </div>\r\n\r\n<div>Offertory: 558 Not unto Us </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;561 The Tree of Life </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;605 Father Welcomes </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;971 There Is a Redeemer (Lutheran Service Builder) </div>\r\n\r\n<div>Closing: 652 Father, We Thank Thee </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (418, 2710, 'B', 'PENTECOST', 'Sunday on September 25-October 1 (Proper 21)', 'Green', '<div><strong>Christ Jesus, the Son of God, Cares for Us and Serves Us with the Forgiveness of Sins</strong></div>\r\n\r\n<div>When the people of Israel wept, complaining that they had no meat to eat (Num. 11:4), Moses cried out to the Lord that &quot;the burden of all this people&quot; was too heavy for him and that he was &quot;not able to carry all this people alone&quot; (Num. 11:11_14). So the Lord had Moses gather &quot;seventy men of the elders of Israel&quot; (Num. 11:16), and the Lord &quot;took some of the Spirit that was on him and put it on the seventy elders&quot; (Num. 11:25), so that Moses would not carry the burden alone. All who thus labor are honored, and all the people are cared for, in the name of the Lord (Mark 9:39_41). Everything is done with reference to Christ Jesus. So we cling to Him, and we flee from all sins that would separate us from Him (Mark 9:42_48). The life of the Church is one of repentant faith in Christ. Christians confess their sins to one another, and they &quot;pray for one another,&quot; that each would be raised up and healed by the Lord Jesus, who covers &quot;a multitude of sins&quot; and saves our souls from death (James 5:15_20).</div>', 'Num. 11:4–6, 10–16, 24–29', 'Psalm 104:27-35', 'James 5:(1–12) 13–20', 'Mark 9:38–50', '<div><strong>Introit\tPsalm 135:1–3, 13–14; antiphon: v. 13</strong></div>\r\n\r\n<div>Your name, O Lord, endures for- | ever, *</div>\r\n\r\n<div><strong>\tyour renown, O Lord, throughout all | ages.</strong></div>\r\n\r\n<div>Praise the Lord! Praise the name | of the Lord, *</div>\r\n\r\n<div><strong>\tgive praise, O servants | of the Lord,</strong></div>\r\n\r\n<div>who stand in the house | of the Lord, *</div>\r\n\r\n<div><strong>\tin the courts of the house | of our God!</strong></div>\r\n\r\n<div>Praise the Lord, for the | Lord is good; *</div>\r\n\r\n<div><strong>\tsing to his name, for it | is pleasant!</strong></div>\r\n\r\n<div>Your name, O Lord, endures for- | ever, *</div>\r\n\r\n<div><strong>\tyour renown, O Lord, throughout all | ages.</strong></div>\r\n\r\n<div>For the Lord will vindicate his | people *</div>\r\n\r\n<div><strong>\tand have compassion on his | servants.</strong></div>\r\n\r\n<div><strong>Glory be to the Father and | to the Son</strong></div>\r\n\r\n<div><strong>\tand to the Holy | Spirit;</strong></div>\r\n\r\n<div><strong>as it was in the beg- | inning,</strong></div>\r\n\r\n<div><strong>\tis now, and will be forever. | Amen.</strong></div>\r\n\r\n<div>Your name, O Lord, endures for- | ever, *</div>\r\n\r\n<div><strong>\tyour renown, O Lord, throughout all | ages.</strong></div>', '<div>Entrance: 797 Praise the Almighty </div>\r\n\r\n<div>Of the Day: 848 Lord, Whose Love through Humble Service </div>\r\n\r\n<div>Offertory: 505 Triune God, Be Thou Our Stay </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;623 Lord Jesus Christ, We Humbly Pray </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;718 Jesus, Lead Thou </div>\r\n\r\n<div>On Closing: 850 God of Grace and God of Glory </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (419, 2720, 'B', 'PENTECOST', 'Sunday on October 2-8 (Proper 22)', 'Green', '<div><strong>Marriage Is a Sign that Manifests the Gospel of Christ and His Church</strong></div>\r\n\r\n<div>Humanity is created in the image and likeness of God. &quot;It is not good that the man should be alone&quot; (Gen. 2:18). For the Lord Himself is a perfect communion of three Persons - the Father, Son and Holy Spirit - in one God. Therefore, &quot;the Lord God caused a deep sleep to fall upon the man, and while he slept took one of his ribs,&quot; which &quot;he made into a woman&quot; and brought &quot;to the man&quot; (Gen. 2:21_22). It is for this reason that &quot;a man shall leave his father and his mother and hold fast to his wife, and they shall become one flesh&quot; (Gen. 2:24; Mark 10:7). This great mystery of holy marriage signifies Christ Jesus, the incarnate Son of God, and His Bride, the Church. Divorce and all manner of adultery contradict and undermine this sign, and in doing so, they confess a false Christ and a false gospel. &quot;What therefore God has joined together, let not man separate&quot; (Mark 10:9). In truth, Christ Jesus has atoned for all such sins, and He has perfected marriage in Himself &quot;through suffering,&quot; that He might bring &quot;many sons to glory&quot; in His resurrection (Heb. 2:8_10).</div>', 'Gen. 2:18–25', 'Psalm 128', 'Heb. 2:1–13 (14–18)', 'Mark 10:2–16', '<div><strong>Introit\tPsalm 127:3–5; antiphon: v. 1a</strong></div>\r\n\r\n<div>Unless the Lord | builds the house, *</div>\r\n\r\n<div><strong>\tthose who build it la- | bor in vain.</strong></div>\r\n\r\n<div>Behold, children are a heritage | from the Lord, *</div>\r\n\r\n<div><strong>\tthe fruit of the womb | a reward.</strong></div>\r\n\r\n<div>Like arrows in the hand of a | warrior *</div>\r\n\r\n<div><strong>\tare the children | of one’s youth.</strong></div>\r\n\r\n<div>Blessèd is the man who fills his quiver | with them!</div>\r\n\r\n<div><strong>\tHe shall not be put to shame when he speaks with his enemies | in the gate.</strong></div>\r\n\r\n<div><strong>Glory be to the Father and </strong>| <strong>to the Son</strong></div>\r\n\r\n<div><strong>\tand to the Holy </strong>| <strong>Spirit;</strong></div>\r\n\r\n<div><strong>as it was in the be- </strong>| <strong>ginning,</strong></div>\r\n\r\n<div><strong>\tis now, and will be forever. </strong>| <strong>Amen.</strong></div>\r\n\r\n<div>Unless the Lord | builds the house, *</div>\r\n\r\n<div><strong>&nbsp;those who build it la- | bor in vain.</strong></div>', '<div><font face=\"Goudy Old Style\" size=2 color=black>Entrance: 869 With the Lord Begin Your Task </font></div>\r\n\r\n<div><font face=\"Goudy Old Style\" size=2 color=black>Of the Day: 853 How Clear Is Our Vocation, Lord </font></div>\r\n\r\n<div><font face=\"Goudy Old Style\" size=2 color=black>Offertory: 806 Give Thanks with a Grateful </font></div>\r\n\r\n<div><font face=\"Goudy Old Style\" size=2 color=black>Heart </font></div>\r\n\r\n<div><font face=\"Goudy Old Style\" size=2 color=black>Distribution: </font></div>\r\n\r\n<div><font face=\"Goudy Old Style\" size=2 color=black>&nbsp;&nbsp;&nbsp;&nbsp;594 God’s Own Child, I Gladly Say It </font></div>\r\n\r\n<div><font face=\"Goudy Old Style\" size=2 color=black>&nbsp;&nbsp;&nbsp;&nbsp;685 Let Us Ever Walk with Jesus </font></div>\r\n\r\n<div><font face=\"Goudy Old Style\" size=2 color=black>Closing: 549 All Hail the Power of Jesus’ Name </font></div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (420, 2730, 'B', 'PENTECOST', 'Sunday on October 9-15 (Proper 23)', 'Green', '<div><strong>Christ Jesus Is the One and Only Good by Whom You Inherit Eternal Life</strong></div>\r\n\r\n<div>The Lord is the Author and Giver of life, as well as a consuming fire of judgment against all &quot;who afflict the righteous, who take a bribe, and turn aside the needy in the gate&quot; (Amos 5:12). &quot;Seek the Lord and live,&quot; therefore, by hating what is evil, loving what is good and doing what is just and right, according to His Word. &quot;And so the Lord, the God of hosts, will be with you&quot; (Amos 5:6, 14_15). Understand that &quot;no one is good except God alone&quot; (Mark 10:18). The life that you are called to live is found neither in your &quot;great possessions,&quot; nor in your good works, but only in Christ Jesus. Let go of &quot;all that you have&quot; and follow Him, even unto death, and &quot;you will have treasure in heaven&quot; (Mark 10:21_22). Do not harden your heart against His voice, nor turn away from Him, lest you &quot;fall away from the living God.&quot; Rather, hear and heed His call, cling to His Word and &quot;exhort one another every day,&quot; that you may remain steadfast in Christ and &quot;firm to the end&quot; (Heb. 3:12_15).</div>', 'Amos 5:6–7, 10–15', 'Psalm 90:12-17', 'Heb. 3:12–19', 'Mark 10:17–22', '<div><font color=black><strong>Introit Psalm 112:3–6; antiphon: v. 1</strong></font></div>\r\n\r\n<div><font color=black>Praise the Lord! Blessèd is the man who | fears the Lord,</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;who greatly delights in his com- | mandments!</strong></font></div>\r\n\r\n<div><font color=black>Wealth and riches are | in his house,</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;and his righteousness endures for- | ever.</strong></font></div>\r\n\r\n<div><font color=black>Light dawns in the darkness for the | upright;</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;he is gracious, merciful, and | righteous.</strong></font></div>\r\n\r\n<div><font color=black>It is well with the man who deals generous- | ly and lends;</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;who conducts his affairs with | justice.</strong></font></div>\r\n\r\n<div><font color=black>For the righteous will nev- | er be moved;</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;he will be remembered for- | ever.</strong></font></div>\r\n\r\n<div><font color=black><strong>Glory be to the Father and | to the Son</strong></font></div>\r\n\r\n<div><font color=black><strong>and to the Holy | Spirit;</strong></font></div>\r\n\r\n<div><font color=black><strong>as it was in the be- | ginning,</strong></font></div>\r\n\r\n<div><font color=black><strong>is now, and will be forever. | Amen.</strong></font></div>\r\n\r\n<div><font color=black>Praise the Lord! Blessèd is the man who | fears the Lord,</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;who greatly delights in his com- | mandments!</strong></font></div>', '<div>Entrance: 725 Children of the Heavenly Father </div>\r\n\r\n<div>Of the Day: 851 Lord of Glory, You Have Bought Us </div>\r\n\r\n<div>Offertory: 558 Not unto Us </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;561 The Tree of Life </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;605 Father Welcomes </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;971 There Is a Redeemer (Lutheran Service Builder) </div>\r\n\r\n<div>Closing: 652 Father, We Thank Thee </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (421, 2740, 'B', 'PENTECOST', 'Sunday on October 16-22 (Proper 24)', 'Green', '<div><strong>By the Voluntary Poverty of Christ, We Enter the Kingdom of God</strong></div>\r\n\r\n<div>To love and trust in earthly wealth is vanity. For nothing of this earth will last forever, nor can any of it grant eternal life (Eccl. 5:10). But the one who trusts in God is &quot;occupied with joy in his heart&quot; and is able to sleep in peace, &quot;whether he eats little or much,&quot; because he knows that the &quot;days of his life&quot; are &quot;the gift of God&quot; (Eccl. 5:12, 18_20). The person who trusts in riches cannot sleep, because he &quot;shall take nothing for his toil that he may carry away in his hand&quot; (Eccl. 5:15). Therefore, it is difficult &quot;for those who have wealth to enter the kingdom of God&quot; (Mark 20:23). Indeed, it is impossible for man, yet &quot;all things are possible with God&quot; (Mark 20:27). Thus, the Rich Man, Jesus Christ, has made Himself poor and has gone through &quot;the eye of a needle,&quot; through death and the grave, &quot;to enter the kingdom of God&quot; on our behalf (Mark 20:24_25). He is the &quot;great high priest who has passed through the heavens&quot; (Heb. 4:14), so that we may now enter His Sabbath rest by faith in His forgiveness (Heb. 4:3_9).</div>', 'Eccl. 5:10–20', 'Psalm 119:9-16', 'Heb. 4:1–13 (14–16)', 'Mark 10:23–31', '<div><strong>Introit Psalm 34:1–4, 17; antiphon: v. 18</strong></div>\r\n\r\n<div>The Lord is near to the broken- | hearted</div>\r\n\r\n<div><strong>&nbsp;and saves the crushed in | spirit.</strong></div>\r\n\r\n<div>I will bless the Lord at all times;</div>\r\n\r\n<div><strong>&nbsp;his praise shall continually be | in my mouth.</strong></div>\r\n\r\n<div>My soul makes its boast | in the Lord;</div>\r\n\r\n<div><strong>&nbsp;let the humble hear and be glad.</strong></div>\r\n\r\n<div>Oh, magnify the | LORD with me,</div>\r\n\r\n<div><strong>&nbsp;and let us exalt his name to- | gether!</strong></div>\r\n\r\n<div>I sought the Lord, and he | answered me</div>\r\n\r\n<div><strong>&nbsp;and delivered me from | all my fears.</strong></div>\r\n\r\n<div>When the righteous cry for help, the | LORD hears</div>\r\n\r\n<div><strong>&nbsp;and delivers them out of all their | troubles.</strong></div>\r\n\r\n<div><strong>Glory be to the Father and | to the Son</strong></div>\r\n\r\n<div><strong>&nbsp;and to the Holy | Spirit;</strong></div>\r\n\r\n<div><strong>as it was in the be- | ginning,</strong></div>\r\n\r\n<div><strong>&nbsp;is now, and will be forever. | Amen.</strong></div>\r\n\r\n<div>The Lord is near to the broken- | hearted</div>\r\n\r\n<div><strong>&nbsp;and saves the crushed in | spirit.</strong></div>', '<div>Entrance: 907 God Himself Is Present </div>\r\n\r\n<div>Of the Day: 690 Hope of the World </div>\r\n\r\n<div>Offertory: 712 Seek Ye First </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;602 The Gifts Christ Freely Gives </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;782 Gracious God, You Send Great Blessings </div>\r\n\r\n<div>Closing: 850 God of Grace and God of Glory </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (422, 2750, 'B', 'PENTECOST', 'Sunday on October 23-29 (Proper 25)', 'Green', '<div><strong>The Lord Jesus Christ Opens Our Eyes to God and Brings Us into His Presence</strong></div>\r\n\r\n<div>As He did for blind Bartimeaus, so does the Lord, Jesus Christ, have mercy upon you. With His Word of the Gospel, &quot;He is calling you&quot; to Himself, to &quot;take heart,&quot; to rise up and live by faith in His forgiveness. He opens your heart and mind to see and know God rightly in Him and to follow Him &quot;on the way&quot; of the cross and into life everlasting (Mark 10:49_52). &quot;He is able to save to the uttermost those who draw near to God through Him,&quot; because He is the great High Priest, who offered Himself &quot;once for all&quot; as a sacrifice for sins. Since He is risen from the dead and &quot;exalted above the heavens,&quot; He &quot;holds His priesthood permanently, because He continues forever,&quot; and &quot;He always lives to make intercession&quot; for His people (Heb. 7:24_27). Along with that, He gathers the children of God to Himself by the proclamation of His Gospel, even &quot;from the farthest parts of the earth.&quot; In mercy He calls them, by the waters of Holy Baptism, &quot;in a straight path in which they shall not stumble,&quot; unto life everlasting (Jer. 31:8_9).</div>', 'Jer. 31:7–9', 'Psalm 126', 'Heb. 7:23–28', 'Mark 10:46–52', '<div><font color=black><strong>Introit Psalm 131; antiphon: Psalm 130:1–2</strong></font></div>\r\n\r\n<div><font color=black>Out of the depths I cry to you, | O Lord!</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;O Lord, hear my voice! Let your ears be attentive to the voice of my pleas for | mercy!</strong></font></div>\r\n\r\n<div><font color=black>O Lord, my heart is not lifted up; my eyes are not | raised too high;</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;I do not occupy myself with things too great and too marve- | lous for me.</strong></font></div>\r\n\r\n<div><font color=black>But I have calmed and quieted my soul, like a weaned child with its | mother;</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;like a weaned child is my soul with- | in me.</strong></font></div>\r\n\r\n<div><font color=black>O Israel, hope | in the Lord</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;from this time forth and for- | evermore.</strong></font></div>\r\n\r\n<div><font color=black><strong>Glory be to the Father and | to the Son</strong></font></div>\r\n\r\n<div><font color=black><strong>&nbsp;and to the Holy | Spirit;</strong></font></div>\r\n\r\n<div><font color=black><strong>as it was in the be- | ginning,</strong></font></div>\r\n\r\n<div><font color=black><strong>&nbsp;is now, and will be forever. | Amen.</strong></font></div>\r\n\r\n<div><font color=black>Out of the depths I cry to you, | O Lord!</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;O Lord, hear my voice! Let your ears be attentive to the voice of my pleas for | mercy!</strong></font></div>\r\n\r\n<div>&nbsp;</div>', '<div>Entrance: 819 Sing Praise to God, the Highest Good </div>\r\n\r\n<div>Of the Day: 713 From God Can Nothing Move Me </div>\r\n\r\n<div>Offertory: 942 Kyrie! God, Father </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;915 Today Your Mercy Calls Us </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;620 Jesus Comes Today with Healing </div>\r\n\r\n<div>Closing: 744 Amazing Grace </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (608, 5100, 'F', NULL, 'The Purification of Mary and the Presentation of Our Lord (February 2)', 'White', NULL, '1 Sam 1:21-28', 'Psalm 84', 'Heb 2:14-18', 'Luke 2:22-32(33-40)', '<div>INTROIT Ps. 48:1–3, 8; antiphon: Ps. 48:9 We have thought on your steadfast love, | O God,* in the midst of your | temple. Great is the LORD and greatly | to be praised* in the city | of our God! His holy mountain, beautiful in elevation, is the joy of | all the earth,* Mount Zion, in the far north, the city of the | great King. Within her | citadels* God has made himself known as a | fortress. As we have heard, so have we seen in the city of the LORD of hosts, in the city | of our God,* which God will establish for- | ever. Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. We have thought on your steadfast love, | O God,* in the midst of your | temple. COLLECT OF THE DAY Almighty and ever-living God, as Your only-begotten Son was this day presented in the temple in the substance of our flesh, grant that we may be presented to You with pure and clean hearts; through Jesus Christ, our Lord, who lives and reigns with You and the Holy Spirit, one God, now and forever. (F12)</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (609, 5110, 'F', NULL, 'St. Matthias, Apostle (February 24)', 'Red', NULL, 'Isa 66:1-2', 'Psalm 134', 'Acts 1:15-26', 'Matt 11:25-30', '<div>INTROIT Ps. 89:1, 5, 15–16; antiphon: Ps. 119:46 I will speak of your testimonies before kings, | [O Lord,]* and shall not be | put to shame. I will sing of the steadfast love of the LORD, for- | ever;* with my mouth I will make known your faithfulness to all gener- | ations. Let the heavens praise your wonders, | O LORD,* your faithfulness in the assembly of the | holy ones! Blessèd are the people who know the | festal shout,* who walk, O LORD, in the light | of your face, who exult in your name | all the day* and in your righteousness are ex- | alted. Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. I will speak of your testimonies before kings, | [O Lord,]* and shall not be | put to shame.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (610, 5120, 'F', NULL, 'St. Joseph, Guardian of Jesus (March 19)', 'White', NULL, '2 Sam 7:4-16', 'Psalm 127', 'Rom 4:13-18', 'Matt 2:13-15, 19-23', '<div>INTROIT Ps. 89:1, 5, 15–16; antiphon: Ps. 128:1 Blessèd is everyone who | fears the LORD,* who walks | in his ways! I will sing of the steadfast love of the LORD, for- | ever;* with my mouth I will make known your faithfulness to all gener- | ations. Let the heavens praise your wonders, | O LORD,* your faithfulness in the assembly of the | holy ones! Blessèd are the people who know the | festal shout,* who walk, O LORD, in the light | of your face, who exult in your name | all the day* and in your righteousness are ex- | alted. Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. Blessèd is everyone who | fears the LORD,* who walks | in his ways!</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (611, 5130, 'F', NULL, 'The Annunciation of Our Lord (March 25)', 'White', NULL, 'Isa 7:10-14', 'Psalm 45:7-17', 'Heb 10:4-10', 'Luke 1:26-38', '<div>INTROIT Ps. 34:1–3; antiphon: Is. 62:11b Say to the daughter of | Zion,* “Behold, your sal- | vation comes.” I will bless the LORD at | all times;* his praise shall continually be | in my mouth. My soul makes its boast | in the LORD;* let the humble hear | and be glad. Oh, magnify the | LORD with me,* and let us exalt his name to- | gether! Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. Say to the daughter of | Zion,* “Behold, your sal- | vation comes.” </div>', NULL, 'It is appropriate to observe this feast day in all its fullness during Lent. However, according to historical precedent, when the Annunciation falls during Holy Week or on Easter Day (or also on the Fifth Sunday in Lent in the One-year Series), it should not be observed at those times but may be transferred to a weekday following the Second Sunday of Easter.');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (612, 5140, 'F', NULL, 'St. Mark, Evangelist (April 25)', 'Red', NULL, 'Isa 52:8-10', 'Psalm 146', '2 Tim 4:5-18', 'Mark 16:14-20', '<div>INTROIT Ps. 92:1–5; antiphon: Mark 16:15 Go into | all the world* and proclaim the gospel to the whole cre- | ation. It is good to give thanks | to the LORD,* to sing praises to your name, | O Most High; to declare your steadfast love in the | morning,* and your faithful- | ness by night, to the music of the lute | and the harp,* to the melody | of the lyre. For you, O LORD, have made me glad | by your work;* at the works of your hands I | sing for joy. How great are your works, | O LORD!* Your thoughts are | very deep! Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. Go into | all the world* and proclaim the gospel to the whole cre- | ation.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (613, 5050, 'F', NULL, 'St. Philip and St. James, Apostles (May 1)', 'Red', NULL, 'Isa 30:18-21', 'Psalm 36:5-12', 'Eph 2:19-22', 'John 14:1-14', '<div>INTROIT Ps. 89:1, 5, 15–16; antiphon: Ps. 119:46 I will speak of your testimonies before kings, | [O Lord,]*</div>\r\n\r\n<div>and shall not be | put to shame. I will sing of the steadfast love of the LORD, for- | ever;* with my mouth I will make known your faithfulness to all gener- | ations. Let the heavens praise your wonders, | O LORD,* your faithfulness in the assembly of the | holy ones! Blessèd are the people who know the | festal shout,* who walk, O LORD, in the light | of your face, who exult in your name | all the day* and in your righteousness are ex- | alted. Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. I will speak of your testimonies before kings, | [O Lord,]* and shall not be | put to shame.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (614, 5060, 'F', NULL, 'The Visitaion (May 31, 3 Year; July 2, 1-Year)', 'White', NULL, 'Isa 11:1-5', 'Psalm 138', 'Rom 12:9-16', 'Luke 1:39-45(46-49)', '<div>My soul magni- | fies the Lord,* and my spirit rejoices in God my | Savior. My heart exults in the LORD; my strength is exalted | in the LORD.* My mouth derides my enemies, because I rejoice in your sal- | vation. There is none holy like the LORD; there is none be- | sides you;* there is no rock | like our God. The LORD makes poor and | makes rich;* he brings low and | he exalts. He raises up the poor from the dust; he lifts the needy from the | ash heap* to make them sit with princes and inherit a seat of | honor. For the pillars of the earth | are the LORD’s,* and on them he has | set the world. Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. My soul magni- | fies the Lord,* and my spirit rejoices in God my | Savior.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (615, 5065, 'F', NULL, 'St. Barnabas, Apostle (June 11)', 'Red', NULL, 'Isa 42:5-12', 'Psalm 112', 'Acts 11:19-30; 13:1-3', 'Mark 6:7-13', '<div>INTROIT Ps. 135:1–3; antiphon: Ps. 135:13 Your name, O LORD, endures for- | ever,* your renown, O LORD, throughout all | ages. Praise the LORD! Praise the name | of the LORD,* give praise, O servants | of the LORD, who stand in the house | of the LORD,*</div>\r\n\r\n<div>in the courts of the house | of our God. Praise the LORD, for the | LORD is good;* sing to his name, for it is | pleasant! Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. Your name, O LORD, endures for- | ever,* your renown, O LORD, throughout all | ages. </div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (616, 5080, 'F', NULL, 'The Nativity of St. John the Baptist (June 24)', 'White', NULL, 'Isa 40:1-5', 'Psalm 85:(1-6)7-13', 'Acts 13:13-26', 'Luke 1:57-80', '<div>INTROIT Luke 1:68, 76–79; antiphon: Mal. 3:1 Behold, I send my messenger and he will prepare the way be-| fore me.* And the Lord whom you seek will suddenly come to his | temple. Blessèd be the Lord God of | Israel,* for he has visited and redeemed his | people. And you, child, will be called the prophet of the | Most High;* for you will go before the Lord to pre- | pare his ways, to give knowledge of salvation to his | people* in the forgiveness | of their sins, because of the tender mercy | of our God,* whereby the sunrise shall visit us | from on high to give light to those who sit in darkness and in the shad- | ow of death,* to guide our feet into the | way of peace. Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. Behold, I send my messenger and he will prepare the way be- | fore me.* And the Lord whom you seek will suddenly come to his | temple.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (617, 5090, 'F', NULL, 'St. Peter and St. Paul, Apostles (June 29)', 'Red', NULL, 'Acts 15:1-12(13-21)', 'Psalm 46', 'Gal 2:1-10', 'Matt 16:13-19', '<div>INTROIT Ps. 89:1, 5, 15–16; antiphon: Ps. 119:46 I will speak of your testimonies before kings, | [O Lord,]* and shall not be | put to shame. I will sing of the steadfast love of the LORD, for- | ever;* with my mouth I will make known your faithfulness to all gener- | ations. Let the heavens praise your wonders, | O LORD,* your faithfulness in the assembly of the | holy ones! Blessèd are the people who know the | festal shout,* who walk, O LORD, in the light | of your face, who exult in your name | all the day* and in your righteousness are ex- | alted. Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. I will speak of your testimonies before kings, | [O Lord,]*and shall not be | put to shame.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (618, 5100, 'F', NULL, 'St. Mary Magdaline (July 22)', 'White', NULL, 'Prov 31:10-31', 'Psalm 73:23-28', 'Acts 13:26-31', 'John 20:1-2, 10-18', '<div>INTROIT Ps. 30:1a, 2–3, 12b; antiphon: Ps. 31:1a In you, O LORD, do I take | refuge;* let me never be | put to shame. I will extol you, | O LORD,* for you have drawn me up [out | of the depths]. O LORD my God, I cried to | you for help,*</div>\r\n\r\n<div>and you have | healed me. O LORD, you have brought up my soul | from Sheol;* you restored me to life from among those who go down | to the pit. O | LORD my God,* I will give thanks to you for- | ever! Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. In you, O LORD, do I take | refuge;* let me never be | put to shame.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (619, 5110, 'F', NULL, 'St. James the Elder, Apostle (July 25)', 'Red', NULL, 'Acts 11:27-12:5', 'Psalm 56', 'Rom 8:28-39', 'Mark 10:35-45', '<div>INTROIT Ps. 89:1, 5, 15–16; antiphon: Ps. 119:46 I will speak of your testimonies before kings, | [O Lord,]* and shall not be | put to shame. I will sing of the steadfast love of the LORD, for- | ever;* with my mouth I will make known your faithfulness to all gener- | ations. Let the heavens praise your wonders, | O LORD,* your faithfulness in the assembly of the | holy ones! Blessèd are the people who know the | festal shout,* who walk, O LORD, in the light | of your face, who exult in your name | all the day* and in your righteousness are ex- | alted. Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. I will speak of your testimonies before kings, | [O Lord,]* and shall not be | put to shame.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (620, 5120, 'F', NULL, 'St. Mary, Mother of Our Lord (August 15)', 'White', NULL, 'Isa 61:7-11', 'Psalm 45:10-17', 'Gal 4:4-7', 'Luke 1:(39-45)46-55', '<div>INTROIT Ps. 34:2–5; antiphon: Ps. 34:1 I will bless the LORD at | all times;* his praise shall continually be | in my mouth. My soul makes its boast | in the LORD;* let the humble hear | and be glad. Oh, magnify the | LORD with me,* and let us exalt his name to- | gether! I sought the LORD, and he | answered me* and delivered me from | all my fears. Those who look to him are | radiant,* and their faces shall never | be ashamed. Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. I will bless the LORD at | all times;* his praise shall continually be | in my mouth.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (621, 5120, 'F', NULL, 'St. Bartholomew, Apostle (August 24)', 'Red', NULL, 'Prov 3:1-8', 'Psalm 121', '2 Cor 4:7-10', 'Luke 22:24-30 or John 1:43-51', '<div>INTROIT Ps. 89:1, 5, 15–16; antiphon: Ps. 119:46 I will speak of your testimonies before kings, | [O Lord,]* and shall not be | put to shame. I will sing of the steadfast love of the LORD, for- | ever;* with my mouth I will make known your faithfulness to all gener- | ations. Let the heavens praise your wonders, | O LORD,* your faithfulness in the assembly of the | holy ones! Blessèd are the people who know the | festal shout,* who walk, O LORD, in the light | of your face, who exult in your name | all the day* and in your righteousness are ex- | alted. Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. I will speak of your testimonies before kings, | [O Lord,]* and shall not be | put to shame.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (622, 5130, 'F', NULL, 'The Martyrdom of St. John the Baptist (August 29)', 'Rose', NULL, 'Rev 6:9-11', 'Psalm 71:1-8', 'Rom 6:1-5', 'Mark 6:14-29', '<div>INTROIT Ps. 31:1, 3, 5; antiphon: Rev. 7:14b These are the ones coming out of the great tribu- | lation.* They have washed their robes and made them white in the blood | of the Lamb. In you, O LORD, do I take refuge; let me never be | put to shame;* in your righteousness de- | liver me. For you are my rock and my | fortress;* and for your name’s sake you lead me and | guide me. Into your hand I commit my | spirit;* you have redeemed me, O LORD, | faithful God. Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. These are the ones coming out of the great tribu- | lation.* They have washed their robes and made them white in the blood | of the Lamb.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (423, 2760, 'B', 'PENTECOST', 'Sunday on October 30-November 5 (Proper 26)', 'Green', NULL, 'Deut. 6:1-9', 'Psalm 119:1-8', 'Heb. 9:11-14(15-22)', 'Mark 12:28-37', NULL, NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (424, 2770, 'B', 'PENTECOST', 'Sunday on November 6-12 (Proper 27)', 'Green', NULL, '1 Kings 17:8-16', 'Psalm 146', 'Heb. 9:24-28', 'Mark 12:38-44', NULL, NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (425, 2780, 'B', 'PENTECOST', 'Sunday on November 13-19 (Proper 28)', 'Green', '<div><strong>The Crucified and Risen Body of Christ Jesus Is the True Temple of God</strong></div>\r\n\r\n<div>Despite its &quot;wonderful stones&quot; and &quot;great buildings,&quot; the Jerusalem temple would be torn down, with not one stone left upon another, just as this present world and its kingdoms will come to an end (Mark 13:1_8). But that temple pointed beyond itself to Christ, to His sacrifice upon the cross and to the resurrection of His body as the true Temple of God. In the midst of sin and death, by the proclamation of the Gospel, He now gathers disciples into His body, wherein &quot;the one who endures to the end will be saved&quot; (Mark 13:10_13). For He is &quot;a great priest over the house of God,&quot; who &quot;will remember their sins and their lawless deeds no more.&quot; By the pure water of His Baptism, they &quot;draw near with a true heart in full assurance of faith,&quot; and by His flesh and blood, they enter the Holy of Holies (Heb. 10:17_22). Thus are His people delivered, &quot;everyone whose name shall be found written in the book.&quot; For by the wisdom of His Gospel, He turns &quot;many to righteousness,&quot; so that &quot;many of those who sleep in the dust of the earth shall awake&quot; to everlasting life (Dan. 12:1_3).</div>', 'Dan. 12:1–3', 'Psalm 16', 'Heb. 10:11–25', 'Mark 13:1–13', '<div>Introit</div>\r\n\r\n<div>Psalm 48:11–14; antiphon: Mark 13:13b</div>\r\n\r\n<div>The one who endures | to the end *</div>\r\n\r\n<div><strong>\twill | be saved.</strong></div>\r\n\r\n<div>Let Mount Zion | be glad! *</div>\r\n\r\n<div><strong>\tLet the daughters of Judah rejoice because of your judgments!</strong></div>\r\n\r\n<div>Walk about Zion, go around her, number her | towers, *</div>\r\n\r\n<div><strong>\tconsider well her ramparts, go through her | citadels,</strong></div>\r\n\r\n<div>that you may tell the next generation that this is God, our God forever and | ever. *</div>\r\n\r\n<div><strong>\tHe will guide us for- ever.</strong></div>\r\n\r\n<div><strong>Glory be to the Father and to the Son</strong></div>\r\n\r\n<div><strong>and to the Holy Spirit;</strong></div>\r\n\r\n<div><strong>as it was in the beginning,</strong></div>\r\n\r\n<div><strong>is now, and will be forever. Amen.</strong></div>\r\n\r\n<div>The one who endures | to the end *</div>\r\n\r\n<div><strong>\twill </strong>| <strong>be saved.</strong></div>', '<div>Entrance: 968 My Lord, What a Morning (Lutheran Service Builder) </div>\r\n\r\n<div>Of the Day: 508 The Day Is Surely Drawing Near </div>\r\n\r\n<div>Offertory: 910 Now the Silence </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;514 The Bridegroom Soon Will Call Us </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;638 Eat This Bread </div>\r\n\r\n<div>Closing: &nbsp;516 Wake, Awake, for Night Is Flying </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (426, 2790, 'B', 'PENTECOST', 'Sunday on November 20-26 (Proper 29)', 'Green', '<div><strong>In Repentance We Are Alert to the Coming of Christ</strong></div>\r\n\r\n<div>The signs of the end are all around us, constant reminders that &quot;heaven and earth will pass away.&quot; But all of these signs are centered in the cross of Christ, whereby He has conquered sin and death, that we might be raised with Him in righteousness through His Word of the Gospel, which &quot;will not pass away&quot; (Mark 13:31). He is &quot;the firstborn of the dead,&quot; who in His great love &quot;has freed us from our sins by his blood&quot; (Rev. 1:5). His salvation is certain because &quot;his dominion is an everlasting dominion&quot; and His kingdom &quot;shall not be destroyed&quot; (Dan. 7:14). For this purpose He came into the world, to reign in love through His voice of the Gospel, which is the truth (John 18:37). So is the righteousness of Christ &quot;a light to the peoples,&quot; which &quot;will never be dismayed&quot; because it is the justice of His cross and resurrection (Is. 51:4_6). As He &quot;is able to keep you from stumbling and to present you blameless before the presence of his glory,&quot; so wait upon &quot;the mercy of our Lord Jesus Christ that leads to eternal life&quot; (Jude 20_24).</div>', 'Is. 51:4–6 or Dan. 7:9–10, 13–14', 'Psalm 93', 'Jude 20–25 or Rev. 1:4b–8', 'Mark 13:24–37 or John 18:33–37', '<div>Introit</div>\r\n\r\n<div>Psalm 39:4–5a, 7–8, 12a; antiphon: 2 Peter 3:13b NIV</div>\r\n\r\n<div>We are looking forward to a new heaven and a | new earth, *</div>\r\n\r\n<div>\tthe home of | righteousness.</div>\r\n\r\n<div>O Lord, make me know my end and what is the measure | of my days; *</div>\r\n\r\n<div>\tlet me know how fleeting | I am!</div>\r\n\r\n<div>Behold, you have made my days a few | handbreadths, *</div>\r\n\r\n<div>\tand my lifetime is as nothing be- | fore you.</div>\r\n\r\n<div>And now, O Lord, for what | do I wait? *</div>\r\n\r\n<div>\tMy hope | is in you.</div>\r\n\r\n<div>Deliver me from all my trans- | gressions. *</div>\r\n\r\n<div>\tDo not make me the scorn | of the fool!</div>\r\n\r\n<div>Hear my prayer, O Lord, and give ear | to my cry; *</div>\r\n\r\n<div>\thold not your peace | at my tears!</div>\r\n\r\n<div>Glory be to the Father and | to the Son</div>\r\n\r\n<div>\tand to the Holy | Spirit;</div>\r\n\r\n<div>as it was in the be- | ginning,</div>\r\n\r\n<div>\tis now, and will be forever. | Amen.</div>\r\n\r\n<div>We are looking forward to a new heaven and a | new earth, *</div>\r\n\r\n<div>\tthe home of | righteousness.</div>', '<div>Entrance: 815 All Praise to Thee, for Thou, O King Divine </div>\r\n\r\n<div>Of the Day: 336 Lo! He Comes with Clouds Descending </div>\r\n\r\n<div>Offertory: 693 O Holy Spirit, Grant Us Grace </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;621 Let All Mortal Flesh Keep Silence </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;680 Thine the Amen, Thine the Praise </div>\r\n\r\n<div>Closing: 525 Crown Him with Many Crowns </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (430, 3000, 'C', 'ADVENT', 'First S. in Advent', 'Blue or Violet', '<div><strong>The Lord Jesus Comes in Humility to Redeem Us</strong></div>\r\n\r\n<div>The season of Advent focuses on the coming of our Lord Jesus Christ, and this first Sunday establishes this theme for the rest of the season. The Son of God came long ago to be our Savior, &quot;a righteous Branch&quot; descended from David (Jer. 33:15). As He then came into Jerusalem, riding on a lowly donkey to sacrifice Himself for the sins of the world (Luke 19:28-40), so does He come to His Church today in the humility of Word and Sacrament to deliver the fruits of His Passion: the forgiveness of sins and eternal life. He absolves us and establishes our hearts &quot;blameless in holiness before our God and Father&quot; (1 Thess. 3:13). The same Lord Jesus, who came to Jerusalem then and who comes to us now in peace, will come again with power and great glory on the Last Day. Then there will be &quot;distress of nations in perplexity,&quot; with &quot;people fainting in fear.&quot; Yet, as we anticipate that great and terrible day, He bids us to rest securely in Him: &quot;Raise your heads, because your redemption is drawing near&quot; (Luke 21:25, 26, 28).</div>', 'Jer. 33:14–16', 'Psalm 25:1–10', '1 Thess. 3:9–13', 'Luke 19:28–40 or Luke 21:25–36', '<div><font color=black><strong>Introit Psalm 89:6, 14–16, 18; antiphon: Zechariah 9:9b, alt.</strong></font></div>\r\n\r\n<div><font color=black>Behold, your king is coming to you;</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;righteous and having salvation.</strong></font></div>\r\n\r\n<div><font color=black>Who in the skies can be compared to the Lord?</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;Who among the heavenly beings is like the Lord?</strong></font></div>\r\n\r\n<div><font color=black>Righteousness and justice are the foundation of your throne;</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;steadfast love and faithfulness go before you.</strong></font></div>\r\n\r\n<div><font color=black>Blessèd are the people who know the festal shout,</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;who walk, O Lord, in the light of your face,</strong></font></div>\r\n\r\n<div><font color=black>who exult in your name all the day</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;and in your righteousness are exalted.</strong></font></div>\r\n\r\n<div><font color=black>For our shield belongs to the Lord,</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;our king to the Holy One of Israel.</strong></font></div>\r\n\r\n<div><font color=black><strong>Glory be to the Father and to the Son</strong></font></div>\r\n\r\n<div><font color=black><strong>and to the Holy Spirit;</strong></font></div>\r\n\r\n<div><font color=black><strong>as it was in the beginning,</strong></font></div>\r\n\r\n<div><font color=black><strong>is now, and will be forever. Amen.</strong></font></div>\r\n\r\n<div><font color=black>Behold, your king is coming to you;</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;righteous and having salvation.</strong></font></div>', '<div>Entrance: 339 Lift Up Your Heads, You Everlasting Doors </div>\r\n\r\n<div>Of the Day: 332 Savior of the Nations, Come </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;331 The Advent of Our King </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;341 Lift Up Your Heads, Ye Mighty Gates </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;335 O Bride of Christ, Rejoice </div>\r\n\r\n<div>Closing: 334 O Lord, How Shall I Meet You </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (431, 3010, 'C', 'ADVENT', 'Second S. in Advent', 'Blue or Violet', '<div><strong>The Preaching of Repentance Prepares Us for the Coming of the Lord</strong></div>\r\n\r\n<div>The preaching and Baptism &quot;of repentance for the forgiveness of sins&quot; (Luke 3:3) prepare us for the coming of the Lord Jesus Christ. The historic work of John the Baptist was completed with the first advent of our Lord Jesus in the flesh, but the ministry of the forerunner continues in the preaching of Law and Gospel and in Holy Baptism. Through His messengers, the Lord calls people of all nations to &quot;see the salvation of God&quot; (Luke 3:6). Our haughtiness is removed and our mountains of pride are brought low, but the Lord humbles us in order to exalt us in His mercy. As the Lord has begun this good work of repentance in us, so also does He perfect it by His Word and Holy Spirit, and He &quot;will bring it to completion at the day of Jesus Christ&quot; (Phil. 1:6). He purifies us to be His priestly people, precious in His sight and abounding in faith and love, so that we offer our very lives in righteousness to the Lord (Mal. 3:3–4).</div>', 'Mal. 3:1–7b', 'Psalm 66:1–12', 'Phil. 1:2–11', 'Luke 3:1–14 (15–20)', '<div><font color=black>INTROIT Psalm 81:8, 10–11, 13; antiphon: Luke 3:4b</font></div>\r\n\r\n<div><font color=black>The voice of one crying in the | wilderness: *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;“Prepare the way of the Lord, make his | paths straight.”</strong></font></div>\r\n\r\n<div><font color=black>Hear, O my people, while I ad- | monish you! *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;O Israel, if you would but lis- | ten to me!</strong></font></div>\r\n\r\n<div><font color=black>I am the Lord your God, who brought you up out of the land of | Egypt. *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;Open your mouth wide, and I will | fill it.</strong></font></div>\r\n\r\n<div><font color=black>But my people did not listen | to my voice; *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;Israel would not sub- | mit to me.</strong></font></div>\r\n\r\n<div><font color=black>Oh, that my people would lis- | ten to me, *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;that Israel would walk | in my ways!</strong></font></div>\r\n\r\n<div><font color=black><strong>Glory be to the Father and | to the Son</strong></font></div>\r\n\r\n<div><font color=black><strong>and to the Holy | Spirit;</strong></font></div>\r\n\r\n<div><font color=black><strong>as it was in the be- | ginning,</strong></font></div>\r\n\r\n<div><font color=black><strong>is now, and will be forever. | Amen.</strong></font></div>\r\n\r\n<div><font color=black>The voice of one crying in the | wilderness: *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;“Prepare the way of the Lord, make his | paths straight.”</strong></font></div>', '<div>Entrance: 343 Prepare the Royal Highway </div>\r\n\r\n<div>Of the Day: 344 On Jordan’s Bank the Baptist’s Cry </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;350 Come, Thou Precious Ransom, Come </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;346 When All the World Was Cursed </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;337 The Night Will Soon Be Ending </div>\r\n\r\n<div>Closing: 333 Once He Came in Blessing </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (432, 3020, 'C', 'ADVENT', 'Third S. in Advent', 'Blue or Violet', '<div><strong>The Coming of Jesus Enables Us to Rejoice</strong></div>\r\n\r\n<div>The Third Sunday in Advent has traditionally been called by the Latin word Gaudete, meaning &quot;Rejoice!&quot; For as you are called to repentance, so also are you urged to rejoice in the coming of the Lord Jesus Christ. By His own cross, He has accomplished salvation for you; &quot;He has cleared away your enemies,&quot; &quot;taken away the judgments against you&quot; and come to reign in your midst. Indeed, He rejoices over you with gladness and song (Zeph. 3:15–17)! Therefore, even from prison St. Paul encourages us to &quot;rejoice in the Lord always,&quot; knowing that the peace of God will guard and keep us in Christ Jesus (Phil. 4:4, 7). We find an example and encouragement in the case of John the Baptist. As he languishes in prison, he calls upon Jesus and is strengthened by the Word of the Gospel that he receives. The same good news is preached to you, by which all things are made new and even &quot;the dead are raised up&quot; (Luke 7:22). Do not be offended by the cross, therefore, but let your life be one of prayer and thanksgiving (Luke 7:23; Phil. 4:6).</div>', 'Zeph. 3:14–20', 'Psalm 85', 'Phil. 4:4–7', 'Luke 7:18–28 (29–35)', '<div><font color=black><strong>Introit &nbsp;Psalm 146:5–8; antiphon: Philippians 4:4</strong></font></div>\r\n\r\n<div><font color=black>Blessèd is he whose help is the God of | Jacob,</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;whose hope is in the </strong>| <strong>Lord his God,</strong></font></div>\r\n\r\n<div><font color=black>who made heaven and earth, the sea, and all that | is in them,</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;who keeps faith for-</strong>| <strong>ever;</strong></font></div>\r\n\r\n<div><font color=black>who executes justice for | the oppressed,</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;who gives food to the </strong>| <strong>hungry.</strong></font></div>\r\n\r\n<div><font color=black>The Lord sets the prisoners free; the Lord opens the eyes | of the blind.</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;The Lord lifts up those who are bowed down; the Lord loves the </strong>| <strong>righteous.</strong></font></div>\r\n\r\n<div><font color=black><strong>Glory be to the Father and </strong>| <strong>to the Son</strong></font></div>\r\n\r\n<div><font color=black><strong>and to the Holy </strong>| <strong>Spirit;</strong></font></div>\r\n\r\n<div><font color=black><strong>as it was in the be-</strong>| <strong>ginning,</strong></font></div>\r\n\r\n<div><font color=black><strong>is now, and will be forever. </strong>| <strong>Amen.</strong></font></div>\r\n\r\n<div><font color=black>Rejoice in the Lord | always;</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;again I will say, </strong>| <strong>Rejoice.</strong></font></div>', '<div>Entrance: 338 Come, Thou Long-Expected Jesus </div>\r\n\r\n<div>Of the Day: 345 Hark! A Thrilling Voice Is Sounding </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;347 Comfort, Comfort Ye My People </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;355 O Savior, Rend the Heavens Wide </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;342 What Hope! An Eden Prophesied </div>\r\n\r\n<div>Closing: 349 Hark the Glad Sound </div>', '<div>Consider LSB357v1 for Gloria</div>');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (433, 3030, 'C', 'ADVENT', 'Fourth S. in Advent', 'Blue or Violet', '<div><strong>The Lord Comes to Visit Us in Peace</strong></div>\r\n\r\n<div>The Fourth Sunday in Advent turns our attention toward the Nativity of Our Lord. With Mary, we await the coming of the Christ, her Son, conceived in her womb by the Spirit of God. As the Lord dealt graciously with her and did great things for her (Luke 1:48–49), so also He manifests Himself and His glory to us in mercy and gentleness. He comes to rule His people in peace, to &quot;shepherd his flock in the strength of the Lord.&quot; He comes forth not from the great capital city of Rome or Jerusalem, but from lowly little Bethlehem (Micah 5:2, 4). He comes to sacrifice Himself, in fulfillment of His Father\'s will, for the salvation and sanctification of His people (Heb. 10:10). He who once visited Elizabeth while hidden in the womb of Mary (Luke 1:39–45) now comes to visit us today, hidden in the lowliness of simple water, bread and wine.</div>', 'Micah 5:2–5a', 'Psalm 80:1–7', 'Heb. 10:5–10', 'Luke 1:39–45 (46–56)', '<div><font color=black><strong>Introit 1 Samuel 2:1b, 2, 5b–7; antiphon: Luke 1:46b–47</strong></font></div>\r\n\r\n<div><font color=black>My soul magni- | fies the Lord, *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;and my spirit rejoices in God my | Savior.</strong></font></div>\r\n\r\n<div><font color=black>My mouth derides my | enemies, *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;because I rejoice in your sal- | vation.</strong></font></div>\r\n\r\n<div><font color=black>There is none holy | like the Lord; *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;there is none besides you; there is no rock | like our God.</strong></font></div>\r\n\r\n<div><font color=black>The barren has borne | seven, *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;but she who has many children | is forlorn.</strong></font></div>\r\n\r\n<div><font color=black>The Lord kills and | brings to life; *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;he brings down to Sheol and | raises up.</strong></font></div>\r\n\r\n<div><font color=black>The Lord makes poor and | makes rich; *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;he brings low and | he exalts.</strong></font></div>\r\n\r\n<div><font color=black><strong>Glory be to the Father and | to the Son</strong></font></div>\r\n\r\n<div><font color=black><strong>and to the Holy | Spirit;</strong></font></div>\r\n\r\n<div><font color=black><strong>as it was in the be- | ginning,</strong></font></div>\r\n\r\n<div><font color=black><strong>is now, and will be forever. | Amen.</strong></font></div>\r\n\r\n<div><font color=black>My soul magni- | fies the Lord, *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;and my spirit rejoices in God my | Savior.</strong></font></div>', '<div>Entrance: 354 Arise, O Christian People </div>\r\n\r\n<div>Of the Day: 357 O Come, O Come, Emmanuel </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;356 The Angel Gabriel from Heaven Came </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;353 Jesus Came, the Heavens Adoring </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;352 Let the Earth Now Praise the Lord </div>\r\n\r\n<div>Closing: 935 Tell Out, My Soul, the Greatness of the Lord</div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (434, 3040, 'C', 'CHRISTMAS', 'The Nativity of Our Lord (Christmas Eve)', 'White', '<div><strong>The Word of the Lord Is Fulfilled in the Flesh of Jesus</strong></div>\r\n\r\n<div>Though Ahaz would not ask, the Lord gives a sign to the house of David that &quot;the virgin shall conceive and bear a son, and shall call his name Immanuel&quot; (Is. 7:14). With this promise, He signifies that salvation is by His grace alone; it is no work or achievement of fallen humanity, but the Lord\'s own work and free gift. The promise is fulfilled as the Son of God is conceived and born of the Virgin Mary, and the sign is received in faith by the house of David in the person of Joseph (Matt. 1:20–24). &quot;Incarnate by the Holy Spirit of the Virgin Mary&quot; (Nicene Creed), God is with us (Immanuel) in the flesh of Jesus, Mary\'s Son. Joseph believes that Word of God and so demonstrates a marvelous example in his immediate and quiet obedience, taking Mary to be his wife and caring for her in faith and love. He loves her because the love of God is manifest in this, that &quot;the Father has sent his Son to be the Savior of the world,&quot; &quot;to be the propitiation for our sins&quot; (1 John 4:9–10, 14).</div>', 'Is. 7:10–14', 'Psalm 110:1–4', '1 John 4:7–16', 'Matt. 1:18–25', '<div><font color=black>Introit Psalm 24:1, 3–5; antiphon: Psalm 2:7</font></div>\r\n\r\n<div><font color=black>I will tell of | the decree: *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;The Lord said to me, “You are my Son; today I have be- | gotten you.”</strong></font></div>\r\n\r\n<div><font color=black>The earth is the Lord’s and the full- | ness thereof, *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;the world and those who dwell | therein.</strong></font></div>\r\n\r\n<div><font color=black>Who shall ascend the hill | of the Lord? *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;And who shall stand in his | holy place?</strong></font></div>\r\n\r\n<div><font color=black>He who has clean hands and a | pure heart, *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;who does not lift up his soul to what is false and does not swear de | ceitfully.</strong></font></div>\r\n\r\n<div><font color=black>He will receive blessing | from the Lord *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;and righteousness from the God of his sal | vation.</strong></font></div>\r\n\r\n<div><font color=black><strong>Glory be to the Father and | to the Son</strong></font></div>\r\n\r\n<div><font color=black><strong>and to the Holy | Spirit;</strong></font></div>\r\n\r\n<div><font color=black><strong>as it was in the be- | ginning,</strong></font></div>\r\n\r\n<div><font color=black><strong>is now, and will be forever. | Amen.</strong></font></div>\r\n\r\n<div><font color=black>I will tell of | the decree: *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;The Lord said to me, “You are my Son; today I have be- | gotten you.”</strong></font></div>\r\n\r\n<div>&nbsp;</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (435, 3050, 'C', 'CHRISTMAS', 'The Nativity of Our Lord (Christmas Midnight)', 'White', NULL, 'Is. 9:2–7', 'Psalm 96', 'Titus 2:11–14', 'Luke 2:1–14 (15–20)', NULL, NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (436, 3060, 'C', 'CHRISTMAS', 'The Nativity of Our Lord (Christmas Dawn)', 'White', NULL, 'Is. 62:10–12', 'Psalm 98', 'Titus 3:4–7', 'Luke 2:(1–14) 15–20', NULL, NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (437, 3070, 'C', 'CHRISTMAS', 'The Nativity of Our Lord (Christmas Day)', 'White', '<div><strong>The Living and Life-Giving Word of God Dwells among Us in the Flesh</strong></div>\r\n\r\n<div>The Lord sends out His ministers of the Gospel to make disciples &quot;of all the nations,&quot; so that &quot;all the ends of the earth shall see the salvation of our God.&quot; For the Lord has &quot;bared his holy arm&quot; in the incarnate Christ (Is. 52:7, 10). The Child in the manger, born of the Virgin Mary, is the very Word of God, the only begotten Son of the Father, &quot;whom he appointed the heir of all things, through whom also he created the world&quot; (Heb. 1:2). As &quot;all things were made through him&quot; (John 1:3), so are all things redeemed and made new in Him. In His body of flesh and blood, we behold &quot;the radiance of the glory of God&quot; (Heb. 1:3), &quot;glory as of the only Son from the Father, full of grace and truth&quot; (John 1:14). He dwells among us in peace that we might have life and light and salvation in Him. For by His Word of the Gospel, we are born again as the children of God, bearing His name and sharing His eternal life.</div>', 'Is. 52:7–10', 'Psalm 2', 'Heb. 1:1–6', 'John 1:1–14 (15–18)', '<div><font color=black><strong>Introit &nbsp;Psalm 98:1–4; antiphon: Isaiah 9:6</strong></font></div>\r\n\r\n<div><font color=black>For to us a child is born, to us a son is | given; *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;and the government shall be upon his | shoulder,</strong></font></div>\r\n\r\n<div><font color=black>and his name shall be called Wonderful | Counselor, *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;Mighty God, Everlasting Father, | Prince of Peace.</strong></font></div>\r\n\r\n<div><font color=black>Oh sing to the Lord a new song, for he has done | marvelous things! *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;His right hand and his holy arm have worked salva- | tion for him. </strong></font></div>\r\n\r\n<div><font color=black>The Lord has made known his sal- | vation; *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;he has revealed his righteousness in the sight of the | nations.</strong></font></div>\r\n\r\n<div><font color=black>He has remembered his steadfast love and faithfulness to the house of | Israel. *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;All the ends of the earth have seen the salvation | of our God.</strong></font></div>\r\n\r\n<div><font color=black>Make a joyful noise to the Lord, | all the earth; *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;break forth into joyous song and sing | praises!</strong></font></div>\r\n\r\n<div><font color=black><strong>Glory be to the Father and | to the Son *</strong></font></div>\r\n\r\n<div><font color=black><strong>and to the Holy | Spirit;</strong></font></div>\r\n\r\n<div><font color=black><strong>as it was in the be-| ginning, *</strong></font></div>\r\n\r\n<div><font color=black><strong>is now, and will be forever. | Amen.</strong></font></div>\r\n\r\n<div><font color=black>For to us a child is born, to us a son is | given; *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;and the government shall be upon his | shoulder,</strong></font></div>\r\n\r\n<div><font color=black>and his name shall be called Wonderful | Counselor, *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;Mighty God, Everlasting Father, | Prince of Peace.</strong></font></div>\r\n\r\n<div>&nbsp;</div>', '<div>Entrance: 387 Joy to the World </div>\r\n\r\n<div>Of the Day: 378* Break Forth, O Beauteous Heavenly Light </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;360 All My Heart Again Rejoices </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;380 Hark! The Herald Angels Sing </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;381 Let Our Gladness Have No End </div>\r\n\r\n<div>Closing: 367 Angels from the Realms of Glory </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (438, 3080, 'C', 'CHRISTMAS', 'First S. a. Christmas', 'White', '<div><strong>The Firstborn Son of God Is Our Redemption from Sin and Death</strong></div>\r\n\r\n<div>When the Lord destroyed the firstborn sons of Egypt, He spared the sons of Israel by providing a lamb in their stead. Hence, all the firstborn sons belong to Him. Every firstborn male animal was sacrificed, and every firstborn son of man was redeemed (Ex. 13:12–13). Therefore, the parents of Jesus &quot;brought him up to Jerusalem to present him to the Lord&quot; (Luke 2:22). However, He is not redeemed from priestly service but is consecrated for &quot;the redemption of Jerusalem&quot; and &quot;the consolation of Israel&quot; (Luke 2:25, 38). For God the Father did not spare His only begotten Son, but offered Him up as the true Passover Lamb, in order to redeem His people from bondage. His cross has caused many to stumble and fall, but His blood atoned for the sins of the world and delivers us from death. We now depart in the peace of Christ because we are also raised with Him. As we receive His body and blood, we join Simeon and Anna in &quot;giving thanks to God the Father through him,&quot; &quot;singing psalms and hymns and spiritual songs,&quot; including the Nunc Dimittis, with thankfulness in our hearts (Luke 2:28–32, 38; Col. 3:15–17).</div>', 'Ex. 13:1–3a, 11–15', 'Psalm 111', 'Col. 3:12–17', 'Luke 2:22–40', '<div><font color=black><strong>Introit &nbsp;Psalm 98:1–4; antiphon: Isaiah 52:10</strong></font></div>\r\n\r\n<div><font color=black>The Lord has bared his holy arm before the eyes of all the | nations, *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;and all the ends of the earth shall see the salvation | of our God.</strong></font></div>\r\n\r\n<div><font color=black>Oh sing to the Lord a new song, for he has done | marvelous things! *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;His right hand and his holy arm have worked salva- | tion for him. *</strong></font></div>\r\n\r\n<div><font color=black>The Lord has made known his sal- | vation; *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;he has revealed his righteousness in the sight of the | nations.</strong></font></div>\r\n\r\n<div><font color=black>He has remembered his steadfast love and faithfulness to the house of | Israel. *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;All the ends of the earth have seen the salvation | of our God.</strong></font></div>\r\n\r\n<div><font color=black>Make a joyful noise to the Lord, | all the earth; &amp;</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;break forth into joyous song and sing | praises!</strong></font></div>\r\n\r\n<div><font color=black><strong>Glory be to the Father and </strong>| <strong>to the Son *</strong></font></div>\r\n\r\n<div><font color=black><strong>and to the Holy </strong>| <strong>Spirit;</strong></font></div>\r\n\r\n<div><font color=black><strong>as it was in the be- </strong>| <strong>ginning, *</strong></font></div>\r\n\r\n<div><font color=black><strong>is now, and will be forever. Amen.</strong></font></div>\r\n\r\n<div><font color=black>The Lord has bared his holy arm before the eyes of all the | nations, *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;and all the ends of the earth shall see the salvation | of our God.</strong></font></div>\r\n\r\n<div>&nbsp;</div>', '<div>Entrance: 384 Of the Father’s Love Begotten </div>\r\n\r\n<div>Of the Day: 389 Let All Together Praise Our God Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;519 In His Temple Now Behold Him </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;937 Lord, Bid Your Servant Go in Peace </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;624 The Infant Priest Was Holy Born </div>\r\n\r\n<div>Closing: 381 Let Our Gladness Have No End </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (439, 3090, 'C', 'CHRISTMAS', 'Second S. a. Christmas', 'White', '<div><strong>The Lord Jesus Is Found in the Temple of His Church</strong></div>\r\n\r\n<div>The Lord Jesus &quot;grew and became strong&quot; (Luke 2:40); He &quot;increased in wisdom and in stature and in favor with God and man&quot; (Luke 2:52). As His body grew and developed, His mind also increased in knowledge and understanding. For as our brother in the flesh, that we might &quot;have redemption through his blood&quot; (Eph. 1:7), He lived by faith in the Word of His Father. Thus, He was catechized by His parents, who took Him up &quot;to Jerusalem every year at the Feast of the Passover&quot; (Luke 2:41); and when He was of age, He gave attention to the Holy Scriptures in His Father\'s house (Luke 2:46, 49). Christ Jesus is still found in His Church, in &quot;the word of truth, the gospel,&quot; by which we are adopted by His Father and sealed with His Spirit (Eph. 1:5, 13). Thus do we gain &quot;an understanding mind&quot; to go about our vocations, discerning &quot;between good and evil&quot; (1 Kings 3:9). And so do we also go up to Jerusalem, to stand &quot;before the ark of the covenant of the Lord&quot; (1 Kings 3:15), that is, in the Holy Communion of His body and blood.</div>', '1 Kings 3:4-15', 'Psalm 119:97-104', 'Eph. 1:3–14', 'Luke 2:40-52', '<div><font color=black><strong>Introit &nbsp;Psalm 147:1, 5, 11–12; antiphon: John 1:14</strong></font></div>\r\n\r\n<div><font color=black>The Word became flesh and dwelt among us, and we have seen his | glory, *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;glory as of the only Son from the Father, full of | grace and truth.</strong></font></div>\r\n\r\n<div><font color=black>Praise the Lord! For it is good to sing praises | to our God; *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;for it is pleasant, and a song of praise is </strong>| <strong>fitting.</strong></font></div>\r\n\r\n<div><font color=black>Great is our Lord, and abun- | dant in power; *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;his understanding is beyond | measure.</strong></font></div>\r\n\r\n<div><font color=black>But the Lord takes pleasure in those who | fear him, *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;in those who hope in his | steadfast love.</strong></font></div>\r\n\r\n<div><font color=black>Praise the Lord, O Jer- | usalem! *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;Praise your God, O | Zion!</strong></font></div>\r\n\r\n<div><font color=black><strong>Glory be to the Father and </strong>| <strong>to the Son *</strong></font></div>\r\n\r\n<div><font color=black><strong>and to the Holy </strong>| <strong>Spirit;</strong></font></div>\r\n\r\n<div><font color=black><strong>as it was in the be- </strong>| <strong>ginning, *</strong></font></div>\r\n\r\n<div><font color=black><strong>is now, and will be forever. </strong>| <strong>Amen.</strong></font></div>\r\n\r\n<div><font color=black>The Word became flesh and dwelt among us, and we have seen his | glory, *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;glory as of the only Son from the Father, full of | grace and truth.</strong></font></div>\r\n\r\n<div>&nbsp;</div>', '<div><font color=black>Entrance: &nbsp;402 The Only Son from Heaven </font></div>\r\n\r\n<div><font color=black>Of the Day: &nbsp;410 Within the Father’s House </font></div>\r\n\r\n<div><font color=black>Distribution: &nbsp;</font></div>\r\n\r\n<div><font color=black>&nbsp;&nbsp;&nbsp;&nbsp;376 Once in Royal David’s City </font></div>\r\n\r\n<div><font color=black>&nbsp;&nbsp;&nbsp;&nbsp;393 Infant Holy, Infant Lowly </font></div>\r\n\r\n<div><font color=black>&nbsp;&nbsp;&nbsp;&nbsp;389 Let All Together Praise Our God </font></div>\r\n\r\n<div><font color=black>Closing: 383 &nbsp;A Great and Mighty Wonder</font></div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (440, 3100, 'C', 'EPIPHANY', 'The Epiphany of Our Lord', 'Green', NULL, 'Is. 60:1–6', 'Psalm 72:', 'Eph. 3:1–12', 'Matt. 2:1–12', NULL, NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (444, 3140, 'C', 'EPIPHANY', 'Second S. a. the Epiphany', 'Green', '<div><strong>The Divine Glory Is Manifested in the Signs of Christ</strong></div>\r\n\r\n<div>When Jesus turned water into wine at the wedding in Cana, it was &quot;the first of his signs,&quot; by which He &quot;manifested his glory&quot; (John 2:11). It pointed to His coming &quot;hour,&quot; when He was lifted up on the cross for the forgiveness of sins and the life of the world (John 2:4; 12:23–32). The glory of the cross is incomprehensible apart from the Word and Spirit of God, but disciples of Jesus recognize that glory in the signs of His Gospel, and so they believe in Him. Jesus does not wait for His disciples to discover Him on their own, but He seeks out the forsaken and the desolate and unites them to Himself. He adorns them with His own beautiful righteousness and delights in them &quot;as the bridegroom rejoices over the bride&quot; (Is. 62:4–5). Purified by the washing of water with His Word in Holy Baptism, His disciples confess that &quot;Jesus is Lord,&quot; and they return thanks to Him &quot;in the Holy Spirit&quot; (1 Cor. 12:3) as they drink the good wine that He pours out for them, which is the new testament in His blood.</div>', 'Is. 62:1–5', 'Psalm 128', '1 Cor. 12:1–11', 'John 2:1–11', '<div><font color=black><strong>Introit &nbsp;Psalm 36:5–9; antiphon: Song of Solomon 2:4</strong></font></div>\r\n\r\n<div><font color=black>[The Lord] brought me to the banq- | ueting house, <strong>*</strong></font></div>\r\n\r\n<div><font color=black><strong>&nbsp;and his banner over | me was love.</strong></font></div>\r\n\r\n<div><font color=black>Your steadfast love, O Lord, extends to the | heavens, *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;your faithfulness | to the clouds.</strong></font></div>\r\n\r\n<div><font color=black>Your righteousness is like the moun- | tains of God; *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;your judgments are like the great deep; man and beast you save, </strong>| <strong>O Lord.</strong></font></div>\r\n\r\n<div><font color=black>How precious is your steadfast love, | O God! *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;The children of mankind take refuge in the shadow </strong>| <strong>of your wings.</strong></font></div>\r\n\r\n<div><font color=black>They feast on the abundance | of your house, *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;and you give them drink from the river of | your delights.</strong></font></div>\r\n\r\n<div><font color=black>For with you is the foun- | tain of life; *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;in your light do </strong>| <strong>we see light.</strong></font></div>\r\n\r\n<div><font color=black><strong>Glory be to the Father and </strong>| <strong>to the Son *</strong></font></div>\r\n\r\n<div><font color=black><strong>and to the </strong>| <strong>Holy Spirit;</strong></font></div>\r\n\r\n<div><font color=black><strong>as it was in the be- </strong>| <strong>ginning, *</strong></font></div>\r\n\r\n<div><font color=black><strong>is now, and will be forever. </strong>| <strong>Amen.</strong></font></div>\r\n\r\n<div><font color=black>[The Lord] brought me to the ban- queting house, *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;and his banner over </strong>| <strong>me was love.</strong></font></div>', '<div><font face=\"Times New Roman\" size=2 color=black>Entrance: 402 The Only Son from Heaven </font></div>\r\n\r\n<div><font face=\"Times New Roman\" size=2 color=black>Of the Day: 408* Come, Join in Cana’s Feast </font></div>\r\n\r\n<div><font face=\"Times New Roman\" size=2 color=black>Distribution: </font></div>\r\n\r\n<div><font face=\"Times New Roman\" size=2 color=black>&nbsp;&nbsp;&nbsp;&nbsp;910 Now the Silence </font></div>\r\n\r\n<div><font face=\"Times New Roman\" size=2 color=black>&nbsp;&nbsp;&nbsp;&nbsp;399 The Star Proclaims the King Is Here </font></div>\r\n\r\n<div><font face=\"Times New Roman\" size=2 color=black>&nbsp;&nbsp;&nbsp;&nbsp;631 Here, O My Lord, I See Thee Face to Face </font></div>\r\n\r\n<div><font face=\"Times New Roman\" size=2 color=black>Closing: 398 Hail to the Lord’s Anointed </font></div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (445, 3150, 'C', 'EPIPHANY', 'Third S. a. the Epiphany', 'Green', '<div><strong>The Lord Is Manifested as Our Savior through the Preaching of the Gospel</strong></div>\r\n\r\n<div>When Jesus opens His mouth to preach, gracious words flow from His lips. The Scriptures are, indeed, fulfilled in your hearing (Luke 4:21–22). For Christ was anointed by the Spirit of the Lord &quot;to proclaim good news to the poor,&quot; &quot;to proclaim liberty to the captives&quot; and &quot;to proclaim the year of the Lord\'s favor&quot; (Luke 4:18–19). By this proclamation, Christ releases His people from captivity and gathers them to Himself in His Church. So it was when the Lord released His people from Babylon and returned them to Jerusalem. &quot;Ezra the priest and scribe, and the Levites who taught the people,&quot; sanctified the whole congregation by the reading and preaching of the Law (Neh. 8:8–9). As the people then were urged to &quot;eat the fat and drink sweet wine and send portions to anyone who has nothing ready&quot; (Neh. 8:10), so are you anointed by the Spirit of the Lord Jesus Christ to share in His feast and to serve the fellow members of His Body with His good gifts, &quot;giving greater honor to the part that lacked it&quot; (1 Cor. 12:12, 24).</div>', 'Neh. 8:1–3,', 'Psalm 19:(1–6)', '1 Cor. 12:12–31a', 'Luke 4:16–30', '<div><strong>Introit Psalm 102:18–22; antiphon: v. 13</strong></div>\r\n\r\n<div>You will arise and have pity on | Zion; *</div>\r\n\r\n<div><strong>\tit is the time to favor her; the appointed | time has come.</strong></div>\r\n\r\n<div>Let this be recorded for a genera- | tion to come, *</div>\r\n\r\n<div><strong>\tso that a people yet to be created may | praise the Lord:</strong></div>\r\n\r\n<div>that he looked down from his | holy height; *</div>\r\n\r\n<div><strong>\tfrom heaven the Lord looked | at the earth,</strong></div>\r\n\r\n<div>to hear the groans of the | prisoners, *</div>\r\n\r\n<div><strong>\tto set free those who were | doomed to die,</strong></div>\r\n\r\n<div>that they may declare in Zion the name | of the Lord, *</div>\r\n\r\n<div><strong>\tand in Jerusa- | lem his praise, </strong></div>\r\n\r\n<div>when peoples gather to- | gether, *</div>\r\n\r\n<div>\t<strong>and kingdoms, to wor-| &nbsp;ship the Lord.</strong></div>\r\n\r\n<div><strong>Glory be to the Father and | to the Son *</strong></div>\r\n\r\n<div><strong>and to the Holy | Spirit;</strong></div>\r\n\r\n<div><strong>as it was in the be- | ginning, *</strong></div>\r\n\r\n<div><strong>is now, and will be forever. | Amen.</strong></div>\r\n\r\n<div>You will arise and have pity on | Zion; *</div>\r\n\r\n<div><strong>\tit is the time to favor her; the appointed | time has come.</strong></div>', '<div>Entrance: 908 Lord, Open Now My Heart to Hear </div>\r\n\r\n<div>Of the Day: &nbsp;839 O Christ, Our True and Only Light </div>\r\n\r\n<div>Distribution:</div>\r\n\r\n<div>594 God’s Own Child, I Gladly Say It </div>\r\n\r\n<div>605 Father Welcomes </div>\r\n\r\n<div>602 The Gifts Christ Freely Gives </div>\r\n\r\n<div>Closing: 810 O God of God, O Light of Light </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (446, 3160, 'C', 'EPIPHANY', 'Fourth S. a. the Epiphany', 'Green', '<div><strong>Jesus Has Authority to Forgive Your Sins and Give You Life</strong></div>\r\n\r\n<div>Jesus was sent to &quot;preach the good news of the kingdom of God&quot; (Luke 4:43). His preaching is an epiphany, or manifestation, of God because His Word reveals the authority of His cross and resurrection, by which He has atoned for the sins of the world. By the preaching of His Gospel in every place, He silences the unclean spirits and casts out demons, heals the diseases of body and soul, and restores life and health to His creation (Luke 4:40–41). For the sake of His divine love, He is &quot;patient and kind&quot; toward us; He &quot;bears all things,&quot; &quot;endures all things&quot; and delivers up His body to save us (1 Cor. 13:3–4, 7). So also for the sake of His love, He calls and sends His prophets, as ministers of His Word, &quot;to pluck up and to break down, to destroy and to overthrow, to build and to plant&quot; (Jer. 1:10).</div>', 'Jer. 1:4–10', 'Psalm 71:1–6 (7–11)', '1 Cor. 12:31b—13:13', 'Luke 4:31–44', '<div><font color=black><strong>Introit Psalm 10:16–18; antiphon: v. 12</strong></font></div>\r\n\r\n<div><font color=black>Arise, O Lord; O God, lift <strong>| </strong>up your hand; *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;forget not the af- | flicted.</strong></font></div>\r\n\r\n<div><font color=black>The Lord is king forever and <strong>| </strong>ever; *</font></div>\r\n\r\n<div><font color=black>&nbsp;<strong>the nations perish | from his land.</strong></font></div>\r\n\r\n<div><font color=black>O Lord, you hear the desire of the af- <strong>| </strong>flicted; *</font></div>\r\n\r\n<div><font color=black>&nbsp;<strong>you will strength- | en their heart;</strong> </font></div>\r\n\r\n<div><font color=black>you will incline your ear to do justice to the fatherless and | the oppressed,</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;so that man who is of the earth may strike ter- | ror no more. *</strong></font></div>\r\n\r\n<div><font color=black><strong>Glory be to the Father and | to the Son *</strong></font></div>\r\n\r\n<div><font color=black><strong>&nbsp;and to the Holy | Spirit;</strong></font></div>\r\n\r\n<div><font color=black><strong>as it was in the be- | ginning, *</strong></font></div>\r\n\r\n<div><font color=black><strong>&nbsp;is now, and will be forever. | Amen.</strong></font></div>\r\n\r\n<div><font color=black>Arise, O Lord; O God, lift up your hand;</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;forget not the af-| flicted.</strong></font></div>', '<div><font face=\"Times New Roman\" size=2 color=black>Entrance: 578 Thy Strong Word </font></div>\r\n\r\n<div><font face=\"Times New Roman\" size=2 color=black>Of the Day: 842 Son of God, Eternal Savior </font></div>\r\n\r\n<div><font face=\"Times New Roman\" size=2 color=black>Distribution: </font></div>\r\n\r\n<div><font face=\"Times New Roman\" size=2 color=black>&nbsp;&nbsp;&nbsp;849 Praise the One Who Breaks the Darkness </font></div>\r\n\r\n<div><font face=\"Times New Roman\" size=2 color=black>&nbsp;&nbsp;&nbsp;535 How Wide the Love of Christ </font></div>\r\n\r\n<div><font face=\"Times New Roman\" size=2 color=black>&nbsp;&nbsp;&nbsp;401 From God the Father, Virgin-Born </font></div>\r\n\r\n<div><font face=\"Times New Roman\" size=2 color=black>Closing: 836 O God of Light </font></div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (447, 3170, 'C', 'EPIPHANY', 'Fifth S. a. the Epiphany', 'Green', '<div><strong>Jesus Comforts His People and Builds Up His Church by the Ministry of His Gospel</strong></div>\r\n\r\n<div>When Isaiah &quot;saw the Lord sitting upon a throne, high and lifted up,&quot; he was overcome with an awareness of his sin and &quot;unclean lips&quot; (Isaiah 6:1, 5). But the Lord atoned for his sin, took away his guilt, and sanctified his lips with &quot;a burning coal&quot; from the altar (Isaiah 6:6–7). Not only was he rescued from death, but he was called and sent as a prophet of the Lord\'s Word (Isaiah 6:8–9). Similarly, when Simon Peter and his companions &quot;enclosed a large number of fish&quot; at the Word of Jesus, he humbled himself and said, &quot;Depart from me, for I am a sinful man&quot; (St. Luke 5:4–8). But Jesus comforted Simon, called him to discipleship, and declared that he would be &quot;catching men&quot; (St. Luke 5:10–11). So, in the office of the ministry, the Church remains the little boat from which Jesus teaches His people (St. Luke 5:3). Thus are we instructed in the faith, so that we say &quot;Amen&quot; and return thanks with heart, mind, tongue, and life. For the preaching of Christ Jesus is a manifestation of the Holy Spirit, by which He builds up His Church on earth (1 Cor. 14:12–19).</div>', 'Is. 6:1–8 (9–13)', 'Psalm 138', '1 Cor. 14:12b–20', 'Luke 5:1–11', '<div><font color=black><strong>Introit Psalm 71:15–18; antiphon: v. 12</strong></font></div>\r\n\r\n<div><font color=black>O God, be not | far from me; *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;O my God, make haste to | help me!</strong></font></div>\r\n\r\n<div><font color=black>My mouth will tell of your righteous acts, of your deeds of salvation | all the day,</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;for their number is past my </strong>| <strong>knowledge.</strong></font></div>\r\n\r\n<div><font color=black>With the mighty deeds of the Lord God | I will come; *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;I will remind them of your righteousness, | yours alone.</strong></font></div>\r\n\r\n<div><font color=black>O God, from my youth you have | taught me, *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;and I still proclaim your | wondrous deeds.</strong></font></div>\r\n\r\n<div><font color=black>So even to old age and gray hairs, O God, do not for- | sake me, *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;until I proclaim your might to another generation, your power to all </strong>| <strong>those to come.</strong></font></div>\r\n\r\n<div><font color=black><strong>Glory be to the Father and | to the Son</strong></font></div>\r\n\r\n<div><font color=black><strong>and to the Holy | Spirit;</strong></font></div>\r\n\r\n<div><font color=black><strong>as it was in the be- | ginning,</strong></font></div>\r\n\r\n<div><font color=black><strong>is now, and will be forever. | Amen.</strong></font></div>\r\n\r\n<div><font color=black>O God, be not | far from me; *</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;O my God, make haste to | help me!</strong></font></div>', '<div>Entrance: &nbsp;409 Hail, O Source of Every Blessing </div>\r\n\r\n<div>Of the Day: &nbsp;533* Jesus Has Come and Brings Pleasure </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;960 Isaiah, Mighty Seer in Days of Old </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;507 Holy, Holy, Holy </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;621 Let All Mortal Flesh Keep Silence &nbsp;</div>\r\n\r\n<div>Closing: 411 I Want to Walk as a Child of the Light </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (448, 3180, 'C', 'EPIPHANY', 'Sixth S. a. the Epiphany', 'Green', '<div><strong>Christians Live by Faith in Christ and Rejoice in the Promise of His Resurrection</strong></div>\r\n\r\n<div>&quot;Cursed is the man who trusts in man,&quot; for all the strength of his flesh is like the grass that fades away (Jer. 17:5). The one who turns away from the Lord may have food and money and laugh for now, but he &quot;shall moan and weep&quot; in the judgment (St. Luke 6:24–25). But &quot;the man who trusts in the Lord&quot; is blessed with all that he needs, &quot;like a tree planted by water.&quot; When heat comes, he survives (Jer. 17:7–8). For the Lord has come in the flesh to heal the people of all their diseases, to cleanse their spirits with forgiveness, and to preach the Gospel of the Kingdom of God to the poor (St. Luke 6:18–20). As all of this is by way of His Cross, it is solely by faith in the promise of His Resurrection that Christians &quot;rejoice&quot; and &quot;leap for joy&quot; (St. Luke 6:21–23). &quot;If Christ has not been raised,&quot; our faith is in vain and we are most to be pitied (1 Cor. 15:14–19). But, in fact, just as &quot;Christ died for our sins,&quot; so has He also &quot;been raised from the dead&quot; (1 Cor. 15:3, 20).</div>', 'Jer. 17:5–8', 'Psalm 1', '1 Cor. 15:(1–11) 12–20', 'Luke 6:17–26', '<div>INTROIT Ps. 119:1–2, 4–5; antiphon: Ps. 119:7 </div>\r\n\r\n<div>I will praise you with an | upright heart,* </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>when I learn your just and righ- | teous decrees. </strong></div>\r\n\r\n<div>Blessèd are those whose way is | blameless,* </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>who walk in the law | of the LORD! </strong></div>\r\n\r\n<div>Blessèd are those who keep his testi- | monies,* </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>who seek him with their | whole heart.</strong> </div>\r\n\r\n<div>You have commanded your | precepts* </div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;to be kept dil- | igently. </strong></div>\r\n\r\n<div>Oh that my ways may be | steadfast* </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>in keeping your | statutes! </strong></div>\r\n\r\n<div><strong>Glory be to the Father and | to the Son* </strong></div>\r\n\r\n<div><strong>and to the Holy | Spirit; </strong></div>\r\n\r\n<div><strong>as it was in the be- | ginning,* </strong></div>\r\n\r\n<div><strong>is now, and will be forever. | Amen.</strong> </div>\r\n\r\n<div>I will praise you with an | upright heart,* </div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;when I learn your just and righ- | teous decrees.</strong></div>', '<div>Entrance: &nbsp;</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;704 Renew Me, O Eternal Light</div>\r\n\r\n<div>Of the Day: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;932* Jesus Sat with His Disciples </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;705 The Man Is Ever Blessed </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;737 Rejoice, My Heart, Be Glad and Sing </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;692 Praise to You and Adoration </div>\r\n\r\n<div>Closing: 394 Songs of Thankfulness and Praise</div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (449, 3190, 'C', 'EPIPHANY', 'Seventh S. a. the Epiphany', 'Green', '<div><strong>As the Son of God Is Merciful and Forgives Your Sins, You Also Be Merciful and Forgive</strong></div>\r\n\r\n<div>Your inheritance as a child of Adam is sin and death, but in Christ you are made alive through His Resurrection from the dead (1 Cor. 15:21–22). As you have died with Him in Holy Baptism, so are you raised with Him to newness of life. Therefore, &quot;do not go on sinning&quot; (1 Cor. 15:34). Instead of serving your desires and harming your neighbors, live &quot;as sons of the Most High,&quot; and &quot;be merciful, even as your Father is merciful&quot; (St. Luke 6:35–36). Deal with others as you would have others deal with you (St. Luke 6:31, 37–38). As Christ loved you when you were at enmity with Him, as He blessed and prayed for those who abused Him, and as He did good to those who hated Him and hurt Him, so also, &quot;love your enemies, and do good&quot; (St. Luke 6:27–29, 35). For God sent His Son to bear the cross and suffer death, not to condemn the guilty, but &quot;to preserve life.&quot; So does He provide a place for you within His Church, where He is near and deals kindly with &quot;you and your children and your children\'s children&quot; (Gen. 45: 5–10).</div>', 'Gen. 45:3–15', 'Psalm 103:1–13', '1 Cor. 15:21–26, 30-42', 'Luke 6:27–38', '<div><font color=black>INTROIT Ps. 37:1–5; antiphon: Ps. 37:7a, b</font></div>\r\n\r\n<div><font color=black>Be still before the LORD and wait patiently | for him;*</font></div>\r\n\r\n<div><font color=black><strong>fret not yourself over the one who prospers | in his</strong></font></div>\r\n\r\n<div><font color=black><strong>way.</strong></font></div>\r\n\r\n<div><font color=black>Fret not yourself because of evil- | doers;*</font></div>\r\n\r\n<div><font color=black><strong>be not envious of wrong- | doers!</strong></font></div>\r\n\r\n<div><font color=black>For they will soon fade | like the grass*</font></div>\r\n\r\n<div><font color=black><strong>and wither like the | green herb.</strong></font></div>\r\n\r\n<div><font color=black>Trust in the LORD, | and do good;*</font></div>\r\n\r\n<div><font color=black><strong>dwell in the land and befriend | faithfulness.</strong></font></div>\r\n\r\n<div><font color=black>Delight yourself | in the LORD,*</font></div>\r\n\r\n<div><font color=black><strong>and he will give you the desires | of your heart.</strong></font></div>\r\n\r\n<div><font color=black>Commit your way | to the LORD;*</font></div>\r\n\r\n<div><font color=black><strong>trust in him, and | he will act.</strong></font></div>\r\n\r\n<div><font color=black><strong>Glory be to the Father and | to the Son*</strong></font></div>\r\n\r\n<div><font color=black><strong>and to the Holy | Spirit;</strong></font></div>\r\n\r\n<div><font color=black><strong>as it was in the be- | ginning,*</strong></font></div>\r\n\r\n<div><font color=black><strong>is now, and will be forever. | Amen.</strong></font></div>\r\n\r\n<div><font color=black>Be still before the LORD and wait patiently | for him;*</font></div>\r\n\r\n<div><font color=black><strong>fret not yourself over the one who prospers | in his</strong></font></div>\r\n\r\n<div><font color=black><strong>way.</strong></font></div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (450, 3200, 'C', 'EPIPHANY', 'Eight S. a the Epiphany', 'Green', NULL, 'Jer. 7:1-7(8-15)', 'Psalm 92', '1 Cor 15:42-52(53-58)', 'Luke 6:39-49', NULL, NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (451, 3210, 'C', 'EPIPHANY', 'The Transfiguration of Our Lord', 'White', '<div><strong>The Glory of God Is Manifested in the Body of Christ</strong></div>\r\n\r\n<div>&quot;Moses was faithful in all God\'s house as a servant,&quot; but Christ Jesus &quot;has been counted worthy of more glory than Moses&quot; (Heb. 3:3, 5). A beloved and well-pleasing Son, faithful even to the point of death, Jesus\' own body was raised up on the third day as the house of God, and He has brought us into that house through the waters of Holy Baptism (Heb. 3:6). Thus, it was not Moses the lawgiver, but his successor, Joshua (the Hebrew name for Jesus), who led the people into the Promised Land (Deut. 34:1–4, 9). Now, on the Mount of Transfiguration, the New Testament Joshua appears in the glory that He is about to manifest by His &quot;departure&quot; (exodus) in Jerusalem (Luke 9:31). Having entered the waters of the Jordan in His Baptism, He passed through those waters and entered into glory by His cross and Passion. What He thereby accomplished in His own flesh and blood, crucified and risen, He reveals and gives to His Body, the Church, by the means of His Word. Therefore, the Father declares from heaven, &quot;Listen to him!&quot; (Luke 9:35).</div>', 'Deut. 34:1–12', 'Psalm 99', 'Heb. 3:1–6', 'Luke 9:28–36', '<div><font color=black><strong>INTROIT Ps. 84:1</strong></font><font\r\nface=Arial color=black><strong>–</strong></font><font color=black><strong>2, 9, 11; antiphon: Ps. 84:4</strong></font></div>\r\n\r\n<div><font color=black>Blessèd are those who dwell | in your house,*</font></div>\r\n\r\n<div><font color=black><strong>ever sing- | ing your praise!</strong></font></div>\r\n\r\n<div><font color=black>How lovely is your | dwelling place,*</font></div>\r\n\r\n<div><font color=black><strong>O | LORD of hosts!</strong></font></div>\r\n\r\n<div><font color=black>My soul longs, yes, faints for the courts | of the LORD;*</font></div>\r\n\r\n<div><font color=black><strong>my heart and flesh sing for joy to the | living God.</strong></font></div>\r\n\r\n<div><font color=black>Behold our shield, | O God;*</font></div>\r\n\r\n<div><font color=black><strong>look on the face of your a- | nointed!</strong></font></div>\r\n\r\n<div><font color=black>For the LORD God is a sun and shield; the LORD bestows</font></div>\r\n\r\n<div><font color=black>favor and | honor.*</font></div>\r\n\r\n<div><font color=black><strong>No good thing does he withhold from those who walk</strong></font></div>\r\n\r\n<div><font color=black><strong>up- | rightly.</strong></font></div>\r\n\r\n<div><font color=black><strong>Glory be to the Father and | to the Son*</strong></font></div>\r\n\r\n<div><font color=black><strong>and to the Holy | Spirit;</strong></font></div>\r\n\r\n<div><font color=black><strong>as it was in the be- | ginning,*</strong></font></div>\r\n\r\n<div><font color=black><strong>is now, and will be forever. | Amen.</strong></font></div>\r\n\r\n<div><font color=black>Blessèd are those who dwell | in your house,*</font></div>\r\n\r\n<div><font color=black><strong>ever sing- | ing your praise!</strong></font></div>', '<div><font face=\"g_d0_f9\" size=2>Entrance: 413 O Wondrous Type! O Vision Fair </font></div>\r\n\r\n<div><font face=\"g_d0_f9\" size=2>Of the Day: 415* Jesus on the Mountain Peak </font></div>\r\n\r\n<div><font face=\"g_d0_f9\" size=2>Distribution: </font></div>\r\n\r\n<div><font face=\"g_d0_f9\" size=2>&nbsp;&nbsp;&nbsp;&nbsp;414 ‘Tis Good, Lord, to Be Here </font></div>\r\n\r\n<div><font face=\"g_d0_f9\" size=2>&nbsp;&nbsp;&nbsp;&nbsp;395 O Morning Star, How Fair and Bright </font></div>\r\n\r\n<div><font face=\"g_d0_f9\" size=2>&nbsp;&nbsp;&nbsp;&nbsp;416 Switly Pass the Clouds of Glory </font></div>\r\n\r\n<div><font face=\"g_d0_f9\" size=2>Closing: 417 Alleluia, Song of Gladness </font></div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (452, 3220, 'C', 'LENT', 'Ash Wednesday', 'Black or Violet', '<div><strong>Return to the Lord Your God with All Your Heart</strong></div>\r\n\r\n<div>On Ash Wednesday, we come down from the mountain with Jesus and set our face with His toward the cross in Jerusalem. We make our pilgrimage with Him by the way of repentance, and thus return to the dying and rising of Holy Baptism. For Christ Jesus, &quot;who knew no sin,&quot; became our sin, so that by His death we are released from sin, and in His resurrection we &quot;become the righteousness of God&quot; (2 Cor. 5:21). Since God has thereby reconciled the world to Himself in Christ, &quot;now is the favorable time; behold, now is the day of salvation&quot; (2 Cor. 6:2). He summons you to return to Him with all your heart because He is &quot;gracious and merciful, slow to anger, and abounding in steadfast love&quot; (Joel 2:13). Do so in faith and confidence before Him, and pray to Him as your Father. Give to the needy from a heart of love, and fast for the sake of repentance (Matt. 6:3–4, 6, 17–18).</div>', 'Joel 2:12–19', 'Psalm 51:1–13 (14–19)', '2 Cor. 5:20b—6:10', 'Matt. 6:1–6, 16–21', '<div><font color=black><strong>INTROIT Ps. 51:1–3, 10–12; antiphon: Ps. 51:17 </strong></font></div>\r\n\r\n<div><font color=black>The sacrifices of God are a broken | spirit;* </font></div>\r\n\r\n<div><font color=black><strong>&nbsp;a broken and contrite heart, O God, you will | not despise. </strong></font></div>\r\n\r\n<div><font color=black>Have mercy on me, O God, according to your | steadfast love;*</font></div>\r\n\r\n<div><font color=black><strong>&nbsp;according to your abundant mercy blot out my trans- | gressions. </strong></font></div>\r\n\r\n<div><font color=black>Wash me thoroughly from my in- | iquity,* </font></div>\r\n\r\n<div><font color=black><strong>&nbsp;and cleanse me | from my sin! </strong></font></div>\r\n\r\n<div><font color=black>For I know my trans- | gressions,* </font></div>\r\n\r\n<div><font color=black>&nbsp;<strong>and my sin is ever be- | fore me. </strong></font></div>\r\n\r\n<div><font color=black>Create in me a clean heart, | O God,* </font></div>\r\n\r\n<div><font color=black><strong>&nbsp;and renew a right spirit with- | in me. </strong></font></div>\r\n\r\n<div><font color=black>Cast me not away from your | presence,* </font></div>\r\n\r\n<div><font color=black>&nbsp;<strong>and take not your Holy Spirit | from me. </strong></font></div>\r\n\r\n<div><font color=black>Restore to me the joy of your sal- | vation,* </font></div>\r\n\r\n<div><font color=black>&nbsp;<strong>and uphold me with a willing | spirit. </strong></font></div>\r\n\r\n<div><font color=black><strong>Glory be to the Father and | to the Son* </strong></font></div>\r\n\r\n<div><font color=black><strong>and to the Holy | Spirit; </strong></font></div>\r\n\r\n<div><font color=black><strong>as it was in the be- | ginning,* </strong></font></div>\r\n\r\n<div><font color=black><strong>is now, and will be forever. | Amen. </strong></font></div>\r\n\r\n<div><font color=black>The sacrifices of God are a broken | spirit;* </font></div>\r\n\r\n<div><font color=black><strong>&nbsp;a broken and contrite heart, O God, you will | not despise.</strong></font></div>\r\n\r\n<div>&nbsp;</div>', '<div><font color=black>Entrance: &nbsp;419 Savior, When in Dust toThee </font></div>\r\n\r\n<div><font color=black>Of the Day: &nbsp;607 &nbsp;From Depths of Woe I Cry to &nbsp;Thee </font></div>\r\n\r\n<div><font color=black>Distribution: &nbsp;</font></div>\r\n\r\n<div><font color=black>&nbsp;&nbsp;&nbsp;&nbsp;616 Baptismal Waters Cover Me </font></div>\r\n\r\n<div><font color=black>&nbsp;&nbsp;&nbsp;&nbsp;561 The Tree of Life </font></div>\r\n\r\n<div><font color=black>&nbsp;&nbsp;&nbsp;&nbsp;550 &nbsp;Lamb of God </font></div>\r\n\r\n<div><font color=black>Closing: 568 If Your Beloved Son, O God </font></div>', '<div>Imposition of Ashes is appropriate at this service.</div>\r\n\r\n<div>Holy Communion is appropriate at this service.</div>');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (453, 3230, 'C', 'LENT', 'First S. in Lent', 'Violet', '<div><strong>Jesus Christ Is Our Champion Against the Devil</strong></div>\r\n\r\n<div>Jesus Christ, our Champion against the devil, endures and overcomes &quot;every temptation&quot; (Luke 4:13) on our behalf. He worships the Lord, His God, and serves Him only by trusting the Word of His Father: &quot;You are my beloved Son; with you I am well pleased&quot; (Luke 3:22). Jesus\' victory is now ours through His gracious Word, which is not far away but near us - in our mouth and in our heart, in the proclamation of repentance and faith. For &quot;with the heart one believes and is justified, and with the mouth one confesses and is saved&quot; (Rom. 10:10). Our confession of Christ includes the prayer of faith, which is not disappointed, &quot;for ‘everyone who calls on the name of the Lord will be saved\'&quot; (Rom. 10:13). The Lord is not oblivious to &quot;our affliction, our toil, and our oppression&quot; (Deut. 26:7), but has mercy upon us. He has brought us out of bondage through the &quot;signs and wonders&quot; of Holy Baptism, &quot;with a mighty hand and an outstretched arm&quot; (Deut. 26:8), and now He leads us by His Spirit even in the wilderness.</div>', 'Deut. 26:1–11', 'Psalm 91:1–13', 'Rom. 10:8b–13', 'Luke 4:1–13', '<div><font color=black><strong>INTROIT Ps. 91:9–13; antiphon: Ps. 91:15–16</strong></font></div>\r\n\r\n<div><font color=black>When he calls to me, I will answer him; I will be with him in | trouble;* </font></div>\r\n\r\n<div><font color=black>&nbsp;<strong>I will rescue him and | honor him. </strong></font></div>\r\n\r\n<div><font color=black>With long life I will sat- | isfy him* </font></div>\r\n\r\n<div><font color=black>&nbsp;<strong>and show him my sal- | vation. </strong></font></div>\r\n\r\n<div><font color=black>Because you have made the LORD your | dwelling place—* </font></div>\r\n\r\n<div><font color=black>&nbsp;<strong>the Most High, who is my | refuge— </strong></font></div>\r\n\r\n<div><font color=black>no evil shall be allowed to be- | fall you,* </font></div>\r\n\r\n<div><font color=black>&nbsp;<strong>no plague come | near your tent. </strong></font></div>\r\n\r\n<div><font color=black>For he will command his angels con- | cerning you* </font></div>\r\n\r\n<div><font color=black>&nbsp;<strong>to guard you in | all your ways. </strong></font></div>\r\n\r\n<div><font color=black>On their hands they will | bear you up,* </font></div>\r\n\r\n<div><font color=black>&nbsp;<strong>lest you strike your foot a- | gainst a stone. </strong></font></div>\r\n\r\n<div><font color=black>You will tread on the lion and the | adder;* </font></div>\r\n\r\n<div><font color=black><strong>&nbsp;the young lion and the serpent you will trample | underfoot. </strong></font></div>\r\n\r\n<div><font color=black><strong>Glory be to the Father and | to the Son* </strong></font></div>\r\n\r\n<div><font color=black><strong>and to the Holy | Spirit; </strong></font></div>\r\n\r\n<div><font color=black><strong>as it was in the be- | ginning,* </strong></font></div>\r\n\r\n<div><font color=black><strong>is now, and will be forever. | Amen. </strong></font></div>\r\n\r\n<div><font color=black>When he calls to me, I will answer him; I will be with him in | trouble;* </font></div>\r\n\r\n<div><font color=black>&nbsp;I will rescue him and | honor him. With long life I will sat- | isfy him* and show him my sal- | vation.</font></div>', '<div><font face=\"Calibri (Detail)\" size=2>Entrance: 657 A Mighty Fortress Is Our God </font></div>\r\n\r\n<div><font face=\"Calibri (Detail)\" size=2>Of the Day: 424* O Christ, You Walked the Road Distribution: </font></div>\r\n\r\n<div><font face=\"Calibri (Detail)\" size=2>&nbsp;&nbsp;&nbsp;&nbsp;718 Jesus, Lead Thou On </font></div>\r\n\r\n<div><font face=\"Calibri (Detail)\" size=2>&nbsp;&nbsp;&nbsp;&nbsp;666 O Little Flock, Fear Not the Foe </font></div>\r\n\r\n<div><font face=\"Calibri (Detail)\" size=2>&nbsp;&nbsp;&nbsp;&nbsp;746 Through Jesus’ Blood and Merit </font></div>\r\n\r\n<div><font face=\"Calibri (Detail)\" size=2>Closing: 418 O Lord, throughout These Forty Days </font></div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (454, 3240, 'C', 'LENT', 'Second S. in Lent', 'Violet', '<div><strong>Jesus Rescues Us from Death and Brings Us into Heaven</strong></div>\r\n\r\n<div>The prophet Jeremiah faithfully preached &quot;all that the Lord had commanded him to speak to all the people&quot; (Jer. 26:8). He called the people to repentance, lest the Lord\'s judgment come upon them. The violence that Jeremiah suffered for this preaching foreshadowed the cross and Passion of Christ Jesus, who suffered the judgment of God for the redemption of all people. For Jesus &quot;comes in the name of the Lord&quot; (Luke 13:35) in order to lay down His life for the sins of the world. Earthly Jerusalem was blind to His gracious visitation, and it put Him to death like the prophets before Him. Yet, His sacrifice upon the cross became the cornerstone of the new Jerusalem, His Church. He visits us today in mercy with His preaching of forgiveness, to gather us to Himself within that holy city, &quot;as a hen gathers her brood under her wings&quot; (Luke 13:34), for &quot;our citizenship is in heaven&quot; (Phil. 3:20).</div>', 'Jer. 26:8–15', 'Psalm 4', 'Phil. 3:17—4:1', 'Luke 13:31–35', '<div><font color=black><strong>INTROIT Ps. 74:1–3; antiphon: Ps. 69:9</strong> </font></div>\r\n\r\n<div><font color=black>For zeal for your house has con- | sumed me,* </font></div>\r\n\r\n<div><font color=black>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and the reproaches of those who reproach you have fall- | en on me. </strong></font></div>\r\n\r\n<div><font color=black>O God, why do you cast us off for- | ever?* </font></div>\r\n\r\n<div><font color=black>&nbsp;&nbsp;&nbsp;&nbsp;<strong>Why does your anger smoke against the sheep of your | pasture?</strong> </font></div>\r\n\r\n<div><font color=black>Remember your congregation, which you have purchased of old, which you have redeemed to be the tribe of your | heritage!* </font></div>\r\n\r\n<div><font color=black>&nbsp;&nbsp;&nbsp;&nbsp;<strong>Remember Mount Zion, where | you have dwelt. </strong></font></div>\r\n\r\n<div><font color=black>Direct your steps to the perpetual | ruins;* </font></div>\r\n\r\n<div><font color=black><strong>&nbsp;&nbsp;&nbsp;&nbsp;the enemy has destroyed everything in the sanctu- | ary! </strong></font></div>\r\n\r\n<div><font color=black><strong>Glory be to the Father and | to the Son* </strong></font></div>\r\n\r\n<div><font color=black><strong>and to the Holy | Spirit; as it was in the be- | ginning,* </strong></font></div>\r\n\r\n<div><font color=black><strong>is now, and will be forever. | Amen. </strong></font></div>\r\n\r\n<div><font color=black>For zeal for your house has con- | sumed me,*</font></div>\r\n\r\n<div><font color=black>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and the reproaches of those who reproach you have fall- | en on me. </strong></font></div>\r\n\r\n<div>&nbsp;</div>', '<div><font face=\"Calibri (Detail)\" size=3>Entrance: 586 Preach You the Word </font></div>\r\n\r\n<div><font face=\"Calibri (Detail)\" size=3>Of the Day: 708 Lord, Thee I Love with All My Heart </font></div>\r\n\r\n<div><font face=\"Calibri (Detail)\" size=3>Distribution: </font></div>\r\n\r\n<div><font face=\"Calibri (Detail)\" size=3>&nbsp;&nbsp;&nbsp;&nbsp;635 O Gracious Lord, I Firmly Am Believing </font></div>\r\n\r\n<div><font face=\"Calibri (Detail)\" size=3>&nbsp;&nbsp;&nbsp;&nbsp;639 Wide Open Stand the Gates </font></div>\r\n\r\n<div><font face=\"Calibri (Detail)\" size=3>&nbsp;&nbsp;&nbsp;&nbsp;725 Children of the Heavenly Father </font></div>\r\n\r\n<div><font face=\"Calibri (Detail)\" size=3>Closing: 728 How Firm a Foundation </font></div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (455, 3250, 'C', 'LENT', 'Third S. in Lent', 'Violet', '<div><strong>Jesus Calls You to Repentance</strong></div>\r\n\r\n<div>Unless you repent, you will all likewise perish&quot; (Luke 13:3, 5). By this warning, the Lord would turn us away from wickedness and bring us to life in Himself. For He is patient with us, that we not be cut down in our sin but live and bear fruit in Him. As He lives, the Lord has &quot;no pleasure in the death of the wicked, but that the wicked turn from his way and live&quot; (Ezek. 33:11). So the Scriptures have been &quot;written down for our instruction, on whom the end of the ages has come&quot; (1 Cor. 10:11), that we should not desire evil but trust in Christ. He alone is faithful, the Rock who feeds us with His &quot;spiritual food&quot; and pours out His &quot;spiritual drink&quot; (1 Cor. 10:3–4).</div>', 'Ezek. 33:7–20', 'Psalm 85', '1 Cor. 10:1–13', 'Luke 13:1–9', '<div><strong>INTROIT Ps. 5:4–8; antiphon: Ps. 1:6 </strong></div>\r\n\r\n<div>For the LORD knows the way of the | righteous,* </div>\r\n\r\n<div><strong>but the way of the wicked will | perish.</strong> </div>\r\n\r\n<div>For you are not a God who delights in | wickedness;* </div>\r\n\r\n<div><strong>evil may not | dwell with you. </strong></div>\r\n\r\n<div>The boastful shall not stand be- | fore your eyes;* </div>\r\n\r\n<div><strong>you hate all evil- | doers. </strong></div>\r\n\r\n<div>You destroy those | who speak lies;* </div>\r\n\r\n<div><strong>the LORD abhors the bloodthirsty and de- | ceitful man. </strong></div>\r\n\r\n<div>But I, through the abundance of your steadfast love, will en- | ter your house.* </div>\r\n\r\n<div><strong>I will bow down toward your holy temple in the | fear of you. </strong></div>\r\n\r\n<div>Lead me, O LORD, in your righteousness because of my | enemies;* </div>\r\n\r\n<div><strong>make your way straight be- | fore me. </strong></div>\r\n\r\n<div><strong>Glory be to the Father and | to the Son* </strong></div>\r\n\r\n<div><strong>and to the Holy | Spirit; </strong></div>\r\n\r\n<div><strong>as it was in the be- | ginning,* </strong></div>\r\n\r\n<div><strong>is now, and will be forever. | Amen.</strong> </div>\r\n\r\n<div>For the LORD knows the way of the | righteous,* </div>\r\n\r\n<div><strong>but the way of the wicked will | perish.</strong></div>', '<div>Entrance: 824 May God Bestow on Us His Grace </div>\r\n\r\n<div>Of the Day: 756* Why Should Cross and Trial Grieve Me </div>\r\n\r\n<div>Distribution: &nbsp;</div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;765 God Moves in a Myserious Way </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;764 When Aimless Violence Takes Those We Love </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;733 O God, Our Help in Ages Past </div>\r\n\r\n<div>Closing: 719 I Leave All Things to God’s &nbsp;</div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (456, 3260, 'C', 'LENT', 'Fourth S. in Lent', 'Violet', '<div><strong>Jesus Christ Has Reconciled Us to the Father</strong></div>\r\n\r\n<div>God the Father has opened His heart to us in love. While we were &quot;still a long way off,&quot; He saw us and &quot;felt compassion&quot; (Luke 15:20). Therefore, He gave His only begotten Son for us, making &quot;him to be sin who knew no sin, so that in him we might become the righteousness of God&quot; (2 Cor. 5:21). By the ministry of reconciliation, He runs to us, embraces us in mercy and clothes us with His glory as beloved sons in Christ Jesus. And so we give thanks unto the Lord our God, who has taken away our sins and turned His anger from us (Is. 12:1). Because He has become our salvation, our strength and our song, we &quot;will trust, and will not be afraid&quot; (Is. 12:2).0</div>', 'Is. 12:1–6', 'Psalm 32', '2 Cor. 5:16–21', 'Luke 15:1–3, 11–32', '<div>INTROIT Ps. 51:2–6; antiphon: Ps. 51:1 </div>\r\n\r\n<div>Have mercy on me, O God, according to your | steadfast love;* </div>\r\n\r\n<div>&nbsp;<strong>according to your abundant mercy blot out my trans- | gressions. </strong></div>\r\n\r\n<div>Wash me thoroughly from my in- | iquity,* </div>\r\n\r\n<div>&nbsp;<strong>and cleanse me | from my sin! </strong></div>\r\n\r\n<div>For I know my trans- | gressions,* </div>\r\n\r\n<div><strong>&nbsp;and my sin is ever be- | fore me.</strong> </div>\r\n\r\n<div>Against you, you only, have I sinned and done what is evil | in your sight,*</div>\r\n\r\n<div>&nbsp;<strong>so that you may be justified in your words and blameless in your | judgment. </strong></div>\r\n\r\n<div>Behold, I was brought forth in in- | iquity,* </div>\r\n\r\n<div>&nbsp;<strong>and in sin did my mother con- | ceive me.</strong> </div>\r\n\r\n<div>Behold, you delight in truth in the inward | being,* </div>\r\n\r\n<div>&nbsp;<strong>and you teach me wisdom in the | secret heart. </strong></div>\r\n\r\n<div><strong>Glory be to the Father and | to the Son* </strong></div>\r\n\r\n<div><strong>and to the Holy | Spirit; </strong></div>\r\n\r\n<div><strong>as it was in the be- | ginning,* </strong></div>\r\n\r\n<div><strong>is now, and will be forever. | Amen. </strong></div>\r\n\r\n<div>Have mercy on me, O God, according to your | steadfast love;* </div>\r\n\r\n<div>&nbsp;</div>', '<div>Entrance: 915 Today Your Mercy Calls Us </div>\r\n\r\n<div>Of the Day: 571 God Loved the World So That He Gave </div>\r\n\r\n<div>Distribution: &nbsp;</div>\r\n\r\n<div>\t421 Jesus, Grant That Balm and Healing </div>\r\n\r\n<div>\t425 When I Survey the Wondrous Cross </div>\r\n\r\n<div>\t609 Jesus Sinners Doth Receive </div>\r\n\r\n<div>Closing: 435 Come to Calvary’s Holy Mountain</div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (457, 3270, 'C', 'LENT', 'Fifth S. in Lent', 'Violet', '<div><strong>God\'s Beloved Son Has Redeemed Us</strong></div>\r\n\r\n<div>Our life and works apart from Christ, no matter how they may glitter to the eyes of the world, are ultimately rubbish and have no righteousness. Rather, in the scandalous cross of Jesus we find our righteousness alone &quot;through faith in Christ&quot; (Phil. 3:9). By such faith, we &quot;know him and the power of his resurrection&quot; (Phil. 3:10). For the same God who brought Israel out of Egypt has done a &quot;new thing&quot; for us in Christ Jesus (Is. 43:19). He has sent His beloved Son into His vineyard to be killed by sinful men and to become &quot;the stone that the builders rejected.&quot; Yet, the One rejected by men &quot;has become the cornerstone&quot; of His Church (Luke 20:17). Through the waters of Holy Baptism, He provides us daily refreshment in our earthly pilgrimage, &quot;a way in the wilderness and rivers in the desert&quot; (Is. 43:19).</div>', 'Is. 43:16–21', 'Psalm 126', 'Phil. 3:(4b–7) 8-14', 'Luke 20:9–20', '<div><strong>INTROIT Ps. 3:3–6; antiphon: Ps. 3:8 </strong></div>\r\n\r\n<div>Salvation belongs | to the LORD;* </div>\r\n\r\n<div>&nbsp;<strong>your blessing be on your | people! </strong></div>\r\n\r\n<div>But you, O LORD, are a shield a- | bout me,* </div>\r\n\r\n<div>&nbsp;<strong>my glory, and the lifter | of my head. </strong></div>\r\n\r\n<div>I cried aloud | to the LORD,* </div>\r\n\r\n<div>&nbsp;<strong>and he answered me from his | holy hill. </strong></div>\r\n\r\n<div>I lay | down and slept;* </div>\r\n\r\n<div>&nbsp;<strong>I woke again, for the LORD sus- | tained me. </strong></div>\r\n\r\n<div>I will not be afraid of many thousands of | people* </div>\r\n\r\n<div>&nbsp;<strong>who have set themselves against me | all around. </strong></div>\r\n\r\n<div><strong>Glory be to the Father and | to the Son* </strong></div>\r\n\r\n<div><strong>and to the Holy | Spirit; </strong></div>\r\n\r\n<div><strong>as it was in the be- | ginning,* </strong></div>\r\n\r\n<div><strong>is now, and will be forever. | Amen. </strong></div>\r\n\r\n<div>Salvation belongs | to the LORD;* </div>\r\n\r\n<div>&nbsp;<strong>your blessing be on your | people!</strong></div>', '<div>Entrance: &nbsp;423 &nbsp;Jesus, Refuge of the Weary </div>\r\n\r\n<div>Of the Day: &nbsp;430* My Song Is Love Unknown </div>\r\n\r\n<div>Distribution: &nbsp;</div>\r\n\r\n<div>420 Christ, the Life of All the Living </div>\r\n\r\n<div>685 Let Us Ever Walk with Jesus </div>\r\n\r\n<div>644 The Church’s One Foundation </div>\r\n\r\n<div>Closing: 427 In the Cross of Christ I Glory</div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (458, 3280, 'C', 'LENT', 'Palm Sunday', 'Red', NULL, 'Deut. 32:36–39', 'Psalm 118:', 'Phil. 2:5–11', 'Luke 22:1—23:56 or', NULL, NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (459, 3290, 'C', 'HOLY WEEK', 'Palm Sunday / Sunday of the Passion ', 'Red', '<div>The Cross and Passion of Our Lord Are the Hour of His Glory\\rThe King of Israel comes into His royal glory by the path of humble obedience &quot;to the point of death, even death on a cross&quot; (Phil. 2:8). He &quot;goes as it has been determined&quot; (Luke 22:22), according to the Scriptures, willingly submitting to His Father\'s plan for the salvation of sinners. &quot;Therefore God has highly exalted him and bestowed on him the name that is above every name&quot; (Phil. 2:9). His suffering and death open the way of repentance for the forgiveness of sins because He goes to the cross bearing the sins of the world. In His resurrection, God the Father vindicates His people and has compassion on His servants (Deut. 32:36). He kills to make alive; He wounds in order to heal. In remembrance of Him, we praise God, confessing &quot;that Jesus Christ is Lord, to the glory of God the Father&quot; (Phil. 2:11).</div>', 'Duteronomy 32:36-39', 'Psalm 118:19-29; Psalm 31:9-16', 'Philippians 2:5-11', 'Luke 22:1-23,56; Luke 23:1-56; John 12:20-43', '<div><font color=black><strong>INTROIT Ps. 24:7–10; antiphon: Ps. 118:26 </strong></font></div>\r\n\r\n<div><font color=black>Blessèd is he who comes in the name | of the LORD!* </font></div>\r\n\r\n<div><font color=black>&nbsp;<strong>We bless you from the house | of the LORD. </strong></font></div>\r\n\r\n<div><font color=black>Lift up your heads, O gates! And be lifted up, O | ancient doors,* </font></div>\r\n\r\n<div><font color=black>&nbsp;<strong>that the King of glory | may come in. </strong></font></div>\r\n\r\n<div><font color=black>Who is this King of | glory?* </font></div>\r\n\r\n<div><font color=black>&nbsp;<strong>The LORD, strong and mighty, the LORD, mighty in | battle! </strong></font></div>\r\n\r\n<div><font color=black>Lift up your heads, O gates! And lift them up, O | ancient doors,* </font></div>\r\n\r\n<div><font color=black>&nbsp;<strong>that the King of glory | may come in. </strong></font></div>\r\n\r\n<div><font color=black>Who is this King of | glory?* </font></div>\r\n\r\n<div><font color=black><strong>&nbsp;The LORD of hosts, he is the King of | glory! </strong></font></div>\r\n\r\n<div><font color=black>Blessèd is he who comes in the name | of the LORD!* </font></div>\r\n\r\n<div><font color=black>&nbsp;<strong>We bless you from the house | of the LORD. </strong></font></div>\r\n\r\n<div>&nbsp;</div>', '<div><font color=black>Entrance: &nbsp;442 All Glory, Laud, and Honor Of the Day: &nbsp;</font></div>\r\n\r\n<div><font color=black>438 A Lamb Goes Uncomplaining Forth </font></div>\r\n\r\n<div><font color=black>Distribution: &nbsp;</font></div>\r\n\r\n<div><font color=black>&nbsp;443 Hosanna, Loud Hosanna </font></div>\r\n\r\n<div><font color=black>&nbsp;444 No Tramp of Soldiers’ Marching &nbsp;Feet </font></div>\r\n\r\n<div><font color=black>&nbsp;&nbsp;441 Ride On, Ride On in Magesty </font></div>\r\n\r\n<div><font color=black>Closing: &nbsp;440 Jesus, I Will Ponder Now</font></div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (460, 3300, 'C', 'HOLY WEEK', 'Monday in Holy Week', 'Scarlet or Violet', NULL, 'Is. 50:5-10', 'Psalm 36:5-10', 'Heb. 9:11-15', 'Matt. 26:1-27:66 orJohn 12:1-23', NULL, NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (461, 3310, 'C', 'HOLY WEEK', 'Tuesday in Holy Week', 'Scarlet or Violet', NULL, 'Is. 49:1-7', 'Psalm 71:1–14', '1 Cor. 1:18-25(26-31)', 'Mark 14:1-15:47 or John 12:23-50', NULL, NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (462, 3320, 'C', 'HOLY WEEK', 'Wednesday in Holy Week', 'Scarlet or Violet', NULL, 'Is. 62:11-63:7', 'Psalm 70', 'Rom. 5:6-11', 'Luke 22:1-23:56 or John 13:38', NULL, NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (463, 3330, 'C', 'HOLY WEEK', 'Holy (Maundy) Thursday', 'Red', '<div><strong>Let Us Love One Another, as Christ Jesus Has Loved Us</strong></div>\r\n\r\n<div>By Holy Baptism, &quot;with our hearts sprinkled clean from an evil conscience and our bodies washed with pure water&quot; (Heb. 10:22), we enter the holy place with Jesus. For Jesus is our Passover Lamb who has been sacrificed for us. He reclines at table with us and feeds us with His own flesh and blood: &quot;the new and living way that he opened for us through the curtain&quot; (Heb. 10:20). In Christ, the Lord remembers us in mercy and remembers our sin no more; He forgives us all our iniquity (Jer. 31:34; Heb. 10:17). With such love, He &quot;loved his own who were in the world,&quot; and He even loves us &quot;to the end&quot; (John 13:1). As He washes us and feeds us in love, let us love one another, just as He has loved us (John 13:34).</div>', 'Jer. 31:31–34 or Ex. 12:1–14', 'Psalm 116:12-16', 'Heb. 10:15–25 or 1 Cor. 11:23–32', 'Luke 22:7–20 or John 13:1–17, 31b–35', NULL, '<div><font face=\"g_d0_f9\" size=2>Entrance: 446 Jesus, Greatest at the Table </font></div>\r\n\r\n<div><font face=\"g_d0_f9\" size=2>Of the Day: 617 O Lord, We Praise Thee </font></div>\r\n\r\n<div><font face=\"g_d0_f9\" size=2>Distribution: </font></div>\r\n\r\n<div><font face=\"g_d0_f9\" size=2>&nbsp;&nbsp;&nbsp;&nbsp;627 Jesus Christ, Our Blessed Savior </font></div>\r\n\r\n<div><font face=\"g_d0_f9\" size=2>&nbsp;&nbsp;&nbsp;&nbsp;636 Soul, Adorn Yourself with Gladness </font></div>\r\n\r\n<div><font face=\"g_d0_f9\" size=2>445 When You Woke That Thursday Morning </font></div>\r\n\r\n<div><font face=\"g_d0_f9\" size=2>Closing: Psalm 22 Chanted </font></div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (464, 3340, 'C', 'HOLY WEEK', 'Good Friday', 'Black', NULL, 'Is. 52:13—53:12', 'Psalm 22 or Psalm 31', 'Heb. 4:14–16; 5:7–9', 'John 18:1—19:42 or John 19:17–30', NULL, NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (465, 3350, 'C', 'HOLY WEEK', 'Holy Saturday', 'Black', NULL, 'Dan 6:1-24', 'Psalm 16', '1 Pet. 4:1-8', 'Matt. 27:57-66', NULL, NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (466, 3360, 'C', 'EASTER', 'The Resurrection of Our Lord (Vigil of Easter)', 'White or Gold', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (467, 3370, 'C', 'EASTER', 'The Resurrection of Our Lord (Easter Sunrise)', 'White or Gold', '<div><strong>Our Redeemer Lives!</strong></div>\r\n\r\n<div>In Adam, all die because all sin. The children of that first gardener have been driven out of Paradise and return to the dust whence they were taken. But now another Gardener has come, who has made His bed in the dust of the earth, and in His resurrection He has opened paradise for all the children of Adam. For &quot;death is swallowed up in victory&quot; (1 Cor. 15:54), and God &quot;gives us the victory through our Lord Jesus Christ&quot; (1 Cor. 15:57). So we each confess that &quot;my Redeemer lives&quot; and &quot;in my flesh I shall see God&quot; (Job 19:25, 26). As He has called us out of darkness into light and wiped away our tears, we behold Him now by faith and recognize His voice in the Gospel. We enter His tomb by the death of Holy Baptism, and we also share His resurrection. For as surely as He has risen, so we also one day &quot;must rise from the dead&quot; (John 20:9).</div>', 'Job 19:23–27', 'Psalm 118:15-29', '1 Cor. 15:51–57', 'John 20:1–18', '<div><strong>INTROIT Ex. 15:2a, 6, 13, 17–18; antiphon: Ex. 15:1b </strong></div>\r\n\r\n<div>I will sing to the LORD, for he has triumphed | gloriously;* </div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;the horse and his rider he has thrown in- | to the sea. </strong></div>\r\n\r\n<div>The LORD is my strength | and my song,* </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and he has become my sal- | vation. </strong></div>\r\n\r\n<div>Your right hand, O LORD, glorious | in power,* </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>your right hand, O LORD, shatters the | enemy.</strong> </div>\r\n\r\n<div>You have led in your steadfast love the people whom you | have redeemed;* </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>you have guided them by your strength to your ho- | ly abode.</strong></div>\r\n\r\n<div>You will bring them in and plant them on your own | mountain,* </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;the place, O LORD, which you have made for | your abode, </div>\r\n\r\n<div>the sanctuary, O Lord, which your hands have es- | tablished.* </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>The LORD will reign forever and | ever. </strong></div>\r\n\r\n<div><strong>Glory be to the Father and | to the Son* </strong></div>\r\n\r\n<div><strong>and to the Holy | Spirit; </strong></div>\r\n\r\n<div><strong>as it was in the be- | ginning,* </strong></div>\r\n\r\n<div><strong>is now, and will be forever. | Amen. </strong></div>\r\n\r\n<div>I will sing to the LORD, for he has triumphed | gloriously;* </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>the horse and his rider he has thrown in- | to the sea.</strong></div>', '<div><font face=\"Calibri (Detail)\" size=2>Entrance: 461 I Know That My Redeemer Lives </font></div>\r\n\r\n<div><font face=\"Calibri (Detail)\" size=2>Of the Day: 486* If Christ Had Not Been Raised from Death </font></div>\r\n\r\n<div><font face=\"Calibri (Detail)\" size=2>Distribution: </font></div>\r\n\r\n<div><font face=\"Calibri (Detail)\" size=2>&nbsp;&nbsp;&nbsp;&nbsp;478 The Day of Resurrection </font></div>\r\n\r\n<div><font face=\"Calibri (Detail)\" size=2>&nbsp;&nbsp;&nbsp;&nbsp;464 The Strife is O’er, the Battle Done </font></div>\r\n\r\n<div><font face=\"Calibri (Detail)\" size=2>&nbsp;&nbsp;&nbsp;&nbsp;633 At the Lamb’s High Feast We Sing </font></div>\r\n\r\n<div><font face=\"Calibri (Detail)\" size=2>&nbsp;&nbsp;&nbsp;&nbsp;475 Good Christians Friends, Rejoice and Sing </font></div>\r\n\r\n<div><font face=\"Calibri (Detail)\" size=2>Closing: 457 Jesus Christ Is Risen Today </font></div>', '');
