INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (593, 4790, '1', 'TRINITY', 'Last Sunday of the Church Year', 'Green', NULL, 'Is. 65:17–25', 'Psalm 149', '1 Thess. 5:1–11', 'Matt. 25:1–13', NULL, NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (597, 5000, 'F', NULL, 'St. Andrew, Apostle (November 30)', 'Red', NULL, 'Ezek 3:16-21', 'Psalm 139:1-12', 'Rom 10:8b-18', 'John 1:35-42a', '<div>INTROIT Ps. 89:1, 5, 15–16; antiphon: John 15:27 You also will bear | witness,* because you have been with me from the be- | ginning. I will sing of the steadfast love of the LORD, for- | ever;* with my mouth I will make known your faithfulness to all gener- | ations. Let the heavens praise your wonders, | O LORD,* your faithfulness in the assembly of the | holy ones!</div>\r\n\r\n<div>Blessèd are the people who know the | festal shout,* who walk, O LORD, in the light | of your face, who exult in your name | all the day* and in your righteousness are ex- | alted. Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. You also will bear | witness,* because you have been with me from the be- | ginning.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (598, 6010, 'O', NULL, 'Mission Observance', 'White', NULL, 'Isa 62:1-7', 'Psalm 96', 'Romans 10:11-17', 'Luke 24:44-53', '<div>INTROIT Ps. 108:3–5; antiphon: Ps. 105:1 Oh give thanks to the LORD; call up- | on his name;* make known his deeds among the | peoples! I will give thanks to you, O LORD, among the | peoples;* I will sing praises to you among the | nations. For your steadfast love is great above the |heavens;* your faithfulness reaches | to the clouds. Be exalted, O God, above the | heavens!* Let your glory be over | all the earth! Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. Oh give thanks to the LORD; call up- | on his name;* make known his deeds among the | peoples!</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (599, 5010, 'F', NULL, 'St. Thomas, Apostle (December 21)\r\nSt. Thomas, Apostle (December 21)', 'Red', NULL, 'Judges 6:36-40', 'Psalm 136:1-4', 'Eph 4:7, 11-16', 'John 20:24-29', '<div>INTROIT Ps. 89:1, 5, 15–16; antiphon: Ps. 31:14 I trust in you, | O LORD;* I say, “You | are my God.” I will sing of the steadfast love of the LORD, for- | ever;* with my mouth I will make known your faithfulness to all gener- | ations. Let the heavens praise your wonders, | O LORD,* your faithfulness in the assembly of the | holy ones! Blessèd are the people who know the | festal shout,* who walk, O LORD, in the light | of your face, who exult in your name | all the day* and in your righteousness are ex- | alted. Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. I trust in you, | O LORD;* I say, “You | are my God.”</div>\r\n\r\n<div>&nbsp;</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (600, 5020, 'F', NULL, 'St. Stephen, Martyr (December 26)', 'Red', NULL, '2 Chron 24:17-22', 'Psalm 119:137-144', 'Acts 6:8-7:2a, 51-60', 'Matt 23:34-39', '<div>INTROIT Ps. 31:1, 3, 5; antiphon: Rev. 7:14b These are the ones coming out of the great tribu- | lation.* They have washed their robes and made them white in the blood | of the Lamb. In you, O LORD, do I take refuge; let me never be | put to shame;* in your righteousness de- | liver me.For you are my rock and my | fortress;* and for your name’s sake you lead me and | guide me. Into your hand I commit my | spirit;* you have redeemed me, O LORD, | faithful God. Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. These are the ones coming out of the great tribu- | lation.* They have washed their robes and made them white in the blood | of the Lamb.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (601, 5030, 'F', NULL, 'St. John, Apostle and Evangelist (December 27)', 'White', NULL, 'Rev 1:1-6', 'Psalm 11', '1 John 1:1-2:2', 'John 21:20-25', '<div>INTROIT Ps. 92:1–5; antiphon: John 20:31 These are written so that you may believe that Jesus is the Christ, the | Son of God,* and that by believing you may have life | in his name. It is good to give thanks | to the LORD,* to sing praises to your name, | O Most High; to declare your steadfast love in the | morning,* and your faithful- | ness by night, to the music of the lute | and the harp,* to the melody | of the lyre. For you, O LORD, have made me glad | by your work;* at the works of your hands I | sing for joy. How great are your works, | O LORD!* Your thoughts are | very deep! Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. These are written so that you may believe that Jesus is the Christ, the | Son of God,* and that by believing you may have life | in his name.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (602, 5040, 'F', NULL, 'Holy Innocents, Martyrs (December 28)', 'Red', NULL, 'Jer 31:15-17', 'Psalm 54', 'Rev 14:1-5', 'Matt 2:13-18', '<div>INTROIT Ps. 31:1, 3, 5; antiphon: Rev. 7:14b</div>\r\n\r\n<div>These are the ones coming out of the great tribu- | lation.* They have washed their robes and made them white in the blood | of the Lamb. In you, O LORD, do I take refuge; let me never be | put to shame;* in your righteousness de- | liver me. For you are my rock and my | fortress;* and for your name’s sake you lead me and | guide me. Into your hand I commit my | spirit;* you have redeemed me, O LORD, | faithful God. Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. These are the ones coming out of the great tribu- | lation.* They have washed their robes and made them white in the blood | of the Lamb.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (604, 5060, 'F', NULL, 'Circumcision and Name of Jesus (Januar 1)', 'White', NULL, 'Num 6:22-27', 'Psalm 8', 'Gal 3:23-29', 'Luke 2:21', '<div>INTROIT Ps. 40:6–8; antiphon: 40:16 May all who seek you rejoice and be | glad in you;* may those who love your salvation say continually, “Great | is the LORD!” Sacrifice and offering you have not desired, but you have given me an | open ear.* Burnt offering and sin offering you have | not required. Then I said, “Behold, | I have come;* in the scroll of the book it is writ- | ten of me: I desire to do your will, | O my God;* your law is with- | in my heart.” Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. May all who seek you rejoice and be | glad in you;* may those who love your salvation say continually, “Great | is the LORD!”</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (605, 5070, 'F', NULL, 'Confession of St. Peter (January 18)', 'White', NULL, 'Acts 4:8-13', 'Psalm 118:19-29', '2 peter 1:1-15', 'Mark 8:27-35(36-9:1)', '<div>INTROIT Ps. 89:1, 5, 15–16; antiphon: Ps. 119:46 I will speak of your testimonies before kings, | [O Lord,]* and shall not be | put to shame. I will sing of the steadfast love of the LORD, for- | ever;* with my mouth I will make known your faithfulness to all gener- | ations. Let the heavens praise your wonders, | O LORD,* your faithfulness in the assembly of the | holy ones! Blessèd are the people who know the | festal shout,* who walk, O LORD, in the light | of your face, who exult in your name | all the day* and in your righteousness are ex- | alted. Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. I will speak of your testimonies before kings, | [O Lord,]* and shall not be | put to shame.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (606, 5080, 'F', NULL, 'St. Timothy, Pastor and Confessor (January 24)', 'White', NULL, 'Acts 16:1-5', 'Psalm 71:15-24', '1 Tim 6:11-16', 'Matt 24:42-47', '<div>INTROIT Ps. 89:1, 5, 15–16; antiphon: 1 Tim. 6:12a, b Fight the good fight | of the faith.* Take hold of the eternal life to which | you were called. I will sing of the steadfast love of the LORD, for- | ever;* with my mouth I will make known your faithfulness to all gener- | ations. Let the heavens praise your wonders, | O LORD,* your faithfulness in the assembly of the | holy ones! Blessèd are the people who know the | festal shout,* who walk, O LORD, in the light | of your face, who exult in your name | all the day* and in your righteousness are ex- | alted. Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. Fight the good fight | of the faith.* Take hold of the eternal life to which | you were called.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (607, 5090, 'F', NULL, 'Converstion of St. Paul (January 25)', 'White', NULL, 'Acts 9:1-22', 'Psalm 67', 'Gal 1:11-24', 'Matt 19:27-30', '<div>INTROIT Ps. 89:1, 5, 15–16; antiphon: Ps. 119:46 I will speak of your testimonies before kings, | [O Lord,]* and shall not be | put to shame. I will sing of the steadfast love of the LORD, for- | ever;* with my mouth I will make known your faithfulness to all gener- | ations. &nbsp;Let the heavens praise your wonders, | O LORD,* your faithfulness in the assembly of the | holy ones! Blessèd are the people who know the | festal shout,* who walk, O LORD, in the light | of your face, who exult in your name | all the day* and in your righteousness are ex- | alted. Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. I will speak of your testimonies before kings, | [O Lord,]* and shall not be | put to shame.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (623, 5140, 'F', NULL, 'Holy Cross Day (September 14)', 'Red', NULL, 'Number 21:4-9', 'Psalm 40:1-11', '1 Cor 1:18-25', 'John 12:20-33', '<div>INTROIT Ps. 98:1, 4, 6; antiphon: Ps. 98:2 The LORD has made known his sal- | vation;* he has revealed his righteousness in the sight of the | nations. Oh sing to the LORD a new song, for he has done | marvelous things!* His right hand and his holy arm have worked salva- | tion for him. Make a joyful noise to the LORD, | all the earth;* break forth into joyous song and sing | praises! With trumpets and the sound | of the horn* make a joyful noise before the | King, the LORD! Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. The LORD has made known his sal- | vation;* he has revealed his righteousness in the sight of the | nations.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (624, 5150, 'F', NULL, 'St. Matthew, Apostle and Evangelist (September 21)', 'Red', NULL, 'Exekiel 2:8-3:11', 'Psalm 119:33-40', 'Eph 4:7-16', 'Matt 9:9-13', '<div>INTROIT Ps. 92:1–5; antiphon: Matt. 9:13b, c</div>\r\n\r\n<div>I desire mercy, and not | sacrifice.* For I came not to call the righteous, but | sinners. It is good to give thanks | to the LORD,* to sing praises to your name, | O Most High; to declare your steadfast love in the | morning,* and your faithful- | ness by night, to the music of the lute | and the harp,* to the melody | of the lyre. For you, O LORD, have made me glad | by your work;* at the works of your hands I | sing for joy. How great are your works, | O LORD!* Your thoughts are | very deep! Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. I desire mercy, and not | sacrifice.* For I came not to call the righteous, but | sinners.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (625, 5160, 'F', NULL, 'St. Michael and All Angels (September 29)', 'White', NULL, 'Daniel 10:10-14; 12:1-3', 'Psalm 91', 'Rev 12:7-12', 'Matt 18:1-11 or Luke 10:17-20', '<div>INTROIT Ps. 103:20–22; antiphon: Ps. 103:1 Bless the LORD, | O my soul,* and all that is within me, bless his | holy name! Bless the LORD, O you his | angels,* you mighty ones who do his word, obeying the voice | of his word! Bless the LORD, | all his hosts,* his ministers, who | do his will! Bless the LORD, all his works, in all places of his do- | minion.* Bless the LORD, | O my soul! Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. Bless the LORD, | O my soul,* and all that is within me, bless his | holy name!</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (626, 5170, 'F', NULL, 'St. Luke, Evangelist (October 18)', 'Red', NULL, 'Isa 35:5-8', 'Psalm 147:1-11', '2 Tim 4:5-18', 'Luke 10:1-9', '<div>INTROIT Ps. 92:1–5; antiphon: Luke 24:46–47 Thus it is written, that the Christ should suffer and on the third day rise | from the dead,* and that repentance and forgiveness of sins should be proclaimed in his name to all nations, beginning from Je- | rusalem. It is good to give thanks | to the LORD,* to sing praises to your name, | O Most High; to declare your steadfast love in the | morning,* and your faithful- | ness by night, to the music of the lute | and the harp,* to the melody | of the lyre. For you, O LORD, have made me glad | by your work;* at the works of your hands I | sing for joy. How great are your works, | O LORD!* Your thoughts are | very deep! Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. Thus it is written, that the Christ should suffer and on the third day rise | from the dead,* and that repentance and forgiveness of sins should be proclaimed in his name to all nations, beginning from Je- | rusalem.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (627, 5170, 'F', NULL, 'St. James of Jerusalem, Brother of Jesus and Martyr (October 23)', 'Red', NULL, 'Acts 15:12-22a', 'Psalm 133', 'Jame 1:12', 'Matt 13:54-58', '<div>INTROIT Ps. 31:1, 3, 5; antiphon: Rev. 7:14b These are the ones coming out of the great tribu- | lation.* They have washed their robes and made them white in the blood | of the Lamb. In you, O LORD, do I take refuge; let me never be | put to shame;* in your righteousness de- | liver me. For you are my rock and my | fortress;* and for your name’s sake you lead me and | guide me. Into your hand I commit my | spirit;* you have redeemed me, O LORD, | faithful God. Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. These are the ones coming out of the great tribu- | lation.* They have washed their robes and made them white in the blood | of the Lamb.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (628, 5180, 'F', NULL, 'St. Simon and St. Jude, Apostles (October 28)', 'Red', NULL, 'Jer 26:1-16', 'Psalm 43', '1 Peter 1:3-9', 'John 15:(12-16)17-21', '<div>INTROIT Ps. 89:1, 5, 15–16; antiphon: Ps. 119:46 I will speak of your testimonies before kings, | [O Lord,]* and shall not be | put to shame. I will sing of the steadfast love of the LORD, for- | ever;* with my mouth I will make known your faithfulness to all gener- | ations. Let the heavens praise your wonders, | O LORD,* your faithfulness in the assembly of the | holy ones! Blessèd are the people who know the | festal shout,* who walk, O LORD, in the light | of your face, who exult in your name | all the day* and in your righteousness are ex- | alted. Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. I will speak of your testimonies before kings, | [O Lord,]* and shall not be | put to shame.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (629, 5190, 'F', NULL, 'Reformation Day (October 31)', 'Red', '<div><font face=Arial size=2 color=\"#3C4043\"><strong>Son of God Has Set Us Free from Sin and Death by His Grace</strong></font></div>\r\n\r\n<div><font face=Arial size=2 color=\"#3C4043\">&quot;Wisdom is justified by her deeds&quot; (Matt. 11:19), and the true Wisdom of God, Christ Jesus the incarnate Son, justifies us by His deeds. He prepares His way by the preaching of repentance, but He has suffered the violence of the Law and voluntarily handed Himself over to violent men, that we might eat and drink with Him in His Kingdom and &quot;remain in the house forever&quot; (John 8:35). For He is &quot;a friend of tax collectors and sinners&quot; (Matt. 11:19), and He has rescued us by His grace from the slavery of sin and death. By the proclamation of His eternal Gospel &quot;to those who dwell on earth, to every nation and tribe and language and people&quot; (Rev. 14:6), &quot;the righteousness of God has been manifested apart from the law&quot; (Rom. 3:21), &quot;that He might be just and the justifier of the one who has faith in Jesus&quot; (Rom. 3:26). And by hearing the Gospel of Christ Jesus, &quot;whom God put forward as a propitiation by His blood, to be received by faith&quot; (Rom. 3:25), &quot;you will know the truth, and the truth will set you free&quot; (John 8:31-32).</font> </div>', 'Rev 14:14:6-7', 'Psalm 46', 'Rom 3:19-28', 'John 8:31-36 or Matt 11:12-19', '<div><strong>INTROIT Ps. 34:1–2, 11, 22; antiphon: Ps. 119:46 </strong></div>\r\n\r\n<div>I will speak of your testimonies before kings, | [O Lord,]* </div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;and shall not be | put to shame. </strong></div>\r\n\r\n<div>I will bless the LORD at | all times;* </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>his praise shall continually be | in my mouth. </strong></div>\r\n\r\n<div>My soul makes its boast | in the LORD;* </div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;let the humble hear | and be glad. </strong></div>\r\n\r\n<div>Come, O children, lis- | ten to me;* </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>I will teach you the fear | of the LORD. </strong></div>\r\n\r\n<div>The LORD redeems the life of his | servants;* </div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;none of those who take refuge in him will | be condemned. </strong></div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div><strong>Glory be to the Father and | to the Son* </strong></div>\r\n\r\n<div><strong>and to the Holy | Spirit; </strong></div>\r\n\r\n<div><strong>as it was in the be- | ginning,* </strong></div>\r\n\r\n<div><strong>is now, and will be forever. | Amen. </strong></div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div>I will speak of your testimonies before kings, | [O Lord,]* </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and shall not be | put to shame.</strong></div>', '<div>Reformation Day (Observed) (Oct. 25, 2020) Entrance: 656 A Mighty Fortress Is Our God </div>\r\n\r\n<div>Of the Day: 555 Salvation unto Us Has Come </div>\r\n\r\n<div>Offertory: 580 The Gospel Shows the Fatherâ€™s Grace </div>\r\n\r\n<div>Distribution: 574 Before the Throne of God Above; </div>\r\n\r\n<div>558 Not unto Us </div>\r\n\r\n<div>Closing: 655 Lord, Keep Us Steadfast in Your Word </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (630, 5200, 'F', NULL, 'All Staints\' Day (November 1)', 'White', '<div><font face=\"Calibri (Detail)\" size=2 color=\"#3C4043\">Saints Are Blessed in the Eternal Presence of Christ</font></div>\r\n\r\n<div><font face=\"Calibri (Detail)\" size=2 color=\"#3C4043\">A great multitude from all tribes and peoples and languages,&quot; cry out &quot;salvation belongs to our God who sits on the throne&quot; (Rev. 7:9-17). Faith-filled saints from every place and time with unified voices eternally magnify the Lamb of God. As His beloved children, we too, &quot;shall see him as he is&quot; (1 John 3:1-3). Joined with the throng of angels and a myriad of saints, we shall &quot;serve him day and night in his temple&quot; (Rev. 7:9-17). In our earthly tension vacillating between saint and sinner, faith and doubt, sacred and profane, we earnestly seek Jesus to calm our fears, comfort our spirits, and forgive our sins. The Holy Spirit, through faith in Christ propels us forward, fortifying us in Word and Sacrament, to our eternal home. In the midst of our constant struggle as believers, we need to be blessed. And so we are. The poor in spirit, the meek, the hungry, the thirsty, the merciful, the pure, and the persecuted are all blessed and we will most certainly inherit the kingdom of heaven (Matt. 5:1-12).</font><font\r\nface=\"Calibri (Detail)\" size=2> </font></div>', 'Rev 7:(2-8)9-17', 'Psalm 149', '1 John 3:1-3', 'Matt 5:1-12', '<div>INTROIT Ps. 31:1, 3, 5; antiphon: Rev. 7:14b </div>\r\n\r\n<div>These are the ones coming out of the great tribu- | lation.* </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>They have washed their robes and made them white in the blood | of the Lamb. </strong></div>\r\n\r\n<div>In you, O LORD, do I take refuge; let me never be | put to shame;* </div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;in your righteousness de- | liver me. </strong></div>\r\n\r\n<div>For you are my rock and my | fortress;* </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>and for your name’s sake you lead me and | guide me. </strong></div>\r\n\r\n<div>Into your hand I commit my | spirit;* </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;<strong>you have redeemed me, O LORD, | faithful God. </strong></div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div><strong>Glory be to the Father and | to the Son* </strong></div>\r\n\r\n<div><strong>and to the Holy | Spirit; </strong></div>\r\n\r\n<div><strong>as it was in the be- | ginning,* </strong></div>\r\n\r\n<div><strong>is now, and will be forever. | Amen. </strong></div>\r\n\r\n<div>&nbsp;</div>\r\n\r\n<div>These are the ones coming out of the great tribu- | lation.* </div>\r\n\r\n<div><strong>&nbsp;&nbsp;&nbsp;&nbsp;They have washed their robes and made them white in the blood | of the Lamb.</strong></div>', '<div>Entrance: 950 Splendor and Honor </div>\r\n\r\n<div>Of the Day: 677 For All the Saints </div>\r\n\r\n<div>Offertory: 949 Heavenly Hosts in Ceaseless Worship </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;932 Jesus Sat with His Disciples; </div>\r\n\r\n<div>&nbsp;&nbsp;&nbsp;&nbsp;676 Behold a Host, Arrayed in White </div>\r\n\r\n<div>Closing: 671 Sing with All the Saints in Glory </div>', '<div>Commoration of the Saints who have gone to be with Jesus over the past year. </div>');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (631, 6000, 'O', NULL, 'Anniversary of a Congregation', 'Red', NULL, '1 Kings 8:22-30', 'Psalm 84', 'Rev 21:1-5', 'Luke 19:1-10', '<div>INTROIT 1 Chron. 29:10b, 11, 13; antiphon: Ps. 26:8 O LORD, I love the habitation | of your house* and the place where your | glory dwells. Blessèd are you, O LORD, the God of | Israel* our father, forever and | ever. Yours, O LORD, is the greatness and the power and the glory and the victory and the | majesty,* for all that is in the heavens and in the | earth is yours. Yours is the kingdom, | O LORD,* and you are exalted as head a- | bove all. And now we thank you, | our God,* and praise your | glorious name. Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. O LORD, I love the habitation | of your house* and the place where your | glory dwells.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (632, 6020, 'O', NULL, 'Christian Education', 'Color of the Season', NULL, 'Deut 6:4-15', 'Psalm 119:129-136', 'Acts 2:37-41', 'Luke 18:15-17', '<div>INTROIT Ps. 34:8–10; antiphon: Ps. 34:11 Come, O children, lis- | ten to me;* I will teach you the fear | of the LORD. Oh, taste and see that the | LORD is good!* Blessèd is the man who takes ref- | uge in him! Oh, fear the LORD, | you his saints,* for those who fear him | have no lack! The young lions suffer want and | hunger;* but those who seek the LORD lack | no good thing. Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. Come, O children, lis- | ten to me;* I will teach you the fear | of the LORD.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (633, 6040, 'O', NULL, 'Harvest Observance', 'Color of The Season', NULL, 'Deut 26:1-11', 'Psalm 65', '2 Cor 9:6-15', 'Luke 12:13-21', '<div>INTROIT Ps. 104:24, 14–15; antiphon: Ps. 104:31 May the glory of the LORD endure for- | ever;* may the LORD rejoice | in his works. O LORD, how manifold are your works! In wisdom have you | made them all;* the earth is full of your | creatures. You cause the grass to grow for the livestock and plants for man to | cultivate,* that he may bring forth food from the earth and wine to gladden the | heart of man, oil to make his | face shine* and bread to strengthen | man’s heart. Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. May the glory of the LORD endure for- | ever;* may the LORD rejoice | in his works.</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (634, 6070, 'O', NULL, 'Day of Thanksgiving', 'White', NULL, 'Deut 8:1-10', 'Psalm 67', 'Phil 4:6-20 or 1 Tim 2:1-4', 'Luke 17:11-19', '<div>INTROIT Ps. 104:24, 27–28, 30; antiphon: Ps. 104:33 I will sing to the LORD as long | as I live;* I will sing praise to my God while I have | being. O LORD, how manifold are your works! In wisdom have you | made them all;* the earth is full of your | creatures.</div>\r\n\r\n<div>These all | look to you,* to give them their food in due | season. When you give it to them, they gath- | er it up;* when you open your hand, they are filled with | good things. When you send forth your Spirit, they are cre- | ated,* and you renew the face | of the ground. Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. I will sing to the LORD as long | as I live;* I will sing praise to my God while I have | being.</div>', '<div>Entrance: 892 Come, Ye Thankful People, Come </div>\r\n\r\n<div>Of the Day: 785 We Praise You, O God </div>\r\n\r\n<div>Distribution: </div>\r\n\r\n<div>&nbsp;&nbsp;893 Sing to the Lord of Harvest; </div>\r\n\r\n<div>&nbsp;&nbsp;894 For the Fruits of His Creation </div>\r\n\r\n<div>Closing: 895 Now Thank We All Our God </div>', '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (635, 6080, 'O', NULL, 'Day of Supplication and Prayer', 'Violet', NULL, 'Joel 2:12-19', 'Psalm 6', '1 John 1:5-2:2', 'Matt 6:16-21', '<div>INTROIT Ps. 30:1, 4–5; antiphon: Ps. 30:10 Hear, O LORD, and be merci- | ful to me!* O LORD, be my | helper! I will extol you, O LORD, for you have | drawn me up* and have not let my foes rejoice | over me. Sing praises to the LORD, O | you his saints,* and give thanks to his | holy name. For his anger is but for a moment, and his favor is for a | lifetime.* Weeping may tarry for the night, but joy comes with the | morning. Hear, O LORD, and be merci- | ful to me!* O LORD, be my | helper!</div>', NULL, '');
INSERT INTO `tblPropers` (`ID`, `Sort`, `ABC1`, `Season`, `LiturgicalDate`, `Color`, `Theme`, `FirstReading`, `Psalm`, `Epistle`, `Gospel`, `Introit`, `HymnSug`, `Notes`) VALUES (636, 6090, 'O', NULL, 'Day of National or Local Tragedy', 'Violet', NULL, 'Job 30:16-24 or Rev 7:13-17', 'Psalm 130', 'Rom 8:31-39 or Heb 12:4-13', 'Luke 13:-19 or Matt 24:32-35', '<div>INTROIT Ps. 102:1–3, 11; antiphon: Ps. 102:12 You, O LORD, are enthroned for- | ever;* you are remembered throughout all gener- | ations. Hear my prayer, | O LORD;* let my cry | come to you! Do not hide your face from me in the day of | my distress!* Incline your ear to me; answer me speedily in the day | when I call! For my days pass a- | way like smoke,* and my bones burn like a | furnace. My days are like an evening | shadow;* I wither a- | way like grass. Glory be to the Father and | to the Son* and to the Holy | Spirit; as it was in the be- | ginning,* is now, and will be forever. | Amen. You, O LORD, are enthroned for- | ever;* you are remembered throughout all gener- | ations.</div>', NULL, '');
